const C=(d,stem,options,answer,explain)=>({type:'choice',difficulty:d,stem,options,answer,explain});
const M=(d,stem,options,answers,explain)=>({type:'multi',difficulty:d,stem,options,answers,explain});
const T=(d,stem,answers,explain)=>({type:'text',difficulty:d,stem,answers,explain});
const K=(stem,parts,explain,table)=>({type:'case',difficulty:3,stem,parts,explain,...(table?{table}: {})});
export const physicsUnits9=[];
export const physicsDetails9={};
export const physicsVisuals9={};
let currentUnit;
function unit(number,title,intro){currentUnit={id:`p${number}`,number,title,term:'g9-full',intro,lessons:[]};physicsUnits9.push(currentUnit);}
function add(id,title,goal,points,pitfall,detail,questions,visual){
 const kind=title.startsWith('跨学科实践')?'跨学科实践':'知识与实验';
 currentUnit.lessons.push({id,title,kind,goal,sourceTopic:`人教版（2024审定）九年级全一册 · 第${currentUnit.number}章 · ${title}`,points,pitfall,questions:questions.map((q,i)=>({...q,id:`phy-${id}-${String(i+1).padStart(2,'0')}`}))});
 physicsDetails9[id]={definition:detail[0],plain:detail[1],method:detail[2],worked:detail[3],sections:[{title:'把原理想清楚',body:detail[4]},{title:'实验与迁移',body:detail[5]}]};
 physicsVisuals9[id]=visual;
}
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const text=(x,y,s,size=18,color='#254f49')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}" font-family="system-ui,sans-serif">${esc(s)}</text>`;
const line=(x1,y1,x2,y2,c='#396b64',w=3)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" stroke-width="${w}"/>`;
const arrow=(x1,y1,x2,y2,c='#cf8051')=>{const a=Math.atan2(y2-y1,x2-x1),dx=8*Math.cos(a),dy=8*Math.sin(a),px=5*Math.sin(a),py=5*Math.cos(a);return line(x1,y1,x2,y2,c)+`<path d="M${x2-dx+px},${y2-dy-py} L${x2},${y2} L${x2-dx-px},${y2-dy+py}" fill="none" stroke="${c}" stroke-width="2"/>`;};
const rect=(x,y,w,h,fill='#e8f2ed')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="9" fill="${fill}" stroke="#47736b" stroke-width="2"/>`;
function V(title,inside,caption){return {title,svg:`<svg class="lesson-diagram" viewBox="0 0 760 330" role="img" aria-label="${esc(title)}"><rect width="760" height="330" rx="18" fill="#f6faf7"/>${inside}</svg>`,caption};}
function flowVisual(title,labels,caption){return V(title,labels.map((s,i)=>rect(30+i*183,100,160,96)+text(45+i*183,140,s,17)+(i<labels.length-1?arrow(192+i*183,148,208+i*183,148):'')).join('')+text(32,270,caption.slice(0,42),15),caption);}
function thermalVisual(mode='heat'){
 if(mode==='particles')return V('温度与分子运动',text(60,42,'较低温度')+text(430,42,'较高温度')+[60,430].map((x,j)=>rect(x,66,260,185)+Array.from({length:10},(_,i)=>{let px=x+25+(i%4)*61,py=96+Math.floor(i/4)*57;return `<circle cx="${px}" cy="${py}" r="8" fill="${j?'#dc956b':'#498f87'}"/>`+arrow(px+9,py,px+22+j*16,py+(i%2?5:-5));}).join('')).join('')+text(67,294,'箭头表示分子运动方向；长度示意运动快慢',17),'分子一直无规则运动。图中不是分子真实比例，也不是宏观气流；升温使分子运动整体更剧烈。');
 if(mode==='energy')return V('改变内能的两种方式',rect(278,100,198,94)+text(312,154,'物体的内能')+arrow(30,145,270,145)+text(38,116,'热传递：能量转移')+arrow(710,145,485,145)+text(489,115,'外界做功：能量转化')+text(95,253,'温差是热传递条件；做功也能使内能改变',19),'暖手袋向手传热；摩擦双手做功。两种方式都能改变内能，但过程不同。');
 return V('等质量物质的吸热升温比较',line(92,252,680,252)+line(92,252,92,47)+text(635,282,'热量 Q')+text(30,40,'温升 Δt')+line(92,252,560,72,'#cc8055')+line(92,252,650,165,'#397e75')+text(482,76,'油：斜率较大',17,'#b66435')+text(506,154,'水：比热容大',17)+line(425,252,425,121,'#a8b5ac',1)+text(264,304,'相同质量、相同吸热：比热容越大，温升越小',17),'此图为无物态变化、比热容近似不变的模型。纵轴是温升，不能把起始温度混入比较。');
}
function engineVisual(title='四冲程汽油机') {return V(title,['吸气','压缩','做功','排气'].map((s,i)=>{let x=32+i*185;return rect(x,73,140,151)+rect(x+15,145+(i===1?-26:0),110,20,'#b6c9c0')+line(x+70,166+(i===1?-26:0),x+70,250)+text(x+45,48,s)+text(x+8,279,i===2?'内能→机械能':i===1?'机械能→内能':i===0?'吸入混合气':'排出废气',15);}).join(''),'四个冲程中做功冲程向外提供机械能。一个工作循环，曲轴转两周，通常对外做功一次。');}
unit(13,'内能','从热量和比热容走向微观分子运动，分清温度、内能与热量。');
add('p13-1','热量 比热容','用控制变量实验理解比热容，并完成吸热、放热与混合问题。',[
'热量是热传递过程中转移能量的多少，单位为焦耳；物体不“含有热量”。','比热容表示单位质量某物质温度升高1 ℃吸收的热量，单位J/(kg·℃)。','没有物态变化时，Q=cmΔt；放热量使用初温减末温得到正温差。','等质量、吸收相同热量时，比热容大的物质温升小；水的比热容约4.2×10³ J/(kg·℃)。','比较吸热能力应控制质量、加热条件，用加热时间近似比较吸热量。'
],'温度高不等于热量多；沸腾吸热但温度不变，不能用Q=cmΔt计算汽化热。',[
'热量描述因温度差而转移的能量，国际单位是焦耳，符号J。单位质量的某种物质温度升高1 ℃所吸收的热量，用比热容表示，符号c。在物态保持不变且比热容可近似看作常量时，吸放热计算用Q=cmΔt。比热容是物质的一种特性，与样品质量多少不同。',
'想象同样质量的水和食用油坐上相同的“加热电梯”。送进同样多能量，油的温度往往升得更高，水升得较慢。水不是没有吸收能量，而是每升高一度需要更多能量。海边昼夜温差通常较小，冷却系统常用水，都与水较大的比热容有关；但实际环境还同时受风、蒸发等因素影响。',
'计算先写清研究对象，再统一质量为kg、温差为℃。升温用末温减初温，降温用初温减末温。比较实验有两条路线：相同质量、相同加热时间，比较温升；或者相同质量、相同温升，比较所需时间。前提是加热功率及散热条件可比，不能把“同样的酒精灯”直接等同于热量绝对相同。',
'把0.50 kg水由20 ℃加热到60 ℃，温升40 ℃，吸热为4.2×10³×0.50×40=8.4×10⁴ J。若同质量油比热容为2.1×10³ J/(kg·℃)，吸收同样热量时温升80 ℃。这里比较的是温度的变化，不是末温的比值；初温不同也不能直接拿末温大小判断比热容。',
'混合冷热水时，能量从高温水转移到低温水。在容器吸热和散热都可忽略的模型中，热水放出的热量等于冷水吸收的热量。相同物质混合可用m热(t热−t)=m冷(t−t冷)。只有两者质量相同，平衡温度才是两个初温的平均值，质量不同要按吸放热守恒求解。',
'实验记录应含质量、初温、每段加热时间和温度，搅拌有助于温度均匀，温度计玻璃泡不碰杯底。绘制温升—热量图时，质量相同的曲线越陡，表示比热容越小。如果出现持续吸热却温度不变的段，应检查是否发生物态变化；这一阶段能量仍然转移，但原来的升温公式不再适用。'
],[
C(1,'下列说法中正确的是？',['物体含有很多热量','热量是热传递过程中转移的能量','温度就是热量','比热容随质量增大而增大'],1,'热量是过程量，不能说物体含有热量。'),
C(1,'比热容的单位是？',['J','J/(kg·℃)','kg/m³','W'],1,'比热容描述单位质量、单位温升需要的热量。'),
C(1,'同种水分成两杯，质量不同。相同条件下比热容如何？',['大杯较大','小杯较大','相同','由容器颜色决定'],2,'比热容是物质特性。'),
C(1,'水从50 ℃降到20 ℃，放热计算中的温差为？',['70 ℃','−30 ℃','30 ℃','2.5 ℃'],2,'放热量用初温减末温，为30 ℃。'),
M(2,'比较两种液体的比热容，合理的措施有？',['取相同质量','使用相同功率加热器并控制散热条件','只比较最终温度而不记录初温','搅拌使温度均匀'],[0,1,3],'应比较温升而不是只看最终温度。'),
M(2,'关于热量计算正确的有？',['质量要与比热容单位配套','无物态变化时可用Q=cmΔt','沸腾时温度不变，所以不吸热','水比热容大可用于冷却'],[0,1,3],'沸腾需要吸热，公式不能用于汽化热。'),
T(2,'0.20 kg水温升10 ℃，c=4200 J/(kg·℃)，吸热多少J？只填数值。',['8400'],'Q=4200×0.20×10=8400 J。'),
T(2,'0.50 kg某液体吸热10000 J，升温10 ℃，比热容多少J/(kg·℃)？',['2000'],'c=Q/(mΔt)=2000。'),
C(2,'等质量水和油吸收相同热量，油温升大，说明？',['油比热容小','油质量大','水没有吸热','两者比热容相同'],0,'c与温升成反比的比较必须固定质量和热量。'),
C(2,'质量相同的水与铜降温相同，c水>c铜，放热较多的是？',['铜','水','一样','无法比较'],1,'Q=cmΔt。'),
C(3,'1 kg、80 ℃的水和3 kg、20 ℃的水混合，无热损失，末温是？',['50 ℃','35 ℃','40 ℃','30 ℃'],1,'1(80−t)=3(t−20)，t=35 ℃。'),
C(3,'等质量A、B液体用相同功率加热，升高同样温度分别用3 min、5 min，忽略散热，cA:cB为？',['5:3','3:5','9:25','1:1'],1,'Q与时间成正比，同m同Δt，c与时间成正比。'),
C(3,'相同加热器加热液体，后期温升变慢且未沸腾，最合理的可能原因是？',['比热容必定减少','向环境散热增加','能量不守恒','质量必定增大'],1,'温差增大往往使散热增强，净吸热功率下降。'),
T(3,'2 kg水由80 ℃冷却到30 ℃，c=4200 J/(kg·℃)，释放热量多少kJ？',['420'],'4200×2×50=420000 J=420 kJ。'),
C(3,'水与油的Q—Δt图线中，在质量相同时水图线斜率更大，横轴Δt、纵轴Q，原因是？',['c水较大','c水较小','水初温更高','斜率无物理意义'],0,'Q/Δt=cm，固定质量时斜率越大，比热容越大。'),
K('相同功率加热器分别加热0.20 kg液体甲、乙，均无物态变化且忽略热损失。甲的比热容为4200 J/(kg·℃)。',[['甲升温多少℃？',['20']],['甲吸收热量多少J？',['16800']],['乙比热容多少J/(kg·℃)？',['2100']]],'两者加热时间相同，吸热相同。甲温升20 ℃，Q=16800 J；乙温升40 ℃，c乙=16800/(0.2×40)=2100。',{headers:['液体','初温/℃','末温/℃','加热时间/s'],rows:[['甲','20','40','120'],['乙','20','60','120']]})
],thermalVisual());
add('p13-2','分子动理论的初步知识','用微观模型解释扩散、分子间作用力，并区分宏观运动。',[
'物质由大量分子、原子等微观粒子组成，粒子间有空隙。','不同物质互相接触进入对方的现象叫扩散，体现分子不停地做无规则运动。','温度越高，分子的热运动越剧烈；固体、液体、气体都可发生扩散。','分子间同时存在引力和斥力，距离不同，两者表现不同。','尘埃飘动、烟雾上升是微粒或空气的宏观运动，不能直接当作分子运动。'
],'“分子间有空隙”不等于物质中没有相互作用；温度升高是运动更剧烈，不是分子本身膨胀。',[
'分子动理论的初步内容包括：物质由大量分子、原子等粒子构成；分子永不停息地做无规则运动；分子之间存在相互作用力。不同物质在彼此接触时互相进入对方的现象称为扩散。分子的无规则运动与温度有关，因此也称为热运动。',
'把香水瓶打开，远处也能闻到气味，是一些气味分子离开液体并在空气中扩散到鼻子。肉眼看不到这些分子，闻到气味是间接证据。相比之下，看得见的烟尘颗粒包含极多分子，它们随空气移动是宏观运动。现象可以同时含有扩散和空气对流，分析时要分清要证明的是哪一层运动。',
'判断实验结论先看变量。例如两杯等量水只改变水温、同时轻轻滴入同量色素，温度较高的一杯颜色分布更快，支持热运动与温度有关。若同时搅拌一杯、不搅拌另一杯，就不能单独证明温度的影响。观察液体分层实验时，应尽量避免振动和搅拌，减少宏观混合的干扰。',
'将50 mL水与50 mL酒精混合，实际总体积可以小于100 mL。这不能说质量减少了，而是微观粒子间的空隙及排列发生改变；在封闭容器且无洒漏时，总质量仍等于混合前质量之和。体积通常不能简单相加，质量在这种混合中可以相加，这是两种物理量的差别。',
'分子间引力和斥力通常同时存在。分子相距很近时斥力表现突出，所以固体和液体难以压缩；适当拉开时引力表现突出，使物质不轻易散开。固体难以拉伸不能解释为“只有引力”，难以压缩也不能解释为“只有斥力”。气体分子平均间距较大，压缩首先减小间距，所以较容易压缩。',
'把接触面打磨平整且洁净的铅柱紧压，可能连接在一起，说明在十分接近时分子间引力可以表现出来。普通两块木板不粘合，并不能推翻分子引力，而是表面粗糙使多数分子相距太远。学会从观察走到证据，再到模型，同时说明模型的适用尺度，是本节比背结论更重要的能力。'
],[
C(1,'以下最能说明扩散的是？',['香气逐渐传到远处','汽车行驶','纸片被风吹走','河水向下流'],0,'气味分子扩散与宏观物体运动不同。'),
C(1,'分子热运动的特点是？',['仅受热时存在','永不停息且无规则','方向始终相同','只有气体分子运动'],1,'三态中的分子均做热运动。'),
C(1,'温度升高时，分子的热运动总体怎样？',['更剧烈','停止','变为有规则','分子质量增大'],0,'温度反映热运动的剧烈程度。'),
C(1,'固体很难压缩，主要说明分子间存在？',['斥力','只有重力','没有空隙','磁力'],0,'距离很小时分子间斥力表现突出。'),
M(2,'属于对分子模型合理理解的有？',['分子间存在空隙','固体中也有分子热运动','分子只有受热后才运动','分子间可同时有引力和斥力'],[0,1,3],'热运动不以外界正在加热为条件。'),
M(2,'比较冷热水中扩散快慢，应控制哪些条件相同？',['水的体积','色素滴数','水的初温','是否搅拌'],[0,1,3],'初温是本实验主动改变的变量。'),
T(2,'水和酒精混合后总体积小于原体积之和，主要说明分子间有________。',['空隙','间隙'],'分子排列和空隙改变使体积不简单相加。'),
T(2,'“温度越高，分子运动越剧烈”中的运动叫分子的________。',['热运动','无规则运动'],'分子的无规则运动与温度有关。'),
C(2,'可见的灰尘在阳光下飘动，能否直接说是单个分子热运动？',['能，因为灰尘很小','不能，灰尘含大量分子','能，因为运动慢','只有白色灰尘可以'],1,'肉眼可见颗粒并不是单个分子。'),
C(2,'气体比液体更容易压缩，主要是因为？',['气体分子更软','气体分子平均间距大','气体没有质量','气体不含分子'],1,'压缩主要减小粒子间距。'),
C(3,'两块粗糙玻璃不粘合，不能否定分子引力，因为？',['引力从不存在','多数表面分子距离未达到有效作用尺度','玻璃不含分子','引力只能在液体中出现'],1,'微观作用需分子十分接近。'),
C(3,'热水中色素散开快，但热水组还被搅拌，结论的主要缺陷是？',['两个变量同时变化','没有温度计一定无效','不允许做液体实验','色素不是物质'],0,'温度和搅拌都能影响宏观混合，不能归因唯一。'),
C(3,'金属热胀时，合理的微观描述是？',['原子个数增多','分子本身明显变大','粒子平均间距通常增大','质量变多'],2,'通常热膨胀与平均间距变化有关。'),
T(3,'密闭无泄漏容器内有50 g水和40 g酒精，混合体积缩小后总质量多少g？',['90'],'混合没有物质逸出，质量为50+40=90 g。'),
C(3,'两铅柱压紧后能承重，主要支持哪项推断？',['分子间可有引力','分子完全不运动','重力消失','任何粗糙表面都能粘牢'],0,'该证据支持近距离分子引力，不能推出其他无限扩大结论。'),
K('把同样大小的色素滴分别滴入两杯水，不搅拌，记录达到近似均匀颜色的时间。除水温外其他条件相同。',[['哪杯水的扩散较快？填甲或乙。',['乙']],['实验中主要改变的物理量是什么？',['温度','水温']],['这种比较方法叫什么？',['控制变量法','控制变量']]],'乙温度高、颜色均匀所需时间短。固定质量、容器和色素用量，改变水温，使用控制变量法。',{headers:['水杯','水温/℃','近似均匀所需时间/s'],rows:[['甲','20','240'],['乙','60','90']]})
],thermalVisual('particles'));
add('p13-3','内能','区分内能与机械能，解释做功、热传递及温度不变时的能量变化。',[
'物体内所有分子热运动的动能与分子势能的总和，称为物体的内能。','任何温度的物体都有内能，0 ℃不是内能为零。','内能与温度、物质的量、状态等有关，不能只按温度比较不同物体的内能。','热传递和做功都可改变内能；前者是能量转移，后者可发生能量转化。','温度不变不等于内能不变，熔化、沸腾过程中吸热可增加内能。'
],'“热量、温度、内能”分别描述过程、冷热程度与状态能量；静止物体也有内能。',[
'物体内部所有分子热运动的动能与分子势能的总和，叫作物体的内能。这里研究的是构成物体的微观粒子，而物体整体运动的动能、整体所处位置的重力势能属于机械能。两种能量可以相互转化，但不能因为物体整体静止，就断言它没有内能。',
'同一杯水温度升高时，分子运动整体更剧烈，内能一般增加。但比较一杯热水和一桶温水，不能只看哪个温度高，因为一桶水包含更多分子。内能还与物体质量、物质种类、物态等有关。0 ℃的冰也有分子运动和相互作用，所以内能不是零；我们日常说“冷”并不代表没有能量。',
'判断改变内能的方式，要看能量怎样跨过研究对象的边界。把热水袋放在手上，能量因温差从热水袋转移到手，是热传递。来回搓手、给打气筒压气，使机械能转化为内能，是做功。两者从改变内能的效果看可以等效，但实际过程不同，不能把一切温度上升都叫吸收热量。',
'密闭容器中的气体吸收热量100 J，同时外界对它做功40 J，若无其他能量交换，气体内能增加140 J。若气体吸收100 J，却推动活塞对外做功40 J，内能只增加60 J。先画出能量进入和离开的箭头，再做加减，比死记正负号更不容易错。',
'冰在熔点熔化时持续吸热而温度保持不变，分子间的排列和相互作用状态变化，因此内能仍会增加。类似地，水在沸腾时温度可以不变，却需要吸热。这说明温度并非内能的完整刻度尺，也说明“吸热一定升温”和“升温一定吸热”都是过度概括。',
'用瓶塞被压缩气体推出的实验解释能量时，研究对象是气体：气体膨胀对外做功，内能可减少，温度降低。若看到白雾，通常是空气中的水蒸气遇冷液化成小液滴，不是“看见了水蒸气”。实验中要把观察到的塞子运动、雾滴形成与推断的能量变化逐步联系起来。'
],[
C(1,'静止在桌上的冰块有内能吗？',['没有','有','只有融化后才有','只有运动后才有'],1,'内部粒子仍做热运动。'),
C(1,'下列通过做功改变内能的是？',['晒太阳','用热水暖手','摩擦双手','放入冰箱降温'],2,'摩擦把机械能转化为内能。'),
C(1,'内能中的动能指？',['物体整体运动的动能','内部粒子热运动的动能','地球公转动能','只指电能'],1,'需区分微观与宏观层次。'),
C(1,'热传递自发发生时能量通常从？',['低温到高温','高温到低温','小质量到大质量','低处到高处'],1,'温差决定热传递方向。'),
M(2,'正确的说法有？',['0 ℃冰有内能','内能变化可通过做功实现','温度高的物体内能一定更多','熔化吸热时内能可增加'],[0,1,3],'内能还与质量、物态等有关。'),
M(2,'属于热传递改变内能的有？',['热汤中的勺子变热','暖气使房间变暖','压缩空气升温','锯木头锯条变热'],[0,1],'压缩和摩擦主要属于做功。'),
T(2,'物体吸热200 J，且无做功及其他能量交换，内能增加多少J？',['200'],'全部输入能量成为内能增量。'),
T(2,'气体绝热膨胀对外做功60 J，内能减少多少J？',['60'],'没有热交换，对外做功来自内能。'),
C(2,'同一杯水升温且物态不变，内能通常？',['增加','减少','不变','为零'],0,'分子热运动更剧烈。'),
C(2,'一桶20 ℃水与一滴80 ℃水相比，仅凭温度能否判断总内能？',['能，80 ℃一定更多','不能，质量等也有关','20 ℃必为零','两者必相同'],1,'总内能不是温度单变量函数。'),
C(3,'物体吸热后温度不变，可能发生？',['熔化','机械能必为零','内能不变','分子停止运动'],0,'熔化时吸热可改变分子势能。'),
C(3,'密闭气体吸热80 J，又对外做功30 J，内能变化为？',['增加110 J','增加50 J','减少50 J','减少110 J'],1,'进入80，输出30，净增50 J。'),
C(3,'压缩空气可使其升温，说明？',['升温必须吸热','做功可以改变内能','热量储存在空气中','只有空气有内能'],1,'机械能转化为内能。'),
T(3,'物体向外放热120 J，同时外界对它做功200 J。内能净增加多少J？',['80'],'净输入200−120=80 J。'),
C(3,'开车急刹后刹车盘变热，合理能量链是？',['内能→汽车动能','汽车动能→部分刹车盘等内能','质量→温度','热量→质量'],1,'摩擦做功使机械能转化为内能。'),
K('密闭气体经历两个过程：A中外界对它做功150 J，同时它向外放热50 J；B中吸热80 J，同时对外做功120 J。',[['A中内能增加多少J？',['100']],['B中内能减少多少J？',['40']],['两个过程合计内能增加多少J？',['60']]],'A净输入150−50=100 J；B净输出120−80=40 J；合计增加60 J。')
],thermalVisual('energy'));
unit(14,'内能的利用','沿能量转化主线理解热机、效率、燃料与热机模型。');
add('p14-1','能量的转化与守恒','追踪能量流向，理解能量守恒与能量利用的方向性。',[
'能量有机械能、内能、电能、化学能、光能等多种形式。','能量可以在物体之间转移，也可以从一种形式转化为另一种形式。','能量既不会凭空产生，也不会凭空消失；在转化和转移过程中总量保持不变。','有用能量与其他去向的能量相加等于输入能量，研究时应明确系统边界。','能量利用存在方向性；能量守恒不意味着可以无条件无限循环利用。'
],'“损失的能量”通常转移到周围环境或转成不易利用的内能，没有消失。',[
'能量可以从一种形式转化成其他形式，也可以从一个物体转移到另一个物体。在这些过程中，能量的总量保持不变，这就是能量守恒定律。所谓“守恒”是把全部相关物体和全部能量形式都计入后得到的结论，不是只观察一个物体便要求它的能量始终相同。',
'手机充电时，电能主要转化为电池的化学能，同时手机和充电器发热。用电池点灯时，化学能再转为电能，最后转为光和内能。若只计算灯发出的光，似乎少了很多能量；把散入空气、外壳、导线的内能一起计入，就会发现能量有去向，没有凭空消失。',
'画能量图时，先定边界，再写输入、期望输出和其他输出。例如对一台电动机，输入电能，期望输出机械能，同时产生热。列账时各能量统一单位，满足输入=有用输出+其他输出+系统内能量增加。若系统温度不断升高，不能漏掉储存在系统中的那部分能量。',
'某小电动机消耗电能1000 J，对重物做功600 J，忽略其他形式的储存，剩余400 J转化为电动机和周围环境的内能。这里可说有效利用的比例为60%，不能说“只守恒了60%”。守恒关系针对全部能量，而有效利用比例针对人们希望得到的那一部分。',
'能量守恒并不能保证任何想象中的装置都能实现。例如滚动的小球最终停下，机械能主要变成分散的内能；要让这些分散的内能自发全部集中回来使小球恢复运动，并不会自然发生。燃料、风能、太阳能等资源的可获取性、能量品质和转换条件都影响可用程度，所以节约能源仍有意义。',
'评价声称“永远发电且无需任何能量输入”的装置，应追问电从哪里来，内部电池是否在放电，有无外部光照、风力或温差。测量输入输出需保持同一时间段与系统边界，不能拿短时释放储能的输出与此刻很小的输入比较。科学解释要能对应可测量的能量账目，而不靠漂亮的机械结构图。'
],[
C(1,'太阳能电池板主要完成什么转化？',['电能→光能','太阳能→电能','内能→质量','机械能→核能'],1,'光伏把太阳辐射能转化为电能。'),C(1,'能量守恒是指？',['每个物体温度不变','全部相关能量总量不变','有用能量永远不减少','不能发生能量转化'],1,'守恒允许各种转化和转移。'),C(1,'电池给灯供电，电池主要提供？',['化学能','重力势能','核能','声能'],0,'电池通过化学反应供电。'),C(1,'摩擦后机械能减少，能量通常？',['消失','转化为内能等','变成没有质量的物质','证明不守恒'],1,'机械能可转化为内能。'),M(2,'下列能量链正确的有？',['电热水壶：电能→内能','电动机：电能→机械能','发电机：机械能→电能','燃料燃烧：内能→化学能'],[0,1,2],'燃烧主要把化学能转化为内能。'),M(2,'分析能量账本应注意？',['明确研究系统','统一能量单位','只统计有用输出','考虑能量储存变化'],[0,1,3],'其他输出也必须统计。'),T(2,'输入电能500 J，输出有用机械能350 J，剩余全部转为内能。内能增加多少J？',['150'],'500−350=150 J。'),T(2,'电动机输入2000 J，有用输出1200 J，有效利用百分比为多少？',['60%'],'1200/2000=60%。'),C(2,'“能量损失”较准确的意思是？',['总能量不守恒','能量去了非期望用途或环境','质量必然减少','能量变为零'],1,'日常损失指难以有效利用的部分。'),C(2,'小球落地后弹起高度变低，主要因为？',['重力消失','机械能部分转为内能和声音','总能量减少','小球没有能量'],1,'碰撞和空气阻力造成机械能转化。'),C(3,'装置短时间输出功率大于外部输入功率，首先还应检查？',['是否释放内部储能','是否违反乘法','输出肯定为假','必须停止测量'],0,'储能变化可以使短时输出大于即时输入。'),C(3,'能量守恒仍要节约能源，合理原因是？',['能量会消失','易利用的能源有限且转化有方向性','所有能量都不可用','太阳没有能量'],1,'能量数量守恒不等于能源品质和可获取性不变。'),C(3,'系统输入100 J，输出70 J，则系统储能变化为？',['增加30 J','减少30 J','增加170 J','不变'],0,'ΔE=100−70。'),T(3,'装置初储能500 J，接受300 J，向外输出650 J，末储能多少J？',['150'],'500+300−650=150 J。'),C(3,'判断无输入持续发电的机器不可靠，最直接根据是？',['外形太复杂','与能量守恒冲突且未给出能源','颜色不正确','速度太慢'],1,'持续输出需要输入或消耗储存的能量。'),K('某装置一个工作周期电能输入2000 J，机械能输出1100 J，向环境放热600 J。',[['系统内储能增加多少J？',['300']],['机械能输出占输入的百分比是多少？',['55%']],['若后续再向环境释放300 J且无其他交换，储能相对最初是否恢复？填是或否。',['是']]],'输入2000=机械1100+散热600+储能300。机械输出55%；再释放300 J后储能恢复初始。')
],flowVisual('能量账本',['输入能量','有用输出','散热等输出','储能变化'],'输入能量 = 各项输出能量 + 系统储能增加量'));
add('p14-2','热机','解释汽油机、柴油机的工作循环与内能转化。',[
'热机利用内能做功，将一部分内能转化为机械能。','四冲程汽油机通常经历吸气、压缩、做功、排气四个冲程。','压缩冲程对气体做功，机械能转化为内能；做功冲程高温高压燃气推动活塞。','一个四冲程工作循环中曲轴转两周，活塞往复两次，对外做功一次。','汽油机通常用火花塞点火，柴油机靠压缩后的高温空气使喷入燃料着火。'
],'飞轮惯性帮助完成其他冲程；不能把每一次活塞运动都当作做功冲程。',[
'热机是利用内能做功的机械。燃料燃烧先使工作物质获得较高内能，工作物质膨胀推动活塞或叶轮，把一部分内能转化为机械能。常见内燃机让燃料在气缸内燃烧，汽油机与柴油机都是例子，但它们的混合、点火方式以及结构细节存在区别。',
'可把四冲程理解为一套完整呼吸和发力动作：吸入、压紧、推动、排出。吸气阶段进气门开，活塞下行；压缩阶段两气门关，活塞上行；做功阶段高温高压燃气膨胀，活塞下行；排气阶段排气门开，活塞上行。只有做功冲程主要向外输出机械能，其他冲程靠飞轮惯性或其他气缸带动。',
'读图先看气门是否打开，再看活塞方向。有气门打开时，进气门开且下行是吸气，排气门开且上行是排气；两气门都关时，上行一般是压缩，下行一般是做功。分析能量转化只在恰当环节使用：压缩是机械能转为内能，做功是内能转为机械能，燃烧则主要是化学能转为内能。',
'一台单缸四冲程汽油机转速为2400 r/min，每秒曲轴转40周。每两周完成一个循环，所以每秒20个循环，也就是每秒做功20次。若每次做功50 J，输出功率为20×50=1000 W。务必先把每分钟换成每秒，并明确单缸条件，不能直接把曲轴转数当作做功次数。',
'汽油机通常吸入空气和汽油的混合气，压缩末由火花塞点燃。柴油机通常吸入空气，压缩使空气温度很高，再喷入柴油而着火。两者都需要空气中的氧气参与燃烧，也都不能将释放的全部能量变为有用机械能。比较两者时不要仅凭“有无火花塞”猜一切性能，应依据题目给定条件。',
'实验模型可用安全的低温差装置展示气体受热膨胀做功。真实发动机存在高温、高压、润滑和冷却问题，不能靠密封易碎容器加热模仿。观察模型转动时还需说明能量来源：外部热源提供能量，气体状态循环变化并推动机构；模型看起来不停转动并不意味着无需能量输入。'
],[
C(1,'热机的主要有用能量转化是？',['内能→机械能','机械能→电能','光能→化学能','电能→核能'],0,'热机利用内能对外做功。'),C(1,'四冲程中主要对外做功的是？',['吸气','压缩','做功','排气'],2,'高温高压燃气推动活塞。'),C(1,'压缩冲程中主要能量转化为？',['内能→机械能','机械能→内能','光能→电能','无变化'],1,'外界对气体做功。'),C(1,'一个四冲程循环曲轴通常转几周？',['1','2','4','8'],1,'四个冲程对应两周。'),M(2,'四冲程汽油机的描述正确的有？',['吸气时进气门打开','压缩时两气门关闭','排气时排气门打开','每个冲程都燃烧做功'],[0,1,2],'通常只有做功冲程输出有用机械能。'),M(2,'汽油机和柴油机比较正确的有？',['两者都是热机','柴油机通常压燃','汽油机通常火花塞点火','两者都把全部热量变为功'],[0,1,2],'热机总有未变为有用功的能量。'),T(2,'单缸四冲程机每秒曲轴转60周，每秒做功多少次？',['30'],'两周做功一次。'),T(2,'单缸四冲程机每秒做功15次，曲轴转速多少r/min？',['1800'],'15×2×60=1800 r/min。'),C(2,'两气门都关闭、活塞上行，通常是什么冲程？',['吸气','压缩','排气','无法确定任何过程'],1,'闭门上行压缩缸内气体。'),C(2,'飞轮的重要作用是？',['凭空产生能量','依靠惯性帮助完成其他冲程','使燃料不需氧气','使效率达到100%'],1,'飞轮储存和释放机械能，使转动较平稳。'),C(3,'单缸机转速3000 r/min，每次做功40 J，功率为？',['1000 W','2000 W','120000 W','500 W'],0,'每秒50周、25次做功，P=25×40=1000 W。'),C(3,'吸入空气，压缩末喷入燃料后燃烧，较符合？',['柴油机','汽油机火花点火过程','电动机','太阳能电池'],0,'描述了压燃方式。'),C(3,'燃料燃烧与气体做功两个步骤的能量链是？',['机械→内→化学','化学→内→机械','内→化学→电','电→核→机械'],1,'先燃烧释放内能，再对外做功。'),T(3,'单缸机输出1200 W，每次做功60 J，曲轴转速多少r/min？',['2400'],'每秒做功1200/60=20次，曲轴40周/s=2400 r/min。'),C(3,'发动机关闭供油后飞轮还转片刻，原因主要是？',['仍有无限能源','惯性及已储机械能','没有摩擦','能量不守恒'],1,'飞轮靠惯性继续运动，能量逐渐耗散。'),K('单缸四冲程汽油机曲轴转速1800 r/min，每次做功80 J，稳定工作10 s。',[['每秒做功多少次？',['15']],['10 s输出机械能多少J？',['12000']],['输出功率多少W？',['1200']]],'1800/60=30周/s；做功15次/s；10 s共150次，W=150×80=12000 J，P=1200 W。')
],engineVisual());
add('p14-3','热机的效率','综合燃料热值、热量、机械功与效率计算。',[
'燃料完全燃烧放出的热量与其质量之比称为热值，单位通常J/kg；气体也可用J/m³。','完全燃烧放热Q放=mq或Vq，必须根据热值单位选择质量或体积。','热机效率是用来做有用功的能量与燃料完全燃烧放出热量之比。','η=W有用/Q放；不完全燃烧、废气、散热、摩擦等影响有效利用。','提高热机效率要减少无用能量输出，不能把热值与效率混为一谈。'
],'实际燃烧不充分不改变燃料本身的热值，但会使实际放热少于按完全燃烧计算的值。',[
'热值描述某种燃料完全燃烧时能够释放多少能量。按质量定义时，1 kg燃料完全燃烧放出的热量在数值上等于其热值，单位为J/kg。热机效率则描述释放的能量中有多少比例成为有用机械功。热值对应燃料特性，效率对应机器及工作条件，两个概念不能互相替代。',
'把燃料提供的能量想成一笔总预算，汽车向前行驶得到的机械能只是其中一项。高温废气带走能量，发动机和冷却水吸收能量，内部摩擦也消耗机械能。人们称这些为损失，是指未成为需要的输出，不是能量消失。提高效率可以少用燃料完成同样运输任务，但不能靠提高效率改变燃料热值。',
'题目通常有三层：先用Q放=mq算燃料账，再用W=Fs或Pt算有用输出，最后用η=W/Q放联系。若燃料用于加热水，用cmΔt得到水真正吸收的热量，效率就应取Q水/Q放。看清“有用”的对象，别在热机题里把冷却水吸热当成机械功。',
'汽车消耗0.20 kg汽油，热值4.6×10⁷ J/kg，完全燃烧释放9.2×10⁶ J。若输出机械功2.76×10⁶ J，效率为30%。若保持效率不变，要获得5.52×10⁶ J机械功，需0.40 kg汽油。计算用30%=0.30代入，不能把30直接放到分母。',
'把发动机总能量绘成比例图可帮助核对：有用功30%、废气35%、冷却与散热25%、其他10%，总和100%。提高某项回收率后也要重新计算总输出。例如把原废气能量的20%进一步回收，并不意味着总效率增加20个百分点，而是增加35%×20%=7个百分点。',
'评价新技术时，应比较相同任务和相似工况。小车总耗油少可能只是行程短，不能证明效率高；同样机械功耗油少，且燃料热值相同，才支持效率较高。热机性能还与排放、维护、成本等有关。本节所有简单计算都以题目给定热值、稳定效率和可忽略其他储能变化为模型条件。'
],[
C(1,'汽油热值4.6×10⁷ J/kg表示？',['1 kg汽油完全燃烧释放相应热量','1 kg汽油温度升高相应度数','发动机效率固定','汽油越多热值越大'],0,'热值按单位质量完全燃烧定义。'),C(1,'热机效率公式是？',['Q放/W','W有用/Q放','m/q','Q放/W×100 J'],1,'效率是无量纲比值。'),C(1,'一桶汽油用去一半，剩余汽油热值通常？',['减半','加倍','不变','为零'],2,'热值不由总质量决定。'),C(1,'热机废气带走能量意味着？',['能量消失','部分能量未用于有用功','燃料没有燃烧','违反守恒'],1,'能量转移到环境。'),M(2,'有助于提高热机有效利用率的措施有？',['减少机械摩擦','合理回收废气余热','让燃料燃烧更充分','宣称燃料热值随效率增加'],[0,1,2],'热值与机器效率不同。'),M(2,'计算燃料放热应注意？',['气体热值若为J/m³应乘体积','质量热值为J/kg应乘kg数','不完全燃烧时实际放热可能较少','把效率直接当作热值'],[0,1,2],'单位决定公式中的量。'),T(2,'0.10 kg燃料热值3×10⁷ J/kg，完全燃烧放热多少J？',['3000000','3×10^6','3e6'],'Q=mq=3×10⁶ J。'),T(2,'热机输入燃料能量2000 J，有用功600 J，效率多少？',['30%'],'600/2000=30%。'),C(2,'燃料没有烧尽，关于热值和实际放热正确的是？',['热值降低','热值不变，实际放热可能较少','实际放热更多','效率必为100%'],1,'热值定义仍以完全燃烧为准。'),C(2,'同种燃料完成相同机械功，甲耗油更少，则甲效率？',['较高','较低','必相同','等于热值'],0,'有用功相同而输入能量较少，效率较高。'),C(3,'燃气热值4×10⁷ J/m³，烧0.0105 m³，以50%效率将1 kg水从20 ℃加热，c=4200，水温升多少℃？',['50','100','200','25'],0,'有效热量0.5×0.0105×4×10⁷=210000 J，Δt=50 ℃，末温70 ℃，没有物态变化。'),C(3,'发动机40%能量经废气损失，回收其中25%转为额外有用功，效率增加多少个百分点？',['25','40','10','65'],2,'增加0.40×0.25=0.10。'),C(3,'车匀速行驶10 km，牵引力500 N，耗燃料0.5 kg，q=4×10⁷ J/kg，效率为？',['25%','50%','40%','10%'],0,'W=500×10000=5×10⁶ J；Q=2×10⁷ J，η=25%。'),T(3,'输出机械功6×10⁶ J，效率30%，燃料q=4×10⁷ J/kg，需燃料多少kg？',['0.5','0.50'],'m=W/(ηq)=0.5 kg。'),C(3,'比较两车效率，最有说服力的数据是？',['车漆颜色','同热值燃料完成相同有用功的耗量','油箱大小','车灯亮度'],1,'必须控制燃料能量及有用任务。'),K('用燃气加热2 kg水，由20 ℃升至70 ℃，c水=4200 J/(kg·℃)，耗燃气0.020 m³，q=3×10⁷ J/m³。',[['水吸收热量多少J？',['420000']],['燃气完全燃烧放热多少J？',['600000']],['加热效率多少？',['70%']]],'Q水=4200×2×50=420000 J；Q燃=0.02×3×10⁷=600000 J；η=70%。')
],flowVisual('热机能量分配',['燃料化学能','燃气内能','有用机械功','废气与散热'],'效率 = 有用机械功 ÷ 燃料完全燃烧放热'));
add('p14-4','跨学科实践：制作简易热机模型','用可控制的模型验证热机原理，记录输出并迭代设计。',[
'实践依次经历任务提出、模型设计、实施测试、交流改进。','模型需要热源、工作物质、将膨胀运动转成机械运动的结构，并能继续循环。','应明确能量来自热源，输出为机械功，同时存在向环境散热。','评价模型可比较稳定运行时间、启动条件、转速和可带动负载。','只改变一个设计变量并重复测试，保留失败数据；不加热密闭易碎容器。'
],'转得快不一定有用功率大；必须结合负载与输出功，使用安全低温差教学模型。',[
'本实践围绕“如何把温差带来的能量转移转变为可见机械运动”展开。热机模型不是永久运动装置，它需要从热源获得能量，并把其中一部分转化为机械功。制作前先画结构示意图和能量流向，标出热源、工作气体、活塞或薄膜、连杆以及运动输出部分，避免只模仿外形而说不出原理。',
'一种合适的课堂选择是低温差热机套件：底部接触温热水，上部与较凉空气接触，内部气体在不同位置吸放热，通过压力变化与机构运动输出机械能。温差消失时模型会逐渐停下。它的工作机理可帮助理解热机，但不要把它的每个零件强行对应四冲程汽油机；不同热机结构可以不同。',
'先确定可测目标，例如在相同初始水温和负载下连续运行两分钟。用秒表计时，在转盘做标记以数转数，必要时用录像逐段分析。比较两种保温设计时保持热水质量、初温、室温、润滑和负载相同。每种方案重复三次，求平均并保留波动范围，不能只报告最好一次。',
'模型提升0.050 kg重物0.40 m，取g=10 N/kg，输出功为mgh=0.20 J。若用时4 s，有用功率为0.050 W。另一个模型空转更快，却提不起重物，不能据此说它输出功率更大。若热源提供20 J能量，前者这段提升过程的有用能量比例仅为1%，其余能量有其他去向。',
'停止运行时要排查具体原因：温差减小使驱动力变弱，摩擦较大使运动难维持，连接漏气可能降低压力作用，负载太重会使机构停转。排查时一次只改变一项因素，再比较转速和可输出功。如果同时换热源、换连杆和减轻负载，即使成功，也无法判断是哪项改进起作用。',
'报告应包括设计草图、材料清单、控制变量、原始数据、能量解释与下一步改进。使用温水和成品低温差机构，在老师指导下开展，不以燃烧燃料或加热密闭容器追求转速。展示交流时既说成功之处，也说明摩擦、散热和测量误差，这样其他同学才能按相同条件复现并评价设计。'
],[
C(1,'热机模型持续运行的能量来源是？',['热源','飞轮凭空产生','连杆颜色','永远不变的惯性'],0,'需持续获得能量或消耗储能。'),C(1,'合理的制作起点是？',['直接加热密闭玻璃瓶','先画结构和能量图','只看转速不测量','省去测试'],1,'先明确目标、结构和可验证原理。'),C(1,'模型提升重物，主要输出什么能量？',['机械能','核能','化学能','电荷'],0,'提升增加重力势能。'),C(1,'温差逐渐消失后模型停下，说明？',['永动机被破坏','持续运行依赖能量供给与温差','能量消失','无需热源'],1,'热源与环境的温差是装置工作的条件。'),M(2,'比较两种连杆设计，应控制？',['热源初温','负载','计时方法','连杆设计完全不变'],[0,1,2],'连杆设计是研究变量。'),M(2,'合适的实践做法有？',['使用低温差教学套件','记录失败数据','加热密闭易碎容器','重复测试'],[0,1,3],'不以危险高压装置做学生模型。'),T(2,'模型20 s转100周，平均每秒多少周？',['5'],'100/20=5周/s。'),T(2,'提升0.10 kg重物0.50 m，g=10 N/kg，做功多少J？',['0.5','0.50'],'mgh=0.1×10×0.5=0.5 J。'),C(2,'甲空转很快、乙能带动较重负载，仅凭空转快慢能否比较有用功率？',['能','不能，需比较输出功和时间','甲一定高','乙一定低'],1,'P=W/t，还需负载与位移等。'),C(2,'三次测量转速相差较大，最好？',['删掉低值','检查条件并报告重复测量','只留最高值','不写单位'],1,'波动本身也是需要说明的数据。'),C(3,'模型输出0.6 J，用时3 s，热源供能30 J，其功率和有效比例为？',['0.2 W，2%','2 W，20%','0.2 W，20%','1.8 W，2%'],0,'P=0.6/3=0.2 W；η=0.6/30=2%。'),C(3,'同时改变温差、负载和连杆，转速提高，主要问题是？',['改进太多难以归因','转速不能测','一定错误','没有输出能量'],0,'无法判断哪项变量使转速改变。'),C(3,'温差足够但模型启动困难，合理排查是？',['检查转轴摩擦与连杆卡滞','认定守恒失效','不断升高到危险温度','去掉所有防护'],0,'优先排查机械损耗及结构问题。'),T(3,'三次稳定转速为4.8、5.2、5.0周/s，平均多少周/s？',['5','5.0'],'平均值为5.0周/s。'),C(3,'下列结论最符合证据意识的是？',['这次成功，所有条件都能运行','在给定温差和负载下三次均运行两分钟','模型绝对无能量损失','不能测量就不记录'],1,'结论应限定在实际测试条件内。'),K('同一模型分别提升0.10 kg重物0.40 m，g=10 N/kg。方案A用时4 s，方案B用时2 s，两方案输入能量均为20 J。',[['每次提升输出功多少J？',['0.4','0.40']],['方案B有用功率多少W？',['0.2','0.20']],['两方案有用能量比例都为多少？',['2%']]],'W=mgh=0.4 J；B功率0.4/2=0.2 W；两者输出功相同、输入相同，效率都2%，速度不同不代表效率一定不同。')
],engineVisual('热机模型：温差供能、机构输出'));
function resistor(x,y,label){return line(x-30,y,x,y)+`<rect x="${x}" y="${y-12}" width="70" height="24" fill="#fff" stroke="#396b64" stroke-width="3"/>`+line(x+70,y,x+100,y)+text(x+17,y-23,label,17);}
function battery(x,y){return line(x-35,y,x-6,y)+line(x-6,y-22,x-6,y+22)+line(x+7,y-12,x+7,y+12)+line(x+7,y,x+40,y)+text(x-24,y+43,'+   −',18);}
function circuitVisual(mode='series',labels=['R₁','R₂']){
 const left=110,right=650,top=94,bottom=260;
 let a=line(left,top,left,bottom)+line(right,top,right,bottom)+line(left,bottom,344,bottom)+battery(379,bottom)+line(419,bottom,right,bottom);
 if(mode==='parallel')a+=line(left,top,280,top)+resistor(310,top,labels[0])+line(410,top,right,top)+line(left,174,280,174)+resistor(310,174,labels[1])+line(410,174,right,174)+`<circle cx="110" cy="174" r="5" fill="#396b64"/><circle cx="650" cy="174" r="5" fill="#396b64"/>`+text(126,204,'A：分流点',15)+text(551,204,'B：汇流点',15);
 else a+=line(left,top,180,top)+resistor(210,top,labels[0])+line(310,top,440,top)+resistor(470,top,labels[1])+line(570,top,right,top);
 return V(mode==='parallel'?'两电阻并联：两端接在相同节点':'两电阻串联：电流只有一条路径',a,mode==='parallel'?'节点A、B之间两条支路；支路两端电压相同，干路电流等于各支路电流之和。':'电流依次流过两个电阻，电流处处相等；电源电压由两个电阻共同分担。');
}
function meterVisual(type='A') {return V(type==='A'?'电流表接法：串联':'电压表接法：并联',line(85,105,210,105)+resistor(240,105,'R')+line(340,105,650,105)+line(85,105,85,264)+line(650,105,650,264)+line(85,264,335,264)+battery(370,264)+line(410,264,650,264)+(type==='A'?`<circle cx="510" cy="105" r="26" fill="#fff" stroke="#396b64" stroke-width="3"/>`+text(500,112,'A',22)+text(455,64,'电流进入 + 端',16):line(210,105,210,191)+line(210,191,345,191)+line(397,191,470,191)+line(470,191,470,105)+`<circle cx="371" cy="191" r="26" fill="#fff" stroke="#396b64" stroke-width="3"/>`+text(361,199,'V',22)+text(205,232,'+              −',18))+text(45,40,type==='A'?'选合适量程，切勿直接跨接电源':'测R两端电压；理想电压表电流可忽略',19),type==='A'?'图为闭合电路，电流表串联测通过R的电流。量程未知时先估算并用大量程试测。':'理想电压表与被测电阻并联；测量支路不改变原电路的主要电流。');}
function graphVisual(title,kind='ohm') {return V(title,line(95,261,650,261)+line(95,261,95,48)+text(650,285,'U/V')+text(35,41,'I/A')+(kind==='ohm'?line(95,261,610,64,'#d38b5f')+line(95,261,610,161,'#3e8178')+text(570,65,'R小')+text(576,149,'R大'):`<path d="M95 261 Q180 80 610 58" fill="none" stroke="#d38b5f" stroke-width="4"/>`+text(290,126,'灯丝升温，电阻增大'))+text(115,311,kind==='ohm'?'同一电压，电流越大，电阻越小':'曲线上各点用 R = U / I；不是定值电阻',17),'横轴电压、纵轴电流；图示强调趋势，数值题需按题目给出的数据计算。');}
unit(15,'电流和电路','从电荷到电流，再用电路图研究连接方式和电流规律。');
add('p15-1','两种电荷','根据相互作用判断带电情况，并用电子转移解释摩擦起电。',[
'自然界存在正、负两种电荷；同种电荷互相排斥，异种电荷互相吸引。','摩擦起电是电子发生转移，得到电子带负电，失去电子带正电。','带电体能吸引轻小物体，但吸引不能单独证明对方带异种电荷。','验电器两金属箔因带同种电荷相互排斥而张开。','导体中有能够自由移动的电荷；常见金属中的自由电荷主要是自由电子。'
],'排斥可判断同种带电；吸引也可能是带电体吸引不带电轻小物体。',[
'用丝绸摩擦过的玻璃棒所带电荷规定为正电荷，用毛皮摩擦过的橡胶棒所带电荷规定为负电荷。电荷相互作用遵循同种相斥、异种相吸。电荷量表示带电多少，单位库仑。这里正负是两种性质的标记，不表示哪种更强或哪种质量更大。',
'摩擦时，物体中的部分电子可能从一种材料转移到另一种材料。原子中的原子核带正电且在这种过程中不离开物体；获得多余电子的一方带负电，失去部分电子的一方带正电。摩擦不是创造了电荷，而是使原本电中性的物体电荷不再相互抵消。若把两个物体作为封闭整体，总电荷保持不变。',
'判断带电性质最稳妥的是用排斥证据。已知正电棒排斥小球，小球必带正电；如果正电棒吸引小球，小球可能带负电，也可能原来不带电，因为带电体能使邻近中性物体内电荷分布变化而产生吸引。题目若说两个带电体相吸，才可判定它们带异种电荷。',
'小球A排斥已知带负电的小球B，因此A也带负电。若A吸引小球C，却没有告诉C原来带电，就不能唯一确定C为正电；C也可能不带电。再用正电棒测试C，若出现排斥，才能确认C为正电。这体现了从一个现象保留多个可能解释，再补充证据缩小范围。',
'验电器的金属球与两片金属箔相连，电荷传到箔片后，两片常带同种电荷而排斥张开。张角能帮助判断带电情况，但仅凭张开不能知道是正还是负。导体易导电的关键是有可自由移动的电荷；绝缘体不是没有电荷，而是电荷不容易自由移动，条件改变后绝缘性能也可能改变。',
'天气干燥时摩擦起电现象较明显，潮湿环境中表面水分可能让电荷较快散失。实验应使用干燥器材、避免手直接接触带电部位，并用多次观察判断。不要把静电吸附和磁铁吸铁混为一谈：带电体可吸引很多轻小非金属物体，而普通磁铁主要吸引铁、钴、镍等磁性材料。'
],[
C(1,'同种电荷之间？',['相吸','相斥','无作用','变成无电荷'],1,'同种相斥、异种相吸。'),C(1,'物体得到电子后通常带？',['正电','负电','永不带电','磁性'],1,'电子带负电。'),C(1,'摩擦起电的本质是？',['创造电荷','电子转移','原子核分裂','生成磁极'],1,'总电荷没有凭空产生。'),C(1,'验电器金属箔张开主要因为？',['同种电荷排斥','异种电荷吸引','重力变大','风力'],0,'两箔片带同种电荷。'),M(2,'关于带电正确的有？',['带电体可吸引轻小物体','吸引一定说明带异种电','排斥说明带同种电','失去电子可能带正电'],[0,2,3],'中性轻小物体也能受吸引。'),M(2,'导体和绝缘体描述正确的有？',['金属内有自由电子','绝缘体完全没有电荷','绝缘性能与条件有关','干燥橡胶通常不易导电'],[0,2,3],'绝缘体也由带电粒子组成。'),T(2,'玻璃棒摩擦后带正电，是得到还是失去电子？',['失去','失去电子'],'正电说明电子相对减少。'),T(2,'负电棒排斥小球，小球带什么电？',['负电','负'],'排斥是同种电荷的证据。'),C(2,'正电棒吸引未说明带电状态的小纸屑，纸屑？',['一定负电','可能不带电','一定正电','没有原子'],1,'带电体可吸引中性物体。'),C(2,'验电器张开但无已知电荷参照，能判断？',['一定正电','一定负电','有带电迹象，符号不能直接确定','一定没电'],2,'张开不能单独识别电荷正负。'),C(3,'A、B均明确带电且相吸，A带正电，则B？',['负电','正电','一定中性','无法判断'],0,'已知双方都带电，吸引表示异种。'),C(3,'两绝缘物体摩擦后分别带+Q和−Q，封闭整体净电荷？',['+2Q','−2Q','0','Q'],2,'电荷转移使一增一减。'),C(3,'金属导电时，通常沿导线定向移动的是？',['原子核','自由电子','金属整体','中子'],1,'金属原子核不沿电路定向迁移。'),T(3,'A排斥正电棒，B与A均带电且相吸，B带什么电？',['负电','负'],'A正，B与A异种，所以B负。'),C(3,'潮湿天气静电现象较不明显，合理解释是？',['电荷种类变少','电荷更容易经表面水分散失','电子不存在','摩擦完全停止'],1,'湿度会改变电荷保留条件。'),K('已知棒P带正电，三个轻小球的观察如下。',[['A带什么电？',['正电','正']],['C已知带电且被A吸引，C带什么电？',['负电','负']],['B被P吸引，是否能确定B一定带负电？填能或不能。',['不能']]],'P排斥A，所以A正；已知带电的C与A相吸，C负；B可能带负电或中性。',{headers:['对象','观察'],rows:[['A','被P排斥'],['B','被P吸引'],['C（已知带电）','被A吸引']]})
],V('同种相斥，异种相吸',[[120,'+'],[290,'+'],[475,'+'],[640,'−']].map(([x,s])=>`<circle cx="${x}" cy="133" r="40" fill="${s==='+'?'#f3d7c2':'#c7e3df'}"/>`+text(x-12,144,s,34)).join('')+arrow(180,133,155,133)+arrow(230,133,255,133)+arrow(525,133,552,133)+arrow(590,133,563,133)+text(111,225,'同种电荷相互排斥')+text(466,225,'异种电荷相互吸引'), '吸引轻小物体也可能由带电体与中性物体的相互作用产生；“吸引”证据不能无限扩大。'));
add('p15-2','电流和电路','用电路组成与通断状态解释电流，并正确画简单电路图。',[
'电荷的定向移动形成电流，规定正电荷定向移动方向为电流方向。','电源使电路两端存在电压，用电器把电能转化为其他形式能量。','持续电流一般需要电源和闭合的导电回路。','通路为正常连通，断路为某处断开；导线直接接电源两极可能形成电源短路。','电路图用统一符号表示连接关系，元件位置变化不一定改变连接方式。'
],'金属自由电子定向移动方向与规定电流方向相反；不可用导线直接连接电源两极。',[
'电荷沿一定方向移动形成电流，人们把正电荷定向移动的方向规定为电流方向。金属导体中的自由电荷通常是电子，电子带负电，因此电子定向移动方向与规定电流方向相反。在电源外部的正常电路中，电流从电源正极流出，经用电器回到负极。',
'一个简单电路由电源、用电器、开关和导线等部分组成。电源负责建立并维持推动电荷定向移动的条件，用电器消耗电能并输出光、热或机械能，开关控制回路是否完整。可以类比环形水路帮助想象电荷流动，但不要把电源理解为不断造出电荷的工厂：导线中本来就有大量电荷。',
'识图时先从电源正极沿导线走，遇到元件看是否可通过，再检查是否能返回负极。某处断开使回路不完整，叫断路。导线绕过用电器可能使其两端被短接；若导线几乎不经过有用电阻直接连接电源两极，则为电源短路，会引起很大电流，因此接线时保持开关断开并检查。',
'电池、开关和一盏灯串成闭合回路时，闭合开关灯亮；把开关断开，整个回路电流停止。若再用导线跨接灯泡两端，灯泡被短路，电流主要从阻力很小的导线通过，可能同时造成电源短路。故障判断不能只说灯不亮，还要判断有没有电流、哪里被旁路或断开。',
'画电路图时用统一元件符号，导线尽量横平竖直，交叉相连处加实心点；不相连的交叉需表示清楚。实际导线长短与图中位置不决定串并联，决定连接的是元件端点连接到了哪些节点。把电路图拉伸或弯折，只要节点关系没有变，它仍表示同一种连接。',
'实验使用规定的低压电源。先摆放器材，按电路图依次连接，完成后逐段核对，再短时间试接观察异常。若导线或电源明显发热，应立即断开并检查。学习电流方向时，可用箭头标在电源外部导线上；箭头标的是约定方向，不要同时把它当作电子移动方向。'
],[
C(1,'电流形成的条件之一是电荷怎样运动？',['无规则运动','定向移动','完全静止','只做圆周运动'],1,'定向移动形成电流。'),C(1,'规定电流方向是？',['负电荷移动方向','正电荷定向移动方向','原子核任意运动方向','由导线颜色决定'],1,'这是统一约定。'),C(1,'控制电路通断的元件是？',['开关','导线外皮','电池商标','桌面'],0,'开关改变回路是否连通。'),C(1,'用导线直接连接电源两极可能造成？',['正常供电','电源短路','安全断路','电池自动变强'],1,'电流可能过大，禁止这样连接。'),M(2,'正确的电路理解有？',['闭合回路有助于形成持续电流','用电器转化电能','电源不断创造电子','金属中电子方向与电流相反'],[0,1,3],'电荷本来存在，电源提供能量。'),M(2,'画电路图应做到？',['使用标准符号','明确相连节点','只按实物外形照画','保持连接关系正确'],[0,1,3],'图强调连接，不是器材照片。'),T(2,'正常电源外部电路，电流从电源哪一极流出？',['正极','正'],'约定电流由正极流向负极。'),T(2,'电路某处断开、无完整回路，这种状态叫？',['断路','开路'],'断路切断了回路。'),C(2,'导线中的电子向左定向移动，电流方向为？',['左','右','上下交替','无法定义'],1,'电子为负电，电流方向相反。'),C(2,'改变电路图元件位置但节点连接未变，电路关系？',['必改变','可以保持相同','必短路','必断路'],1,'连接拓扑由端点关系决定。'),C(3,'灯泡两端跨接一根理想导线，灯泡一般？',['仍正常发光','被短路，电压趋近零','电压加倍','阻值变为无穷'],1,'旁路线使两端近似等电位。'),C(3,'灯不亮就能断定断路吗？',['能','不能，灯被短路也可能不亮','一定电源坏','一定灯丝断'],1,'需要其他证据区分故障。'),C(3,'电池、灯、开关串成回路；开关接在灯前或灯后，对控制作用？',['只有灯前有效','只要串联位置不同也控制同一回路','灯后导致并联','灯后必短路'],1,'单一路径的开关在哪里都能控制通断。'),T(3,'某闭合低压电路每秒通过横截面的电荷量为0.6 C，已知1 A=1 C/s，电流多少A？',['0.6'],'I=Q/t=0.6 A。'),C(3,'电路连接完成后最合理做法是？',['直接长时间通电','先核查有无短接，再试接','用手触摸裸露高压端','增大电源电压检测'],1,'低压实验也需检查回路与量程。'),K('一个低压电路按“电源正极→开关S→灯L→电源负极”连接。',[['S断开时电路状态是什么？',['断路','开路']],['S闭合时，电源外部电流先经过S还是L？',['S','开关S']],['若用理想导线跨接电源两极，这种危险状态叫什么？',['电源短路','短路']]],'S断开无闭合回路；电流约定由正极出发先过S；两极直接用导线连接会造成电源短路。')
],circuitVisual('series',['用电器R₁','用电器R₂']));
add('p15-3','串联电路和并联电路','依据节点与电流路径识别串并联，设计独立与共同控制。',[
'元件依次相接，电流只有一条路径，称为串联电路。','元件两端分别接在同一对节点上，形成多条支路，称为并联电路。','串联电路任一处断路会使整条回路无电流。','理想电源供电的并联电路，各支路可以独立工作；干路开关控制所有支路。','分支开关只控制所在支路；判断连接应看节点而非图的外形。'
],'并排画的不一定并联，画成一条直线的也可能含分支；从分流点到汇流点追踪路径。',[
'串联电路把用电器一个接一个地接入同一路径，电荷通过前一个元件后还要经过后一个元件。并联电路让各用电器分别接在同一对节点之间，电流在分流点分开，在汇流点重新汇合。区分的关键是电流是否有多条独立路径，而不是图上元件摆放得横向还是竖向。',
'可以把串联想成一条只有一个通道的走廊，其中一扇门关闭，整个通道都被切断。并联像两条连接同一出入口的走廊，一条关闭，另一条仍可通行。这个比喻用来理解连接与控制，不能用来断言电荷“先到某灯，后到另一灯”产生可见时间差；实际电路建立后各处响应很快。',
'识图时先找电源两端，再把没有元件的理想导线所连接的端点视为同一节点。逐条追踪从正极到负极的路线，标出公共干路与各支路。若两个元件两端分别在相同两节点上，它们就是并联；若连接点没有其他分支、依次通过，通常为串联。复杂图可以重画，让节点关系更清楚。',
'两盏走廊灯要求用一个总开关同时控制，又希望一盏损坏后另一盏仍能亮，可让两灯并联，总开关接在干路。若还要每盏能独立开关，再在各支路分别串联一个开关。这样总开关断开，两盏都灭；总开关闭合时，每盏灯由自己的支路开关控制。',
'故障分析要附带电源模型条件。在理想稳定电源下，一条并联支路断开，其他支路电压保持不变，通常不受影响。但一条支路被理想导线短接可能使整个电源短路，并非“只影响本支路”。所以“并联支路互不影响”用于正常通断和理想电源的限定情境，不能无限扩展到短路故障。',
'设计控制电路先写逻辑：任一开关闭合就亮，常用两个开关并联后控制灯；两个开关都闭合才亮，常用两开关串联。用低压模拟验证所有开关组合，比只试一次更可靠。列出真值表时应检查四种组合是否都满足要求，并明确元件允许电流与电源电压，避免控制正确却发生短接。'
],[
C(1,'两个用电器依次连接且只有一条电流路径，属于？',['串联','并联','短路','断路'],0,'单一路径是串联特征。'),C(1,'并联两灯共有的特点是？',['两端接同一对节点','电流必相等','任一灯断路全部熄灭','只能一个开关'],0,'支路电流可不同。'),C(1,'并联电路干路开关控制？',['所有支路','只有一条支路','电源内部电子数','无作用'],0,'干路是所有支路共同路径。'),C(1,'串联两灯中一只灯丝断开，通常？',['另一只更亮','两灯都不亮','另一只不变','电源短路'],1,'整个回路被断开。'),M(2,'正常并联电路中正确的有？',['各支路可独立通断','支路开关控制所在支路','干路开关可总控','一条支路短路绝不影响电源'],[0,1,2],'短路可能危及整个电源。'),M(2,'判断连接方式可靠的方法有？',['找分流汇流节点','沿电流路径追踪','只看元件是否并排','在节点关系不变下重画'],[0,1,3],'图的几何外观不足以判断。'),T(2,'两盏灯要求独立工作，应主要选串联还是并联？',['并联'],'并联提供独立支路。'),T(2,'两个开关都闭合灯才亮，两开关应怎样连接？',['串联'],'串联形成逻辑“且”。'),C(2,'两个开关任一闭合都可使灯亮，两开关可？',['串联','并联后与灯串联','跨接电源短路','与灯都断开'],1,'开关并联提供任一路径，但必须与灯串入主回路。'),C(2,'两灯并联，总开关断开但支路开关闭合，灯？',['都能亮','都不亮','必短路','亮度加倍'],1,'干路被切断。'),C(3,'稳定理想电源的并联支路一盏断路，另一盏额定匹配且无故障，亮度？',['通常不变','必变暗','必变亮','必熄灭'],0,'另一支路两端电压不变。'),C(3,'并联两支路之一用理想导线替代用电器，主要危险是？',['仅该支路不亮且完全安全','可能形成电源短路','变成正常串联','总电流变为零'],1,'导线将两电源节点直接连接。'),C(3,'如配图所示，两电阻两端分别连同一对节点，R₁断路后R₂所在回路仍完整。属于？',['串联','并联','两者都不是','电源断路'],1,'同一对节点之间有两条支路。'),T(3,'两开关A、B串联控制一灯，共4种开关状态，其中灯亮的状态有几种？',['1'],'仅A、B都闭合时灯亮。'),C(3,'某报警器要求门开或窗开任一条件成立就报警，两个感应开关在触发时闭合，可用？',['两开关串联','两开关并联后与报警器串联','报警器短接','开关仅接一个端点'],1,'并联实现“或”控制。'),K('总开关S位于干路，灯L₁与开关S₁串联成支路1，灯L₂与S₂串联成支路2，两支路并联于稳定电源。',[['S闭合、S₁断开、S₂闭合时，亮的是L₁还是L₂？',['L2','L₂']],['S断开、S₁和S₂闭合时有几盏灯亮？',['0']],['若只使L₁熄灭而L₂继续亮，应断开哪个开关？',['S1','S₁']]],'总开关控制所有支路，分开关只控制自身支路；正常通断可独立操作。')
],circuitVisual('parallel'));
add('p15-4','电流的测量','正确连接、选量程、读电流表，并结合故障判断测量状态。',[
'电流用I表示，单位安培A，1 A=1000 mA，1 mA=1000 μA。','电流表串联接入待测电路，让电流从正接线柱流入。','读数先确定量程和分度值，再读指针位置；未知电流先估算并用大量程试测。','理想电流表电阻很小，不能直接接在电源两极之间。','测量不同位置电流时要保持连接关系，改接前断开开关。'
],'同一刻度盘在不同量程下分度值可能不同；指针反偏首先检查正负接线。',[
'电流表示电流的强弱，符号为I，国际单位安培，简称安。实验中常见较小电流可用毫安表示，1 A等于1000 mA。电流表要让被测电流从内部通过，因此应串联在被测路径中，而不是像测电压那样跨在元件两端。',
'可以把电流表想成统计某通道通行量的检测站。要测这条支路，就要把检测站放在这条支路里，不能放到另一条路上。理想电流表内部电阻近似为零，正常串联时对原电路影响较小；若把它直接跨接电源两端，相当于用低电阻通道短接电源，容易损坏器材。',
'操作顺序是断开开关，选接线柱，确认电流从正端进入，检查量程，再试接。估计不出电流时先用较大量程，观察后再在断电状态下改到更合适量程。读表先看接线柱决定量程，再数每小格代表多少，最后读取指针位置。不能只背某刻度位置对应固定电流。',
'一只双量程表，小量程0至0.6 A共30小格，每格0.02 A；大量程0至3 A共30小格，每格0.1 A。指针在第18小格时，小量程读0.36 A，大量程读1.8 A。若题目没有给接线柱或量程，仅有指针位置，不能唯一确定数值。',
'指针向零刻度左侧偏，通常需要检查正负接线是否颠倒；指针超过最大刻度，应迅速断开，检查是否量程过小或电路短路；指针偏转太少则可以在不超量程前提下用更小量程提高读数精细程度。故障判断需结合灯亮不亮、表接法和开关状态，不能只凭一个现象下唯一结论。',
'测量应记录数值与单位，且读数时视线与表盘尽量垂直，减少视差。切换测量位置必须先断开电路；不要带电用接线头乱碰找读数。若研究串联各处电流，应使用同一量程并让电路工作条件稳定，再比较多个位置；小幅差别也可能来自仪表分辨率和接线接触状况。'
],[
C(1,'电流国际单位为？',['V','A','Ω','J'],1,'安培是电流单位。'),C(1,'电流表应与被测支路？',['串联','并联','完全断开','仅接一个端点'],0,'需要被测电流通过仪表。'),C(1,'200 mA等于？',['2 A','0.2 A','20 A','0.02 A'],1,'除以1000。'),C(1,'电流应从电流表哪个接线柱流入？',['正','负','任意都完全相同','外壳'],0,'正常指针表要按极性接入。'),M(2,'合理操作有？',['改接前断开开关','未知电流先大量程试测','直接跨接电源试表','读数先看量程'],[0,1,3],'不可直接跨接电源。'),M(2,'量程0至0.6 A、30等分小格的表，正确的有？',['每格0.02 A','15格是0.30 A','每格0.2 A','可测0.50 A'],[0,1,3],'0.6/30=0.02 A。'),T(2,'0至3 A量程分30小格，指针第12格，电流多少A？',['1.2'],'分度值0.1 A，读1.2 A。'),T(2,'0.45 A等于多少mA？',['450'],'0.45×1000=450。'),C(2,'指针反偏首先检查？',['接线极性','桌子颜色','灯泡玻璃形状','单位印刷字体'],0,'电流反向进入会使指针反偏。'),C(2,'电流很小而未超限，更合适的量程通常？',['越大越好','适当小量程','不接量程','直接短路'],1,'小量程通常有更细的分度值。'),C(3,'同表盘0.6 A和3 A量程，同一指针位置读数比为？',['1:5','5:1','1:1','1:10'],0,'量程比0.6:3=1:5。'),C(3,'0至0.6 A表误以3 A刻度读成1.5 A，实际电流？',['0.30 A','7.5 A','1.5 A','0.03 A'],0,'实际为所读值的1/5。'),C(3,'电流表并联到灯两端后灯不亮，最需警惕？',['电流表形成旁路短接灯','电流一定为零','灯额定值自动提高','电源变成交流'],0,'小内阻表可能短路灯甚至电源。'),T(3,'电流表0至0.6 A，共30小格。指针第23格，读数多少A？',['0.46'],'23×0.02=0.46 A。'),C(3,'两次改接测得0.30 A和0.32 A，分度值0.02 A，应如何评价？',['必证明电流不守恒','考虑分辨率与接触变化，再重复核查','只删去一个数据','两数一定完全准确'],1,'差异为一小格，需按实验精度分析。'),K('同一电流表两量程均为30等分小格，甲接0至0.6 A，乙接0至3 A。',[['甲指针第16格，读数多少A？',['0.32']],['乙指针第16格，读数多少A？',['1.6']],['若电流估计0.4 A，确认安全后用哪一量程读得更精细？填0.6或3。',['0.6']]],'分度值分别0.02 A与0.1 A；对应0.32 A与1.6 A。0.4 A在小量程内，选0.6 A更精细。')
],meterVisual('A'));
add('p15-5','串、并联电路中电流的规律','通过多组实验总结电流规律，分析支路与干路读数。',[
'串联电路电流处处相等：I=I₁=I₂。','并联电路干路电流等于各支路电流之和：I=I₁+I₂。','并联支路电流不一定相等，大小与支路元件和两端电压有关。','研究规律应改变灯泡或电源条件多次测量，避免偶然特殊结果。','电流表放在分流点前测干路，放在某支路只测该支路。'
],'电流流过用电器不会被消耗掉；用电器转化的是电能，电荷不在灯中凭空消失。',[
'串联电路中，电流各处相等。并联电路中，在分流点流入的总电流等于流出的各支路电流之和，在汇流点同样满足这个关系。这些规律可以通过测量得到，也与电荷不会在正常稳定节点中无休止堆积相一致。要把电流的连续性与电能在元件中的转化分开理解。',
'两盏串联灯亮度不同，并不表示通过较亮灯的电流一定更多，因为它们在同一路径，电流相同。并联灯也不一定电流相同，只有当支路元件条件相同等情况下才可能恰好相等。串联规律讲同一条路，干路求和规律讲分叉处，先看连接，再套数值。',
'实验先用不同规格的小灯泡串联，在灯前、两灯之间、灯后分别测量；再把两灯并联，测干路和各支路。保持电源条件稳定，记录量程和单位，改接前断电。只用两个完全相同灯泡可能测得并联支路电流相同，但这只是特例，应更换不同灯泡检验一般规律。',
'两支路电流分别为0.20 A和0.35 A，干路是0.55 A。若干路表读0.80 A，已知一支路0.30 A，另一支路应为0.50 A。串联两个不同电阻时，只要某处测到0.30 A，其余位置也为0.30 A，而不能按元件数量把电流再分成一半。',
'分析带多个电流表的图，先画节点并把理想电流表看作所在路径的一小段导线，再标注每块表究竟在哪些支路分流之前或之后。两块表读数的差有时就是某个支路电流。如果两表指针偏转相同但量程不同，必须先分别换算读数；相同偏角不等于相同电流。',
'实验数据小幅偏差可来自仪表精度、接触电阻或电池状态变化，应注明而不是编造完全相等数据。若干路测值小于一支路，先检查量程、位置、极性和记录单位，通常是接线或读数问题。在模型中电流规律必须同时成立，矛盾数据可以帮助定位错误，不应硬凑结论。'
],[
C(1,'串联电路中的电流关系是？',['处处相等','越流越小','灯越亮电流必越大','总是相加'],0,'串联只有一条路径。'),C(1,'并联电路干路电流等于？',['某一支路','各支路之和','两支路之差','固定为1 A'],1,'分流点满足电流相加。'),C(1,'电流经过灯泡后？',['电荷被消耗完','稳定串联回路电流不减少','一定减半','变成电压'],1,'灯转化电能而不是消耗电荷。'),C(1,'并联两支路电流？',['一定相同','不一定相同','一定相反','不能测量'],1,'支路元件不同电流可不同。'),M(2,'实验探究合理做法有？',['多组不同灯泡验证','记录各表量程','只测一组相同灯泡就认定支路总相等','改接先断电'],[0,1,3],'需避免从特殊条件推一般规律。'),M(2,'两支路电流0.2 A和0.4 A，正确的有？',['干路0.6 A','干路大于任一支路','支路电流必须改为相同','电流在节点处分流'],[0,1,3],'支路可不相等。'),T(2,'串联两灯，灯前电流0.28 A，灯后电流多少A？',['0.28'],'串联各处相等。'),T(2,'并联支路0.25 A、0.35 A，干路多少A？',['0.6','0.60'],'0.25+0.35=0.60 A。'),C(2,'并联干路0.9 A，支路1为0.4 A，支路2为？',['0.5 A','1.3 A','0.36 A','0.4 A'],0,'0.9−0.4=0.5 A。'),C(2,'串联两灯亮度不同，电流关系？',['较亮灯电流大','两灯相同','较暗灯电流大','无法确定'],1,'串联电流相同，亮度还与实际功率有关。'),C(3,'并联干路表用3 A量程、支路表用0.6 A量程，偏角相同。干路1 A，则另一支路？',['0.8 A','0.2 A','1.2 A','5 A'],0,'同偏角支路读1/5=0.2 A，另一支路0.8 A。'),C(3,'并联干路0.7 A，两支路分别记录0.4 A与0.5 A，应？',['直接平均成0.45 A','检查位置、量程和记录','认定规律失效','删除干路数据'],1,'0.4+0.5≠0.7，存在测量或记录问题。'),C(3,'稳定理想电源并联三支路电流0.1、0.2、0.3 A，断开0.2 A支路后干路为？',['0.6 A','0.4 A','0.2 A','0 A'],1,'其余支路电压不变，总电流0.1+0.3。'),T(3,'并联两支路电流比2:3，干路1.5 A，较小支路多少A？',['0.6'],'共5份，每份0.3 A，2份0.6 A。'),C(3,'如果表A位于两支路分流之前，表B仅在支路1，A−B表示？',['支路2电流','两支路之和','支路1电压','总电阻'],0,'干路减支路1等于支路2。'),K('三组并联实验数据如下，表中问号均为电流，单位A。',[['第1组干路电流多少A？',['0.5','0.50']],['第2组支路2电流多少A？',['0.4','0.40']],['第3组支路1电流多少A？',['0.3','0.30']]],'逐组应用I=I₁+I₂：0.2+0.3=0.5；0.65−0.25=0.4；0.9−0.6=0.3。',{headers:['组别','干路','支路1','支路2'],rows:[['1','?','0.20','0.30'],['2','0.65','0.25','?'],['3','0.90','?','0.60']]})
],circuitVisual('parallel',['I₁支路','I₂支路']));
unit(16,'电压 电阻','掌握电压测量、电阻因素与变阻器，设计低压调光电路。');
add('p16-1','电压','理解电压作用，正确并联电压表并读取量程。',['电压是形成电流的原因之一，电源提供电压；有电压不一定有持续电流。','电压符号U，单位伏特V；1 kV=1000 V，1 V=1000 mV。','电压表与被测元件并联，电流从正接线柱流入，选合适量程。','理想电压表电阻很大，所通过的电流可忽略；可用适当量程测电源两端电压。','读数由量程和分度值共同确定，电压测量需明确两端是哪两个节点。'],'电压存在于两点之间，不能说“流过某灯的电压”；有电源但回路断开时也可以测到电压。',[
'电压是使电荷发生定向移动、形成电流的原因之一。电源在两端提供电压，符号为U，单位伏特。讨论电压总要指出哪两个位置之间，例如灯泡两端、电源两端。它不是沿导线流动的物质，不能套用“电压经过灯泡后被消耗”的说法。',
'可用水位差帮助理解电压推动流动，但这只是一种类比。一个水路的阀门关闭，即使有水位差也没有持续水流；电路断开时，电源两端仍可有电压而没有持续电流。因此“有电流必需相应条件”不能倒过来变成“看到电压就一定有电流”。电压与闭合回路必须一起考虑。',
'电压表需要比较两端状态，所以并联在被测元件两端。先断开开关接线，正接线柱接靠电源正极的一端，负接线柱接另一端，先估算量程。理想电压表电阻很大，通过它的电流可忽略；若误把它串联在灯泡回路中，电流可能很小，灯泡不亮，而表可能接近显示电源电压。',
'双量程电压表0至3 V与0至15 V共用30小格时，分度值分别0.1 V和0.5 V。指针第24格，读数可能是2.4 V，也可能是12 V，必须看实际接线柱。若电源约6 V，小量程会超限，应先接15 V量程，不能为了读得更细就忽视测量范围。',
'沿理想导线连接且没有其他元件的各点，可以视为同一节点，节点内部电压近似为零。判断电压表测谁时，沿表两根线各自追踪到节点，不必局限于图上表放在谁旁边。电压表画得靠近某电阻，也可能跨接了两个串联电阻，真正测的是两者共同的电压。',
'在电路故障题中，理想电压表两端若恰好跨接一处断路，并通过其余完好导线连接到电源两极，可能读到接近电源电压。若表跨接被短路的元件，两端处于同一节点，则读数接近零。必须说明只有一处故障等限制条件，不能把“零电压”一概等同于某一种故障。'
],[C(1,'电压的单位是？',['A','V','Ω','W'],1,'伏特是电压单位。'),C(1,'电压表应怎样接？',['并联在被测元件两端','只接一个接线柱','串联代替导线','短接电源'],0,'电压是两点间的量。'),C(1,'2 kV等于？',['2000 V','200 V','0.002 V','20 V'],0,'1 kV=1000 V。'),C(1,'电源两端有电压而开关断开，持续电流？',['一定很大','通常没有','必为1 A','与电压相等'],1,'回路未闭合。'),M(2,'正确操作包括？',['接合适量程','正端接较高电势端','读数先确定分度值','无条件直接接任意高压'],[0,1,2],'必须在仪器和实验安全范围内。'),M(2,'理想电压表的特点包括？',['电阻很大','通过电流可忽略','正常测量时并联','可替代导线正常供灯'],[0,1,2],'串联高电阻会阻碍主要电流。'),T(2,'0至3 V共30小格，指针第18格，读数多少V？',['1.8'],'每格0.1 V。'),T(2,'4500 mV等于多少V？',['4.5'],'除以1000。'),C(2,'电压表跨接电源6 V，应优先选？',['0至3 V','0至15 V','0至0.6 A','不接量程'],1,'6 V超过3 V。'),C(2,'理想电压表误串联进灯回路，灯通常？',['正常更亮','电流极小，可能不亮','被永久加热','一定短路'],1,'表内阻大。'),C(3,'串联两电阻，电压表一端接R₁前、一端接R₂后，测的是？',['R₁','R₂','两电阻总电压','总电流'],2,'根据节点判断测量范围。'),C(3,'同表盘实际用3 V量程，却按15 V刻度读成10 V，真实值为？',['2 V','50 V','10 V','0.5 V'],0,'实际量程为所读量程1/5。'),C(3,'理想电源、开关、R串联，只有R断路，电压表跨R两端，闭合开关后？',['电流为零而表约等于电源电压','电流很大','电压必零','电源必短路'],0,'电压表经导线连到电源两极，但电流近似零。'),T(3,'0至15 V量程共30格，测得7.5 V。改接0至3 V会超量程吗？填会或不会。',['会'],'7.5>3，不能使用小量程。'),C(3,'表跨在一根理想导线两端，回路有电流，表读数为？',['电源电压','近似0','电流数值','任意大'],1,'导线电阻忽略，两端电压近似零。'),K('电压表有0至3 V和0至15 V两量程，共30等分小格。',[['大量程指针第14格，读数多少V？',['7']],['小量程相同指针位置，读数多少V？',['1.4']],['某电源为4.5 V，能否直接用3 V量程测量？填能或不能。',['不能']]],'大量程每格0.5 V，小量程每格0.1 V；4.5 V超过3 V上限。')],meterVisual('V'));
add('p16-2','串、并联电路中电压的规律','实验验证电压分配与相等关系，避免以位置判断表测量对象。',['串联电路总电压等于各部分电压之和：U=U₁+U₂。','并联各支路两端电压相等，并等于电源两端电压。','串联各部分电压不一定相等，需要依据元件条件判断。','实验要使用不同规格元件和多组数据，不能从相同灯泡特例概括普遍等分。','测量应正确选量程与极性，并用节点分析电压表的测量范围。'],'串联电压相加、并联电压相等；不要把电流规律直接照搬到电压。',[
'串联电路中，各用电器依次接入电源两端，它们共同分担电源电压，满足总电压等于各部分电压之和。并联电路中，各支路都接在同一对节点之间，因此每条支路两端电压相等。串联“相加”与并联“相等”是电压规律，和电流规律恰好需要分别记清。',
'可把电压分配想成沿楼梯下降的高度差：走过第一段再走第二段，总高度差为两段相加。而连接同一楼层起点与终点的两条不同路线，高度差相同。这个类比仅帮助理解相加关系，不表示电压就是高度，也不表示电流一定和走路人数同样分配。',
'串联实验分别测第一灯、第二灯和两灯总电压；并联实验测两支路和电源电压。每次接表前断开开关，保证极性正确且不超过量程。改变灯泡规格后重复测试，才能检验电压关系。如果使用完全相同灯泡看到各分一半，只能说明该条件下的结果，不能推出所有串联电路均分电压。',
'两个电阻串联在9 V电源上，测R₁两端3 V，则R₂两端6 V。若改成并联且电源仍保持9 V，两电阻各自两端都是9 V。连接改变后，原来串联状态的3 V、6 V不能保留照用，电流及功率也会随之改变，应从新电路重新分析。',
'多个电压表可能跨接重叠区段。若A、B、C、D依次在三个串联电阻的边界，UAD为总电压，UAC覆盖前两个电阻，UBD覆盖后两个电阻。UAC与UBD相加时，中间电阻被计算两次，所以不能把两个表的读数直接当作总电压；画出被测区间最直观。',
'误差处理同样重要：三个独立读数可能存在一小格以内的差别，应注明量程和仪表精度。若某表接在一段完好导线两端，电压近似为零；若在某处断路后测到全部电源电压，也要结合回路结构解释。先确定连接与表测区间，再代数求解，能避免大部分电压综合题错误。'
],[C(1,'串联两元件总电压等于？',['U₁+U₂','U₁−U₂','总为U₁','0'],0,'串联电压相加。'),C(1,'两电阻并联在6 V电源，两支路电压各为？',['3 V','6 V','12 V','无法测量'],1,'两端节点相同。'),C(1,'串联不同电阻两端电压？',['一定相同','不一定相同','一定为零','等于电流'],1,'不能从串联直接推出等分。'),C(1,'测电压应使用？',['串联电流表','并联电压表','温度计','秒表'],1,'需比较元件两端。'),M(2,'正确关系有？',['串联总电压为各部分之和','并联支路电压相等','串联电压总均分','并联支路电流总相等'],[0,1],'后两项是缺少条件的说法。'),M(2,'实验应注意？',['换不同元件再验证','量程覆盖待测值','改接前断电','只记总电压无需分电压'],[0,1,2],'探究关系需分别测量。'),T(2,'串联总电压12 V，第一元件5 V，第二元件多少V？',['7'],'12−5=7。'),T(2,'并联电路某支路电压4.5 V，另一支路电压多少V？',['4.5'],'并联电压相等。'),C(2,'相同灯串联各为3 V，只能说明？',['所有串联均分','该相同条件下电压相同','电压消失','电流也必为3 A'],1,'需更换元件检验一般关系。'),C(2,'并联两灯一支路正常断开，稳定电源下另一支路电压？',['不变','减半','加倍','变零'],0,'仍接原电源两端。'),C(3,'三个电阻串联，总12 V，前两个共7 V，后两个共9 V，中间电阻电压？',['4 V','2 V','5 V','16 V'],0,'中间被两次计入，7+9−12=4。'),C(3,'三个电阻串联，总18 V，U₁:U₂:U₃=1:2:3，U₂为？',['3 V','6 V','9 V','12 V'],1,'6份18 V，2份6 V。'),C(3,'某并联电路测出支路3 V、另一支路6 V且电源稳定，最应？',['检查两端节点和量程','宣布新规律','取平均4.5 V','认为电压随路径变'],0,'同节点电压应相同。'),T(3,'三个串联元件总电压15 V，前两者共9 V，后两者共11 V，中间元件电压多少V？',['5'],'9+11−15=5。'),C(3,'两电阻串联时总电压6 V，改并联后仍用6 V稳定电源，每个电阻两端电压？',['仍是原分压','都是6 V','都是3 V','都是12 V'],1,'需按新的节点连接分析。'),K('三个串联电阻R₁、R₂、R₃总电压为10 V。测得R₁与R₂共6 V，R₂与R₃共7 V。',[['R₃两端电压多少V？',['4']],['R₁两端电压多少V？',['3']],['R₂两端电压多少V？',['3']]],'U₃=10−6=4 V；U₁=10−7=3 V；U₂=10−3−4=3 V。')],circuitVisual('series',['U₁','U₂']));
add('p16-3','电阻','用控制变量研究影响电阻的因素，理解电阻的属性。',['电阻表示导体对电流阻碍作用的大小，符号R，单位欧姆Ω。','导体电阻与材料、长度、横截面积和温度等有关。','同材料同温度同横截面时，导体越长电阻越大；同长度时越粗电阻通常越小。','电阻是导体性质，不能说电压越大导体电阻就必然越大。','多数金属温度升高电阻增大，实际灯丝电阻随发光状态变化。'],'研究一个因素时必须控制其他因素；横截面积与直径不同，直径倍增面积变为四倍。',[
'导体对电流的阻碍作用用电阻表示，符号R，单位欧姆，简称欧。导体电阻越大，在相同电压下通过它的电流通常越小。电阻与导体自身的材料、尺寸和温度等有关，不是因为有电流流过才产生；一段导线没有接入电路时，也具有相应的电阻性质。',
'一条较长的金属线给电荷定向移动的阻碍通常较大，一条较粗的线提供更大的横截面，阻碍通常较小。但不能只比较长短就下结论：短而细的线可能比长而粗的线电阻更大，材料不同也会使结果改变。日常铜导线外层橡胶是绝缘层，不能把整个外径当作导电横截面。',
'控制变量实验要先说明研究因素。研究长度，选同材料、同温度、同粗细而长度不同的线；研究粗细，长度、材料和温度相同；研究材料，长度和横截面积相同。可在同一低压电源下比较电流，或用合适仪器测电阻，但不能同时换电源电压导致电流差异难以解释。',
'给出均匀导线模型R与L成正比、与横截面积S成反比时，把一根线均匀拉长到原来的2倍，体积不变，横截面积变为原来1/2，所以电阻变为4倍。若只是切去一半而粗细不变，电阻变为1/2。两种操作都涉及长度变化，却因横截面积条件不同产生不同结果。',
'温度也是重要条件。灯丝刚通电时温度较低、电阻较小，发光后温度升高、电阻增大，因此不能把灯泡在室温测得的电阻直接用于额定发光状态计算。不同材料的温度特性可能不同，初中题若涉及热敏电阻应按题中给出的随温度变化关系判断，不能把金属经验推广到全部材料。',
'当题目给出U/I求得的数值变化时，需要看元件是否为恒温定值电阻。对固定温度的定值电阻，U增大使I按比例增大，U/I保持不变；灯丝升温则使这个比值改变。区分“测量电阻的比值方法”与“电阻由哪些因素决定”，是后续学习欧姆定律和非线性图像的基础。'
],[C(1,'电阻的单位是？',['Ω','A','V','C'],0,'欧姆是电阻单位。'),C(1,'同材料同温度同粗细，导线越长电阻通常？',['越大','越小','不变','总为零'],0,'长度增加阻碍通常增大。'),C(1,'同材料同温度同长度，横截面积越大电阻通常？',['越大','越小','无规律','无限大'],1,'粗线电阻通常较小。'),C(1,'导线未接入电路，电阻？',['不存在','仍是导体性质','必无穷大','由电流决定为零'],1,'电阻不以有电流为存在条件。'),M(2,'影响导体电阻的因素有？',['材料','长度','横截面积','导线外皮颜色'],[0,1,2],'温度也会影响，外皮颜色不是直接因素。'),M(2,'研究长度影响时应控制？',['材料','横截面积','温度','长度相同'],[0,1,2],'长度是自变量。'),T(2,'2000 Ω等于多少kΩ？',['2'],'1 kΩ=1000 Ω。'),T(2,'同粗细均匀导线截去一半，R与长度成正比，原10 Ω，剩余多少Ω？',['5'],'长度减半，电阻减半。'),C(2,'多数金属导体温度升高时，电阻通常？',['增大','减小到零','一定不变','变为负值'],0,'这里只说多数金属一般趋势。'),C(2,'研究材料影响，合理配对是？',['相同长度与截面积的铜线和镍铬线','不同粗细不同长度两线','只看颜色','一根加热一根冷却'],0,'只改变材料。'),C(3,'均匀导线体积不变拉成原长2倍，R∝L/S，电阻为原来？',['2倍','4倍','1/2','不变'],1,'L×2，S÷2，R×4。'),C(3,'同材料同长度，圆线直径加倍，R∝1/S，电阻为原来？',['1/2','1/4','2倍','4倍'],1,'面积与直径平方成正比。'),C(3,'一灯从1 V到2 V电流从0.20 A到0.30 A，说明？',['电阻不变','发热后电阻增大','电阻减小','电压创造电阻'],1,'比值从5 Ω变6.67 Ω，可能由灯丝升温造成。'),T(3,'均匀线原电阻18 Ω，平均剪成3段，再将三段两端并接；每段6 Ω且三等阻并联总阻为单段1/3。总阻多少Ω？',['2'],'剪开每段6 Ω，三段并接2 Ω。'),C(3,'两线电流不同却电源电压也不同，能否直接比较电阻？',['能，只比电流','不能，需同时考虑电压','电流大电阻必大','两者必相等'],1,'只有相同电压才能由电流比较电阻。'),K('同温度均匀金属线电阻遵循R∝L/S。参考线A长1 m、面积1 mm²、电阻4 Ω。',[['同材料B长2 m、面积1 mm²，电阻多少Ω？',['8']],['同材料C长1 m、面积2 mm²，电阻多少Ω？',['2']],['A均匀拉到2 m且体积不变，电阻多少Ω？',['16']]],'B长度倍增R=8；C面积倍增R=2；A拉长时面积减半，R为原来4倍=16。')],V('电阻与长度、横截面积',text(48,44,'材料和温度保持相同')+rect(55,83,270,15,'#c8ded6')+text(375,97,'短：电阻较小')+rect(55,148,510,15,'#c8ded6')+text(55,198,'长：电阻较大')+rect(55,240,270,38,'#c8ded6')+text(375,267,'同长较粗：电阻较小'),'只改变一项因素才能比较；圆线直径变化会按平方关系改变横截面积。'));
add('p16-4','变阻器','识别滑动变阻器有效电阻丝，判断滑片变化和安全接法。',['滑动变阻器靠改变接入电路的电阻丝长度改变电阻。','常用“一上一下”两接线柱；两个上端通常近似零阻，两个下端通常接入全长。','接下端A与滑片P时，有效部分是A到P，P离A越远接入电阻越大。','串联变阻器可调电流，也可保护电路；闭合开关前通常调至接入阻值最大。','铭牌如“20 Ω 1 A”表示最大阻值20 Ω、允许通过的最大电流1 A。'],'判断滑片方向先标有效电阻丝，不能死记“向左电阻总变大”。',[
'滑动变阻器通过改变接入电路的电阻丝长度来改变电阻，是利用导体电阻与长度的关系制成的。电阻丝绕在绝缘支架上，滑片与某处电阻丝接触，移动滑片就改变起作用的那段长度。实际器材外观可能不同，但抓住固定下端与滑片的接入关系即可分析。',
'常见四接线柱结构，上端通过金属杆连到滑片，下端分别接电阻丝两头。选一个上端和一个下端，才有滑动调节效果。如果两个上端接入，电阻近似为零；如果两个下端接入，通常把整段电阻丝固定接入。不能只看外形好像接了四根线，就认定可以调节。',
'画出接线后先圈出有效电阻丝：例如下端A位于左端、滑片为P，接A与P时，A到P这段有效；P向A靠近，长度变短，电阻减小；远离A，电阻增大。如果改接右端B，方向关系正好反过来。接通前通常把有效长度调到最长，以限制初始电流。',
'电源6 V、定值电阻10 Ω与变阻器串联，变阻器最大20 Ω。在最大位置总阻30 Ω，电流0.20 A；调到5 Ω时总阻15 Ω，电流0.40 A。若电流表只允许0.30 A，最小总阻要达到6/0.30=20 Ω，因此变阻器不能小于10 Ω，并非整个滑程都安全。',
'铭牌写20 Ω 1 A，20 Ω是全长电阻，1 A是允许通过的最大电流，不表示任何位置都自动流1 A。调电流时还要兼顾电源、灯泡、电流表和变阻器各自的限值，真正允许值是这些条件共同约束的结果。功率较大的负载需要符合要求的器件，普通学生变阻器不能随意用于家庭电器。',
'故障特征可帮助判断接线：怎么滑都几乎最大电流，可能接了两个上端；怎么滑电流都较小且不变，可能接了两个下端，也可能存在别的固定因素。检查应先断电再追踪接线，不能凭观察就强行得出唯一故障。低压实验中逐渐调节并同步观察电表，接近限值应停止继续移动。'
],[C(1,'滑动变阻器主要改变导体的？',['材料','接入长度','电荷种类','温度单位'],1,'改变有效电阻丝长度。'),C(1,'常见调节接法是？',['一上一下','两个上端','只接一端','两个下端'],0,'一端接滑片，一端接电阻丝固定端。'),C(1,'闭合前通常调到？',['最大接入电阻','最小电阻','任意位置无关','零电阻'],0,'用于保护回路。'),C(1,'“20 Ω 1 A”中20 Ω表示？',['恒定电流','最大阻值','最小功率','电源电压'],1,'全长电阻20 Ω。'),M(2,'下端左A与滑片P接入，正确的有？',['AP为有效段','P远离A电阻增大','P靠近A电阻减小','方向与下端选择无关'],[0,1,2],'换右端后方向关系反过来。'),M(2,'变阻器串联可用于？',['调节电流','限制初始电流','自动保证任意器材安全','改变被测元件两端电压'],[0,1,3],'仍需遵守量程与额定值。'),T(2,'电源6 V、固定10 Ω、变阻器20 Ω串联，电流多少A？',['0.2'],'6/(10+20)=0.2 A。'),T(2,'均匀变阻器全长40 Ω，接入四分之一长度，阻值多少Ω？',['10'],'长度与电阻成正比。'),C(2,'接两个下端时移动滑片，通常？',['阻值随位置变','全长阻值不变','无限电阻','产生电源'],1,'两端固定接入全部电阻丝。'),C(2,'接左端A与P，P向右移动，串联电流通常？',['增大','减小','始终不变','变负'],1,'有效段变长，总阻增加。'),C(3,'6 V电源，10 Ω固定电阻串联变阻器，电流上限0.3 A，变阻器至少？',['5 Ω','10 Ω','20 Ω','0 Ω'],1,'总阻≥20 Ω，滑阻≥10 Ω。'),C(3,'均匀滑阻最大30 Ω，接左端A，P由1/3长度处移到2/3，固定10 Ω、电源6 V，电流变化？',['0.3→0.2 A','0.2→0.3 A','0.6→0.3 A','0.1→0.2 A'],0,'滑阻10→20 Ω，总阻20→30 Ω。'),C(3,'固定R与滑阻串联，电源不变，滑阻减小，R两端电压？',['增大','减小','不变','为零'],0,'I增大，UR=IR增大。'),T(3,'电源12 V，固定20 Ω，要求电流0.3 A，串联滑阻应为多少Ω？',['20'],'总阻40 Ω，滑阻20 Ω。'),C(3,'0至50 Ω、允许0.5 A滑阻串联10 Ω与12 V电源，最小安全滑阻？',['14 Ω','24 Ω','0 Ω','50 Ω'],0,'总阻至少12/0.5=24 Ω，滑阻14 Ω。'),K('6 V电源、10 Ω固定电阻、最大20 Ω的滑动变阻器串联，忽略导线电阻。',[['滑阻为20 Ω时电流多少A？',['0.2']],['要使固定电阻两端为3 V，滑阻应为多少Ω？',['10']],['若电流不得超过0.4 A，滑阻最小多少Ω？',['5']]],'最大时I=6/30=0.2 A；UR=3 V则I=0.3 A，滑阻分3 V所以10 Ω；上限0.4 A需要总阻15 Ω，滑阻至少5 Ω。')],V('先圈出有效电阻丝 AP',line(80,178,680,178,'#b68a5e',9)+line(80,178,80,246)+line(680,178,680,246)+text(64,281,'A')+text(664,281,'B')+line(400,72,400,166,'#417e73')+`<path d="M392 150 L400 173 L408 150" fill="none" stroke="#417e73" stroke-width="3"/>`+text(389,60,'P')+line(80,202,400,202,'#cf8051',5)+text(177,235,'接A与P时：这段有效')+text(95,36,'P向A靠近 → 长度变短 → 电阻减小'),'图为原理展开图。换接B与P时，有效段变为PB，方向关系随之改变。'));
add('p16-5','跨学科实践：制作简易调光台灯','按需求设计低压调光电路，兼顾限流、亮度和能量利用。',['用低压电源、开关、灯泡和串联变阻器构成可调光模型。','亮度取决于灯的实际功率，改变串联电阻可改变灯的电流和电压。','设计先核对额定电压、电流及器件限值，连接前开关断开、滑阻最大。','测量多档电流、电压并记录亮度，使用P=UI比较实际功率。','LED有极性和限流要求，不能把白炽灯模型无条件换成裸LED。'],'低压实验模型与家庭市电台灯不同；不能直接改接220 V电源。',[
'制作简易调光台灯要把“能亮”提升为“亮度可调、工作稳定、使用合适”。先选择配套的低压电源和小灯泡，明确额定电压，再用串联滑动变阻器调节电流。设计图中应标出电源、开关、灯和变阻器接线，外壳和灯罩还要考虑固定、散热以及遮挡强光的问题。',
'串联电阻增大时，总电流一般减小，灯泡分到的电压和实际功率通常降低，灯变暗；电阻减小时则相反。灯不是“分到更少电荷就被用完”，而是每秒转化的电能发生变化。白炽灯发光同时强烈发热，灯丝电阻随温度变化，所以精确分析要用每档实测U和I，不能把热态电阻固定用于所有档位。',
'实施时保持开关断开，将滑阻接成一上一下并调到最大；电流表串联，电压表跨灯。检查后接通，缓慢移动滑片，每档记录电压、电流和观察条件相同的亮度。不要超过灯的额定电压及各仪表量程。若达到额定状态，应停止继续提高，不以“再亮一点”作为超额定工作的理由。',
'一只标3 V的灯，在某档测到2.0 V、0.20 A，实际功率为0.40 W；另一档3.0 V、0.25 A，功率0.75 W，通常后一档更亮。电源若为4.5 V，后一档串联电阻分得1.5 V，阻值1.5/0.25=6 Ω，滑阻消耗功率1.5×0.25=0.375 W。',
'调光设计也需考虑能量效率。串联变阻器会发热，有一部分电能没有用于灯的发光；电源电压远高于灯额定电压时，串联电阻可能浪费较多能量。若采用LED，需要核对正负极、允许电流和限流方案；本实践可讨论改进方向，但不能把白炽灯的电阻计算直接当作LED的恒定电阻模型。',
'测试报告应包括工作范围、亮度比较、实际功率、温升及材料选择。若评价两种灯罩效果，要保持同一灯功率、测量距离和环境光，不应一边调大电流一边换灯罩。设计迭代可改善光照方向和结构稳定性，使用低压电池供电的模型展示，不接入家庭市电，更不拆改在用台灯的高压部分。'
],[C(1,'低压调光模型中滑动变阻器通常与灯？',['串联','仅接一端','直接短接','作为电源'],0,'串联调节回路电流。'),C(1,'灯亮度主要与什么相关？',['实际功率','外壳颜色','标志字数','导线长度单独决定'],0,'每秒转化电能影响亮度。'),C(1,'接通前滑阻通常置于？',['最大阻值','零阻值','任意不检查','中间必正确'],0,'限制起始电流。'),C(1,'灯的额定电压表示？',['正常工作的电压','永远实际电压','最大电源体积','绝缘电阻'],0,'应按额定条件使用。'),M(2,'设计应核对？',['灯额定电压','变阻器允许电流','电表量程','只看外壳美观'],[0,1,2],'性能和安全限值必须同时满足。'),M(2,'合理测试做法有？',['逐档记录U与I','改变灯罩时保持灯功率相同','直接接市电验证亮度','记录发热与稳定性'],[0,1,3],'模型只用合适低压电源。'),T(2,'灯两端2.5 V，电流0.20 A，功率多少W？',['0.5','0.50'],'P=UI=0.50 W。'),T(2,'电源4.5 V，灯分3 V，串联变阻器两端多少V？',['1.5'],'总电压减灯电压。'),C(2,'调小串联变阻器后，灯通常？',['变亮','必变暗','必不变','电阻必为零'],0,'电流及实际功率通常增大。'),C(2,'把裸LED直接替代灯泡，最需注意？',['极性及限流','颜色一样即可','不需要电源','必为定值电阻'],0,'LED不是恒阻元件。'),C(3,'电源6 V，灯正常3 V、0.3 A，串联限流电阻与其耗功为？',['10 Ω、0.9 W','20 Ω、1.8 W','10 Ω、1.8 W','5 Ω、0.45 W'],0,'剩3 V，R=3/0.3=10 Ω，P=3×0.3=0.9 W。'),C(3,'调光档A为2 V、0.2 A，B为3 V、0.25 A，灯电阻和功率变化？',['均增大','电阻减小功率增大','均不变','电阻增大功率减小'],0,'R10→12 Ω，P0.4→0.75 W。'),C(3,'两灯罩测试中A灯功率高、B灯功率低，A看起来亮，能否归因灯罩？',['能','不能，功率也是变量','必A更优','必B更优'],1,'需控制光源功率与环境。'),T(3,'电源4.5 V，灯3 V、0.25 A，总输入功率多少W？',['1.125'],'P总=4.5×0.25=1.125 W。'),C(3,'同样灯功率0.75 W，方案甲总耗1.5 W，乙总耗1.0 W，照明条件相同，乙的灯用电比例比甲？',['高25个百分点','低25个百分点','高50个百分点','相同'],0,'甲50%，乙75%，差25个百分点。'),K('调光模型电源恒为6 V，灯正常电压3 V。某档测灯3 V、0.20 A，另一档测灯2 V、0.15 A。',[['正常档灯功率多少W？',['0.6']],['正常档串联滑阻多少Ω？',['15']],['较暗档滑阻电阻约多少Ω？保留一位小数。',['26.7']]],'正常P=3×0.2=0.6 W，滑阻(6−3)/0.2=15 Ω；暗档滑阻(6−2)/0.15≈26.7 Ω。')],circuitVisual('series',['台灯L','调节电阻R']));
unit(17,'欧姆定律','从控制变量实验建立I、U、R关系，解决测量、分压、分流与动态电路。');
add('p17-1','电流与电压和电阻的关系','设计探究实验，理解正比、反比关系各自的前提条件。',['电阻一定时，通过导体的电流与两端电压成正比。','电压一定时，通过导体的电流与电阻成反比。','探究I与U关系需固定电阻并调节电压；探究I与R关系需保持被测电阻两端电压。','换较大电阻后，通常需增大串联滑阻以恢复被测电阻原电压。','定值电阻的I—U图在条件近似不变时为过原点直线，I—R图一般不是直线。'],'“成正比”不仅是一起变大，还要求比值恒定；比较时控制条件不能省。',[
'研究电流受哪些因素影响，需要把电压和电阻分开考察。在导体电阻保持一定时，电流与电压成正比；在电压保持一定时，电流与电阻成反比。这两句话的前半句是规律成立的必要限定，不应在背诵时略去。实际实验尽量选择温度变化不大的定值电阻。',
'正比意味着电压变为原来两倍，电流也变为两倍，I/U保持恒定；仅仅看到二者一起变大还不够。反比意味着电阻倍增、电流减半，IR保持恒定。若灯丝发热后电阻改变，I与U的图线可能弯曲，不说明实验失败，而是研究对象已不符合“电阻一定”的条件。',
'探究电流与电压时，电阻保持不变，滑动变阻器与其串联用来调节电压，电流表串联、电压表跨被测电阻，记录多组U和I。探究电流与电阻时，更换不同电阻后每次都调滑阻，使电压表恢复到同一目标值，再读取电流；不能只保证电源电压不变。',
'电源6 V，目标被测电压2 V。换用5 Ω电阻时电流0.4 A，滑阻需分4 V，所以为10 Ω；换为10 Ω电阻时电流0.2 A，为了仍分4 V，滑阻应调至20 Ω。若滑阻最大只有15 Ω，就无法保持目标电压，第二组不能直接纳入同条件比较。',
'图像读法先认轴。I为纵轴、U为横轴，定值电阻图线斜率I/U等于1/R，线越陡电阻越小；如果把U放纵轴，斜率就变成R，结论随坐标改变。I与1/R关系在U恒定时为直线，但I与R为曲线，不要把所有“有规律”误认为线性。',
'多次测量的目的之一是验证关系在多组条件下是否成立，而不是把不同电压下的电流简单求平均。检查异常值应回看量程、接触、电阻温升和目标电压。保留原始表格并给出依据后再讨论偏差；不能为了画过原点的直线任意修改数据，真实实验允许在合理误差范围内接近理论关系。'
],[C(1,'研究I与U关系应保持？',['电阻不变','电压不变','电流不变','时间总相同即可'],0,'控制R，改变U。'),C(1,'研究I与R关系应保持？',['电阻不变','被测电阻两端电压不变','电流不变','导线颜色相同即可'],1,'控制U，改变R。'),C(1,'R不变时U加倍，I？',['加倍','减半','不变','变为零'],0,'I与U成正比。'),C(1,'U不变时R加倍，I？',['加倍','减半','不变','四倍'],1,'I与R成反比。'),M(2,'正确结论有？',['正比要求比值恒定','反比要求乘积恒定','只要同增就一定正比','需控制变量'],[0,1,3],'同增不必成正比。'),M(2,'探究I与R时合理操作有？',['换电阻前断电','换后调回目标电压','只保持电源电压相同就足够','记录实际被测电压'],[0,1,3],'分压会随电阻变化。'),T(2,'同电阻在2 V时0.2 A，在4 V时电流多少A？',['0.4'],'电压倍增电流倍增。'),T(2,'恒定电压下5 Ω时0.6 A，15 Ω时多少A？',['0.2'],'R变3倍，I变1/3。'),C(2,'I纵轴、U横轴直线越陡，电阻？',['越大','越小','一定相同','无定义'],1,'斜率=1/R。'),C(2,'同一灯泡升温后I—U曲线弯曲，主要提醒？',['灯丝电阻可能变化','电流不存在','电压无法测量','一定读数错误'],0,'R一定条件可能不满足。'),C(3,'被测10 Ω定值电阻与滑动变阻器串联接恒定6 V电源，忽略电表影响。要使被测电阻两端保持2 V，滑阻应为多少？',['10 Ω','20 Ω','30 Ω','5 Ω'],1,'I=0.2 A，滑阻分4 V，R=20 Ω。'),C(3,'被测定值电阻与滑动变阻器串联接恒定6 V电源，理想电表测量。要求被测电阻两端保持2 V，滑阻最大30 Ω，被测电阻最大可用多少？',['15 Ω','30 Ω','60 Ω','10 Ω'],0,'滑阻=2R被测，所以R≤15 Ω。'),C(3,'被测定值电阻与滑动变阻器串联接恒定电源，忽略电表影响。换成较大的被测电阻且不调滑阻，其两端电压怎样变化？',['升高','降低','保持原值','必为零'],0,'分压比例R/(R+滑阻)增大。'),T(3,'恒定9 V电源给被测电阻与滑动变阻器串联电路供电，忽略电表影响。要求被测电阻两端3 V，换15 Ω电阻时滑阻应多少Ω？',['30'],'被测I=0.2 A，滑阻需分6 V，R=30 Ω。'),C(3,'数据U为1、2、3 V，I为0.1、0.2、0.4 A，能直接认定正比吗？',['能','不能，第三点比值不同需查原因','仅靠递增即可','正比不需比值'],1,'前两点10 Ω，第三点7.5 Ω，需核查。'),K('恒定6 V电源给被测电阻与滑动变阻器串联电路供电，目标被测电压3 V，分别用5 Ω、10 Ω、15 Ω电阻，忽略电表影响。',[['5 Ω组电流多少A？',['0.6']],['15 Ω组所需滑阻多少Ω？',['15']],['若滑阻最大10 Ω，15 Ω组能否保持3 V？填能或不能。',['不能']]],'电流3/5=0.6 A；目标电压为电源一半，滑阻需与被测电阻相等；15 Ω大于滑阻上限10 Ω。')],graphVisual('恒定电阻：I 与 U 成正比'));
add('p17-2','欧姆定律','用I=U/R解决同一导体、同一状态下的电压电流电阻问题。',['欧姆定律：通过导体的电流与两端电压成正比，与电阻成反比，I=U/R。','三个物理量必须对应同一导体、同一状态，单位用A、V、Ω。','变形U=IR、R=U/I；R=U/I是测量表达式，不表示R由U、I决定。','定值电阻需近似恒温；灯泡等电阻可能随工作状态变化。','先识电路与被测对象，再列规律，动态变化需区分不变量和变量。'],'不能把电源总电压与某支路电流、另一个电阻混在同一公式。',[
'欧姆定律将电流、电压和电阻联系起来：I=U/R。它描述同一段导体在相应状态下的关系，电流单位用安培，电压用伏特，电阻用欧姆。公式可变形为U=IR和R=U/I，但变形不能改变各量必须对应同一对象和同一工作状态的要求。',
'同一个近似恒温的定值电阻接不同电压，电流会随电压变化，但电阻保持原值。由测量比值R=U/I计算电阻，并不是说加大电压就把电阻造得更大。灯泡情况不同，电压增大可能使灯丝温度明显升高，从而电阻改变，需按每个状态的U与I分别计算。',
'做题第一步标对象：电源总量、某个电阻、某条支路不要混用。第二步标状态：开关变化前后、滑片移动前后分别列已知。第三步统一单位并选变形公式，最后判断结果是否合理。例如6 V电源接10 Ω电阻电流0.6 A；若算出60 A，应检查小数或单位转换。',
'一个定值电阻两端电压3 V、通过电流0.20 A，电阻为15 Ω。把它改接4.5 V且温度近似不变，电流为0.30 A。如果原来3 V是两个串联电阻的总电压，0.20 A是回路电流，求出的15 Ω只能是总电阻，不能自动当作其中任一个电阻的阻值。',
'动态电路中先找固定量。稳定电源电压不变，串联总电阻增加时总电流减小；固定电阻两端电压随电流减小，剩余更多电压由变阻器分担。并联支路的独立电流由共同电压和自身电阻决定，另一支路正常通断时不应把原电流简单均分给剩余支路。',
'安全范围题需把每个限制翻成不等式。例如电流表上限0.6 A、某电阻允许电压3 V且电阻10 Ω，那么通过该电阻不得超过0.3 A；串联回路还要同时满足滑阻允许电流。共同范围由最严格条件决定，求得数学结果后还要检查是否落在滑动变阻器的实际调节范围内。'
],[C(1,'欧姆定律表达式为？',['I=U/R','I=UR','R=UI','U=I/R'],0,'单位配套为A、V、Ω。'),C(1,'6 V加在20 Ω两端，电流为？',['0.3 A','120 A','3.3 A','0.03 A'],0,'6/20=0.3 A。'),C(1,'公式三个量需对应？',['同一对象同一状态','任意三个元件','只要单位相同','不同时间随意混用'],0,'对象与状态一致。'),C(1,'恒温定值电阻电压升高，其电阻？',['不变','必升高','必减小','变零'],0,'自身条件不变R不变。'),M(2,'可用的变形公式有？',['U=IR','R=U/I','I=U/R','R=UI'],[0,1,2],'R不是UI。'),M(2,'应用欧姆定律注意？',['单位统一','明确对应元件','关注温度变化','总电压可随意配局部电阻'],[0,1,2],'量必须对应。'),T(2,'电阻两端4 V，电流0.25 A，电阻多少Ω？',['16'],'4/0.25=16 Ω。'),T(2,'12 Ω电阻通过0.5 A，电压多少V？',['6'],'U=IR=6 V。'),C(2,'R=U/I应理解为？',['电阻一定与电压成正比','可用电压电流比值测电阻','I为零时电阻必无穷','电阻被电流制造'],1,'比值法不改变决定因素。'),C(2,'500 mA流过8 Ω电阻，电压？',['4000 V','4 V','0.004 V','16 V'],1,'0.5×8=4 V。'),C(3,'一电阻电压增2 V，电流增0.1 A且R恒定，R为？',['20 Ω','2 Ω','0.2 Ω','无法由差值求'],0,'ΔU=RΔI，R=20 Ω。'),C(3,'同一恒温定值电阻电压从3 V到5 V，电流增加0.2 A，原电流是多少？',['0.3 A','0.5 A','0.2 A','0.8 A'],0,'R=2/0.2=10 Ω，原I=0.3 A。'),C(3,'电源6 V，固定10 Ω串联滑阻，固定电阻电压不能超3 V，电流表上限0.6 A，最大允许电流？',['0.6 A','0.3 A','0.9 A','0.2 A'],1,'电阻条件I≤3/10=0.3 A更严格。'),T(3,'同一恒温电阻在U时电流0.2 A，电压增加3 V后电流0.5 A，原电压多少V？',['2'],'R=3/(0.5−0.2)=10 Ω，U=0.2×10=2 V。'),C(3,'某灯3 V时0.3 A、6 V时0.4 A，不能用3 V状态的R直接预测6 V电流，是因为？',['灯丝温度及电阻改变','电压单位改变','电荷不守恒','电流表无效'],0,'R由10变15 Ω。'),K('定值电阻R在甲状态电压2 V、电流0.10 A；乙状态电压6 V；丙状态电流0.25 A，温度近似不变。',[['R多少Ω？',['20']],['乙状态电流多少A？',['0.3']],['丙状态电压多少V？',['5']]],'R=2/0.1=20 Ω；乙I=6/20=0.3 A；丙U=0.25×20=5 V。')],graphVisual('欧姆定律：同对象、同状态'));
add('p17-3','电阻的测量','完成伏安法实验、区分定值电阻与灯丝测量，并分析误差。',['伏安法用电压表测U、电流表测I，依据R=U/I求电阻。','电流表串联，电压表与被测元件并联，滑阻串联调节并保护。','测定值电阻可多次测量求电阻平均值，以减小随机误差。','测灯泡应比较不同状态R与温度关系，不把不同温度的阻值平均成固定电阻。','故障分析结合电流表、电压表、灯亮暗和连接位置，并说明单一故障条件。'],'求平均应先各组算R，不能随意把不同时刻U和I交叉相除。',[
'伏安法测电阻是同时测出被测元件两端电压和通过它的电流，再用R=U/I计算。这个方法把不易直接观察的阻碍作用转成可测电学量。实验中电流表串联，电压表并联在被测电阻两端，变阻器串联用来改变工作点并限制接通时的电流。',
'连接前开关断开，滑片调到接入电阻最大，按图连线后检查表的正负与量程。闭合后缓慢调节，记录同一状态下的U和I，再改变状态重复。若测定值电阻，应避免长时间大电流使其明显发热；温度变化较大时，测出的差异不再只来自随机误差。',
'数据处理时每组先算一个R，再对同一稳定电阻的各次结果求平均，并说明有效数字与单位。实验测灯丝电阻则目的不同：随着灯变亮、温度升高，电阻可能系统增加，平均这些值会掩盖物理变化。此时应绘制U—I或R随状态变化的图，解释温度影响。',
'某电阻三组数据为2.0 V与0.20 A、2.5 V与0.25 A、3.0 V与0.30 A，三组均得10 Ω。若第三组为3.0 V与0.29 A，得约10.34 Ω，平均约10.11 Ω，可结合分度值讨论偏差。不能为了得到整齐的10 Ω把原始0.29 A改为0.30 A。',
'在规定的串联测量电路里，只有被测电阻断路时，电流表可能无示数、电压表接近电源电压；被测电阻短路时，电压表接近零而电流可能增大。若表本身接线松脱、电源失效或存在多个故障，相同示数也可能有别的原因，所以题目必须提供限制条件，推断时要逐段检查。',
'更精细的模型考虑仪表并非理想：若电压表有电流且电流表读的是被测电阻与电压表两路总电流，分母偏大，算得R偏小；若电压表连同电流表的压降一起测量，分子偏大，算得R偏大。初中常按理想电表处理，但明确测量范围能帮助理解这些误差，而无需死记接法名称。'
],[C(1,'伏安法依据是？',['R=U/I','R=UI','R=I/U','R=Ut'],0,'测电压和电流比值。'),C(1,'电压表在伏安法中应？',['与被测电阻并联','与电源全部串联','代替导线','只接一端'],0,'测被测电阻两端。'),C(1,'闭合前滑阻？',['最大','最小','必须一半','不用接'],0,'保护电路。'),C(1,'测定值电阻多次测量的一个目的为？',['减小随机误差','改变单位','让电阻消失','只选最大值'],0,'重复测量可评估随机波动。'),M(2,'实验合理做法有？',['同状态读U、I','先各组算R','避免明显温升','把所有灯丝不同温度阻值平均成额定R'],[0,1,2],'灯丝不同温度对应不同电阻。'),M(2,'测得数据2 V、0.2 A，正确结论有？',['R=10 Ω','电功率为0.4 W','R=0.4 Ω','U和I必须同一次状态'],[0,1,3],'R是商，P是积。'),T(2,'电压2.4 V，电流0.30 A，电阻多少Ω？',['8'],'2.4/0.3=8。'),T(2,'三次电阻为9.8、10.0、10.2 Ω，平均多少Ω？',['10','10.0'],'算术平均10.0 Ω。'),C(2,'灯越亮所测R越大，合理原因？',['温度升高','一定实验错','电流被消耗','电源电阻被复制'],0,'金属灯丝电阻与温度有关。'),C(2,'电流为0、电压表近电源电压，单故障位于被测R，则R可能？',['断路','短路','正常必然','变为零'],0,'电压表跨断路处可测电源电压。'),C(3,'电流表读0.21 A，其中电压表分流0.01 A；U=2 V，被测R真实值为？',['10 Ω','9.52 Ω','20 Ω','0.42 Ω'],0,'真实电流0.20 A，R=10 Ω。'),C(3,'电压表测到被测R与电流表共同压降，用U/I求被测R，结果？',['偏大','偏小','一定准确','变零'],0,'包含了电流表的电阻。'),C(3,'被测10 Ω定值电阻与滑动变阻器串联接恒定6 V电源，忽略电表影响。要求被测电压3 V，滑阻最大5 Ω，能否实现？',['能','不能，需10 Ω滑阻','必须0 Ω','只换电压表即可'],1,'两者分压各3 V需相等阻值。'),T(3,'三组U、I分别(1.5,0.15)、(2.0,0.20)、(2.5,0.25)，平均电阻多少Ω？',['10'],'三组均为10 Ω。'),C(3,'某组灯丝电阻随亮度单调增大，最合理处理？',['取平均当恒定阻值','分别标注各工作点并分析温度','删去高值','只保留最小值'],1,'不同状态不是同一个恒定量的随机误差。'),K('用理想电表测小灯泡，表中三组数据均为真实工作状态。',[['第一组电阻多少Ω？',['5']],['第三组电阻多少Ω？',['10']],['能否把三组阻值平均视为灯丝固定电阻？填能或不能。',['不能']]],'1/0.2=5 Ω，3/0.3=10 Ω；灯丝温度改变，阻值也改变。',{headers:['电压/V','电流/A'],rows:[['1.0','0.20'],['2.0','0.25'],['3.0','0.30']]})],graphVisual('灯丝：不同工作点的电阻不同','lamp'));
add('p17-4','欧姆定律在串、并联电路中的应用','综合串并联规律分析等效电阻、分压分流和动态范围。',['串联总电阻R总=R₁+R₂，电压之比U₁:U₂=R₁:R₂。','并联满足1/R总=1/R₁+1/R₂，支路电流之比I₁:I₂=R₂:R₁。','串联总阻大于任一分电阻，并联总阻小于任一支路电阻。','动态电路先看总阻与总流，再回到各元件电压、电流与量程。','开关状态改变后重新识别连接，不能沿用另一状态的分压或分流。'],'分压与电阻同向，分流与电阻反向；比例只在同一个串联或并联状态下使用。',[
'把欧姆定律与串并联规律结合，就能把多个电阻等效成一个电阻。串联电流相同，总电压相加，所以总电阻为各电阻之和。并联电压相同，总电流相加，所以总电阻倒数为各支路电阻倒数之和。两个并联电阻还可写为R总=R₁R₂/(R₁+R₂)，条件必须是真正并联。',
'串联像把导电路径加长，总阻变大；并联像增加可走的通道，总阻变小。这种类比帮助检查答案：10 Ω与20 Ω并联不可能得到30 Ω，也不可能大于10 Ω。10 Ω与20 Ω串联则为30 Ω，相同电流下20 Ω分到的电压是10 Ω的两倍。',
'解题先识别节点、去掉理想导线形状的干扰，再按总量到局部的顺序。串联常先求总阻和电流，再求分电压；并联常先用共同电压求支路电流，再相加得到总电流。比例方法虽快，也要写出依据，尤其并联电流比与电阻比相反，不能凭印象套。',
'6 Ω与3 Ω并联在6 V电源上，各电流1 A、2 A，总电流3 A，总电阻2 Ω。如果同两电阻改为串联，总阻9 Ω，电流2/3 A，两端电压分别4 V、2 V。相同元件和相同电源，连接不同使电流、功率差别很大，这是家庭并联和实验保护都必须重视的原因。',
'滑动变阻器与定值电阻串联，滑阻增大，总电流减小，固定电阻电压减小，而滑阻分到的电压增大。滑阻功率却不一定一直增大或一直减小，因为P=I²R中的I和R同时变；若需分析极值，应在初中范围内用具体数据或给定关系检验，不能只盯着一个因子。',
'多状态题可分别画两幅简图，标同一个电源U及已知电流，再列两个方程。安全范围题要同时检查电流表、电压表、滑阻和负载限值，有时上限来自电流表，下限来自电压表。最后把计算值代回各元件，核对电压和是否等于总电压、电流和是否等于干路电流，这也是主动发现算错的办法。'
],[C(1,'5 Ω和10 Ω串联总阻？',['15 Ω','5 Ω','3.33 Ω','50 Ω'],0,'串联相加。'),C(1,'两只10 Ω并联总阻？',['20 Ω','10 Ω','5 Ω','0 Ω'],2,'两等阻并联为一半。'),C(1,'串联分电压与电阻之比？',['相同','相反','无关','总为1:1'],0,'U=IR，同I。'),C(1,'并联分电流与电阻之比？',['相同','反比','总1:1','无电流'],1,'I=U/R，同U。'),M(2,'正确的有？',['串联总阻大于任一分阻','并联总阻小于任一支路阻值','并联电压相等','串联电流一定均分'],[0,1,2],'串联电流处处相等，没有分流。'),M(2,'串联固定R与滑阻，滑阻增大时？',['总电流减小','固定R电压减小','滑阻电压增大','总电源电压必变大'],[0,1,2],'理想稳定电源电压固定。'),T(2,'6 Ω、3 Ω并联，总阻多少Ω？',['2'],'6×3/(6+3)=2。'),T(2,'2 Ω、4 Ω串联接6 V，4 Ω两端电压多少V？',['4'],'总电流1 A，分压4 V。'),C(2,'并联两电阻比2:3，电流比为？',['2:3','3:2','1:1','4:9'],1,'电流反比分配。'),C(2,'串联接入新电阻且电源稳定，总电流？',['增大','减小','不变','无限大'],1,'总电阻增大。'),C(3,'10 Ω与R串联接6 V，I=0.2 A；改并联同电源，干路电流？',['0.9 A','0.6 A','0.3 A','0.2 A'],0,'串联总阻30，R=20；并联I=6/10+6/20=0.9 A。'),C(3,'两个电阻串联总30 Ω，并联总20/3 Ω，则可能是？',['10 Ω与20 Ω','5 Ω与25 Ω','15 Ω与15 Ω','1 Ω与29 Ω'],0,'10×20/30=20/3。'),C(3,'12 V电源、10 Ω固定R与滑阻串联，R两端≤6 V且I≤0.5 A，最小滑阻？',['10 Ω','14 Ω','24 Ω','2 Ω'],1,'I≤0.5更严，总阻≥24，滑阻≥14。'),T(3,'6 V电源并联R₁=10 Ω及R₂，干路0.9 A，R₂多少Ω？',['20'],'I₁=0.6，I₂=0.3，R₂=6/0.3=20。'),{...C(3,'读图：图中R₁=10 Ω、R₂=20 Ω并联，电源6 V，则总电流和总电阻是？',['0.9 A、20/3 Ω','0.2 A、30 Ω','0.3 A、20 Ω','0.6 A、10 Ω'],0,'分流0.6与0.3 A，总0.9 A，R总=6/0.9=20/3 Ω。'),diagram:circuitVisual('parallel',['R₁=10 Ω','R₂=20 Ω']).svg},K('电源电压恒定，R₁=10 Ω。R₁与R₂串联时电流0.2 A，改并联后R₁支路电流0.6 A。',[['电源电压多少V？',['6']],['R₂多少Ω？',['20']],['并联后干路电流多少A？',['0.9']]],'并联R₁电压为电源U=0.6×10=6 V；串联总阻6/0.2=30 Ω，R₂=20 Ω；并联I=0.6+6/20=0.9 A。')],circuitVisual('parallel',['R₁=6 Ω','R₂=3 Ω']));
unit(18,'电功率','用电能和功率评价用电效果，通过测量与焦耳定律分析节能和发热。');
add('p18-1','电能 电功','识读电能表并联系W=UIt，计算能耗、费用与能量转化。',['电能可转化为内能、光能、机械能等，电流做功的过程就是电能转化的过程。','电功W=UIt，单位配套为V、A、s时得到J。','生活中常用kW·h计量电能，1 kW·h=3.6×10⁶ J，俗称1度电。','电能表显示累计电能，某段消耗量等于后读数减前读数。','脉冲常数N imp/(kW·h)表示消耗1 kW·h对应N次脉冲，不能当成功率。'],'功率是快慢，电能是总量；电能表的累计示数不能直接当成本月用电量。',[
'电能是能量的一种形式。电流通过用电器时，电能转化成其他形式的能量，电流做了多少功，就有多少电能发生转化。在电压、电流保持稳定的条件下，电功可用W=UIt计算；如果工作状态不断变化，应按阶段计算后相加，不能把某一瞬间电流当作全程值。',
'家庭电能表相当于记录总用电量的里程表，它显示从开始计量以来累积的电能。这个月用电量是月末减月初，而不是直接读月末数字。日常一度电就是1 kW·h，表示1 kW的用电器工作1 h消耗的电能，它是能量单位，不是功率单位，也不是“每小时用电一度”的重复写法。',
'计算先选择统一单位路线：用伏特、安培、秒得到焦耳；用千瓦、小时得到千瓦时。两套路线都正确，但不能用瓦乘小时后直接写焦耳。电能表若标2000 imp/(kW·h)，闪烁100次代表100/2000=0.05 kW·h，测量时间再结合电功率定义才能求平均功率。',
'某装置电压12 V、电流0.5 A，稳定运行10 min，电功为12×0.5×600=3600 J，等于0.001 kW·h。若电能表从01234.5变为01302.5，本段用电68.0 kW·h。假定每度0.60元且无阶梯差异，费用40.8元，实际收费要按题目或真实账单给定规则。',
'电能转化方向要与设备一致：电热器主要转化为内能，电动机主要转为机械能同时发热，灯转为光能和内能。输入电功不一定等于纯粹发热量，尤其电机带动负载时有机械输出。只有纯电阻电热模型且忽略其他能量变化时，才可把电功全部视为产生的热量。',
'用电能表测单个用电器时，其他用电器应停止工作，或明确扣除它们的贡献；若空调、冰箱周期启停，应测足够长时间再给平均值。测量只观察已有仪表和公开铭牌，不打开电能表或触碰带电线路。报告需注明时间范围、计量常数和工作状态，便于别人复算。'
],[C(1,'1度电等于？',['1 kW·h','1 kW','1 A','1 V'],0,'度是生活中的电能单位。'),C(1,'电能表主要测量？',['电能','电阻','温度','瞬时电流'],0,'记录累计用电量。'),C(1,'W=UIt中t用s，W单位为？',['J','W','Ω','A'],0,'V·A·s=J。'),C(1,'1 kW·h等于？',['3.6×10⁶ J','3600 J','1000 J','3.6 J'],0,'1000 W×3600 s。'),M(2,'正确的有？',['用电量为示数之差','电功表示转化的电能','kW·h是功率','电机输入能量不全转化为热'],[0,1,3],'千瓦时是能量。'),M(2,'用电能表测单台电器应？',['确认其他负载贡献','记录计量常数','记录时间','拆开带电表壳'],[0,1,2],'无需操作带电内部。'),T(2,'6 V、0.2 A工作50 s，电功多少J？',['60'],'6×0.2×50=60 J。'),T(2,'表初值320.5、末值350.0 kW·h，本段用电多少度？',['29.5'],'350−320.5=29.5。'),C(2,'2000 imp/(kW·h)的表闪100次，电能？',['0.05 kW·h','20 kW·h','0.5 kW·h','100 kW·h'],0,'100/2000=0.05。'),C(2,'3000 J输入电动机，有用机械功2400 J，其余发热，热量？',['3000 J','600 J','2400 J','5400 J'],1,'能量守恒相减。'),C(3,'2000 imp/(kW·h)电能表在6 min闪100次，仅该电器工作，其平均功率？',['500 W','1000 W','50 W','300 W'],0,'W=0.05 kW·h，t=0.1 h，P=0.5 kW。'),C(3,'两电器先后各工作半小时，功率100 W、900 W，总耗电与全程平均功率？',['0.5 kW·h、500 W','1 kW·h、1000 W','0.5 kW·h、1000 W','0.25 kW·h、500 W'],0,'总能0.05+0.45=0.5，时间1 h。'),C(3,'电费前100度0.5元/度，超过部分0.8元/度，本月140度，费用？',['82元','70元','112元','90元'],0,'100×0.5+40×0.8=82。'),T(3,'电压12 V、电流2 A工作5 min，再以1 A工作10 min，总电功多少J？',['14400'],'12×2×300+12×1×600=14400。'),C(3,'某电表6 min共耗0.08度，其他固定负载0.2 kW同时工作，这6 min内目标电器的平均功率是多少？',['0.6 kW','0.8 kW','1.0 kW','0.2 kW'],0,'总平均0.08/0.1=0.8，减0.2为0.6。'),K('电能表常数2500 imp/(kW·h)，只让一台电热器工作，5 min闪250次。',[['消耗电能多少kW·h？',['0.1']],['平均功率多少W？',['1200']],['按0.6元/度，持续同功率工作2 h费用多少元？',['1.44']]],'W=250/2500=0.1度；P=0.1/(5/60)=1.2 kW；2 h耗2.4度，费用1.44元。')],V('读电能表：末数减初数',rect(55,73,292,109)+text(84,115,'月初 01234.5',28)+text(112,157,'kW·h',20)+rect(414,73,292,109)+text(443,115,'月末 01302.5',28)+text(473,157,'kW·h',20)+arrow(354,130,403,130)+text(124,245,'本月：1302.5 − 1234.5 = 68.0 kW·h',24),'电能表显示累计消耗量；本段用电量要作差。数字及费用示例仅作计算练习。'));
add('p18-2','电功率','区分额定与实际功率，测小灯泡功率并处理电路综合。',['电功率表示电流做功快慢，P=W/t=UI，单位W。','额定功率是额定电压下的功率，实际功率由实际工作状态决定。','纯电阻模型可用P=I²R=U²/R；非纯电阻设备需慎用这些变形式。','测灯泡额定功率需调至额定电压，再读电流计算P=UI。','灯亮度通常取决于实际功率，不只比较额定功率标注。'],'不同电压下灯丝温度改变，不能默认其电阻恒定，除非题目明确忽略变化。',[
'电功率用来表示电流做功快慢，定义为电功与所用时间之比，P=W/t，单位瓦特。在电压、电流相对稳定时，P=UI。功率大表示同样时间转化电能更多，并不自动表示某次总耗电更多，因为工作时间也参与决定总电能。',
'额定电压是用电器正常工作所需的电压，额定功率是额定电压下对应的功率。“220 V 100 W”不是说不管接多少电压都消耗100 W。当实际电压变化时，实际电流和功率也可能变化。灯泡亮暗应看当前实际功率，不能只把额定标注大的灯判为任何接法下都更亮。',
'测小灯泡功率时，电流表串联、电压表跨灯、滑阻串联，接通前滑阻最大。逐渐调到电压表等于额定电压，读取当时电流，计算额定功率。再测略低于额定电压的状态作比较。灯在不同电压下温度不同，各点功率是不同工作状态，不应求平均作为额定功率。',
'额定3 V的灯在正常状态电流0.25 A，额定功率0.75 W，热态电阻12 Ω。若题目明确“忽略灯丝电阻变化”，接2 V时功率可算4/12=1/3 W；真实灯丝温度降低后电阻会改变，精确功率应由实测U、I或给定图线求得，不能忽略模型条件。',
'对纯电阻，结合欧姆定律得到P=I²R和P=U²/R。串联电流相同，电阻大的元件功率大；并联电压相同，电阻小的元件功率大。两个看似相反的结论各有条件。电动机把部分电能变成机械能，输入P=UI仍可用，但不能把U/I视作线圈纯电阻后认为所有能量都是焦耳热。',
'综合题常同时限制电压表量程、电流表量程、灯泡额定值和滑阻规格。先以最严格约束确定允许电流，再求阻值范围与功率范围。若用I—U图读灯泡工作点，串联时电流相同、各电压之和为电源电压；并联时电压相同。只有这些关系同时满足的图上点才是实际状态。'
],[C(1,'电功率表示？',['做功快慢','累计电荷','电压高低唯一指标','电阻大小'],0,'P=W/t。'),C(1,'P=UI单位配套为？',['W、V、A','J、V、Ω','A、W、s','Ω、V、A'],0,'伏安积单位瓦。'),C(1,'“3 V 0.6 W”中0.6 W是？',['额定功率','任意电压下实际功率','总电能','电阻'],0,'额定电压对应额定功率。'),C(1,'同样时间功率更大，耗电？',['更多','更少','必相同','为零'],0,'W=Pt。'),M(2,'正确的有？',['灯亮度看实际功率','额定值是正常工况','测额定功率要调到额定电压','不同工况功率取平均必为额定功率'],[0,1,2],'不同状态不应混成额定值。'),M(2,'恒定纯电阻可用的公式有？',['P=UI','P=I²R','P=U²/R','P=UR'],[0,1,2],'由欧姆定律推得。'),T(2,'灯3 V、0.2 A，功率多少W？',['0.6'],'UI=0.6。'),T(2,'10 Ω电阻接5 V，功率多少W？',['2.5'],'25/10=2.5。'),C(2,'两电阻串联且R₁>R₂，则功率？',['P₁>P₂','P₁<P₂','必相同','无法按条件比较'],0,'同I，P=I²R。'),C(2,'两电阻并联且R₁>R₂，则功率？',['P₁>P₂','P₁<P₂','必相同','都为零'],1,'同U，P=U²/R。'),C(3,'两灯“6 V 3 W”“6 V 6 W”，忽略阻变，串联接6 V，功率较大的是？',['3 W灯','6 W灯','相同','都额定'],0,'电阻分别12、6 Ω，串联同I，大电阻实际功率大。'),C(3,'电源6 V，灯额定3 V 0.9 W，正常时串联电阻消耗的电功率是多少？',['0.9 W','1.8 W','0.3 W','0.45 W'],0,'I=0.3 A，滑阻分3 V，P=0.9 W。'),C(3,'“220 V 100 W”电热器忽略阻变，接110 V实际功率？',['25 W','50 W','100 W','200 W'],0,'U减半，P为1/4。'),T(3,'两个10 Ω电阻先串联后并联接同6 V电源，并联总功率是串联总功率多少倍？',['4'],'串联总20 Ω，并联5 Ω，同U功率比20/5=4。'),C(3,'灯数据1 V、0.2 A；2 V、0.25 A；3 V、0.3 A。与10 Ω电阻串联接4.5 V，实际电流是？',['0.2 A','0.25 A','0.3 A','0.5 A'],1,'0.25 A时灯两端2 V，定值电阻分2.5 V，两者之和4.5 V，恰好等于电源电压。'),K('低压灯额定3 V，正常电流0.20 A，与滑阻串联接6 V电源。',[['灯额定功率多少W？',['0.6']],['正常状态灯电阻多少Ω？',['15']],['正常状态总输入功率多少W？',['1.2']]],'P灯=3×0.2=0.6 W；R灯=3/0.2=15 Ω；总P=6×0.2=1.2 W。')],graphVisual('测灯功率：读取同一工作点','lamp'));
add('p18-3','跨学科实践：为家庭节约用电提建议','通过功率、时间和使用需求估算节电收益，并设计可验证建议。',['节电建议先建立用电账本：额定/实测功率、工作时间和启停情况。','电能W=Pt，功率用kW、时间用h时，电能为kW·h。','待机功率虽小，长时间累积也可能可观。','比较方案需保证服务效果相近，并考虑设备成本、使用寿命和回收期。','使用电能表或合格成品计量设备记录，不拆改家庭带电线路。'],'空调、冰箱等并非一直按额定功率运行；用额定功率乘全天时间只是特定假设下估算。',[
'家庭节约用电不是简单把所有电器关掉，而是在满足照明、学习、保鲜等需求的前提下减少不必要消耗。实践第一步调查主要设备功率、每天运行时间和控制方式，区分持续工作、周期启停、待机三类情况，再建立每日或每月能耗表，找到贡献最大的环节。',
'一只10 W灯和一台1000 W设备相比，瞬时功率很小，但若灯全年长时间无效亮着也会浪费能量。另一方面，冰箱压缩机不会全天持续工作，不能直接以铭牌功率乘24 h当作精确日耗电。真实计量数据比仅靠额定标注更贴近情况，应注明估计假设与测量时段。',
'用W=Pt计算时，功率换成kW，时间换成h。统计多个设备分别相乘再相加，不要把最大同时功率和月总能耗混为一谈。更换灯具应保证照明效果相当，减少待机可在确实不需要保持功能时断电。对空调等设备，合理设定、密封保温与维护清洁往往需要结合实际环境评估。',
'把一盏40 W灯换成照明效果相当的8 W灯，每天用5 h，每月按30天，节电(0.040−0.008)×5×30=4.8 kW·h。题设电价0.60元/度，每月省2.88元。若净新增成本28.8元且其他条件不变，简单回收期10个月，但未考虑寿命、维护和资金时间价值。',
'一个节能方案要有基准、行动与验证：先记录改进前一周相近使用条件下电量，再实施措施，再记录另一周。天气、家庭人数、使用需求明显不同会干扰结果，不能把所有电量下降都归因某一个新设备。可以使用单位服务量能耗，例如每次烧水耗电或相同照度下功率，使比较更公平。',
'成果可是一页建议书，列出优先措施、预计节电量、费用及限制条件，按收益和实施难度排序。不要以节电为由关闭必需的安全系统，也不自行改动插座和家庭线路。建议以合格成品与正常操作为基础，面对有待机功能或数据保存要求的设备，先了解其用途再决定是否断电。'
],[C(1,'估算电器能耗的核心公式是？',['W=Pt','W=P/t','R=UI','I=Pt'],0,'功率乘时间得到能量。'),C(1,'功率用kW、时间用h，能量单位？',['kW·h','W','A','Ω'],0,'单位相乘。'),C(1,'比较两灯节电应尽量保证？',['照明效果相当','外壳颜色相同','价格必相同','亮度任意'],0,'需满足相同服务需求。'),C(1,'长期待机是否耗电？',['可能耗电','绝对不耗电','只要屏黑就零','必等于额定全功率'],0,'待机仍可能有小功率。'),M(2,'用电调查应记录？',['功率','工作时间','周期启停状况','只记品牌名字'],[0,1,2],'能耗需反映使用状态。'),M(2,'合理节电建议有？',['减少无效照明','在需求相同时比较能效','擅自拆改带电线路','考虑待机时间'],[0,1,3],'实施需正常安全操作。'),T(2,'20 W灯每天5 h，30天耗电多少度？',['3'],'0.02×5×30=3。'),T(2,'2 W待机连续500 h，耗电多少度？',['1'],'0.002×500=1。'),C(2,'冰箱实际日耗电更适合通过？',['只拿额定功率乘24 h','足够时段电能计量','观察体积','看门颜色'],1,'需考虑启停周期。'),C(2,'相同日能耗下不同设备的同时总功率？',['必相同','不一定相同','都为零','就是电价'],1,'能量与时间安排有关。'),C(3,'40 W换8 W同效果灯，每天5 h、30天，节电和按0.6元/度省费？',['4.8度、2.88元','6度、3.6元','1.2度、0.72元','4.8度、28.8元'],0,'差32 W乘150 h=4.8度。'),C(3,'净新增成本36元，每月节电5度，电价0.6元/度，简单回收期？',['12个月','6个月','10个月','18个月'],0,'每月3元，36/3=12。'),C(3,'空调改进后节电20%，但当月降温需求比基准少30%，能否全归因措施？',['能','不能，外部条件变化干扰','节能无效必定','电表一定错误'],1,'需同服务和环境条件或做归一化分析。'),T(3,'设备工作100 W每天4 h，其余20 h待机5 W，一天总耗电多少度？',['0.5'],'0.1×4+0.005×20=0.5。'),C(3,'一措施每日省0.4度但新增设备每天耗0.1度，30天净节电？',['12度','9度','3度','15度'],1,'净0.3×30=9度。'),K('某家10 W灯每天6 h、电视80 W每天4 h。电视其余20 h待机3 W，每月30天。',[['灯每月耗电多少度？',['1.8']],['电视每月待机耗电多少度？',['1.8']],['若灯改8 W且电视非使用时完全断电，每月共节电多少度？',['2.16']]],'灯0.01×6×30=1.8；待机0.003×20×30=1.8；灯节0.002×6×30=0.36，总节2.16。')],V('同样照明效果下比较能耗',text(55,45,'每天使用5小时，每月按30天')+rect(65,80,250,145)+text(127,122,'原灯 40 W',23)+rect(95,150,185,35,'#e0b189')+rect(430,80,250,145)+text(490,122,'新灯 8 W',23)+rect(460,150,37,35,'#90c4b6')+text(134,289,'每月节电 (0.040 − 0.008) × 150 = 4.8度',21),'条形宽度示意相同时间下的能耗比例，比较须以照明效果相当为前提。'));
add('p18-4','焦耳定律','探究电流热效应并区分电功与焦耳热，计算电热综合。',['电流通过导体产生热量的现象叫电流的热效应。','焦耳定律Q=I²Rt，热量与电流平方、电阻和通电时间成正比。','研究电流影响需控制R和t，研究电阻影响需控制I和t。','纯电阻电热器中电功全部转化为热，Q=W；电动机一般Q<W。','电热有可利用的一面，也会导致导线损耗，电流过大特别危险。'],'Q=U²t/R仅在适用的纯电阻模型成立；比较热量前先确定同电流还是同电压。',[
'电流通过导体时导体会发热，叫电流的热效应。焦耳定律定量说明：导体产生的热量等于电流的平方、电阻和通电时间的乘积，Q=I²Rt。在I用安、R用欧、t用秒时，Q为焦耳。电流因素是平方关系，所以电流倍增时，同电阻同时间的热量变为四倍。',
'电热水壶、电饭锅利用电流热效应；导线发热过多则会浪费能量并损害绝缘层。保险丝、过载保护等措施与控制大电流风险有关。不能由“电阻越大热越多”得到无条件结论：串联同电流时大电阻发热多，并联同电压时大电阻电流小，发热功率反而可能较小。',
'探究电阻影响常把不同电阻丝串联，使电流相同，通电同样时间，用相同装置内空气膨胀或液体升温比较发热。探究电流影响则让电阻相同、电流不同，并保持通电时间一致。转换法把不易直接看见的热量大小转化为液柱高度或温升，但还要保持受热介质和散热条件相近。',
'2 A电流通过5 Ω电阻10 s，发热Q=2²×5×10=200 J。若电流变为3 A，其余不变，热量450 J，增加250 J。若同一5 Ω电阻接10 V，电流2 A，输入电功10×2×10=200 J，纯电阻情况下与发热量相等。',
'电动机正常转动时，输入电能一部分转为机械能，另一部分成为线圈等内能。线圈电阻2 Ω，电流1 A，时间10 s，线圈焦耳热20 J；若输入电压6 V，电功60 J，忽略其他损耗可输出40 J机械能。不能用U²t/R直接算180 J，原因是电源电压不等同于纯电阻压降模型。',
'电热综合题常有两次效率：燃料或电源提供能量，电热器发热，水只吸收其中一部分。先求热量，再用cmΔt求水温升，若升到沸点还要检查是否出现相变，不能让常压液态水按简单公式无限升温。算温升时质量用kg，所有能量先统一J，最终还应核对结果与实际边界是否相符。'
],[C(1,'焦耳定律为？',['Q=I²Rt','Q=IR/t','Q=IUt²','Q=R/I'],0,'电流平方乘电阻和时间。'),C(1,'同R同t，I加倍，热量为原来？',['2倍','4倍','1/2','不变'],1,'平方关系。'),C(1,'电热水壶利用？',['电流热效应','电磁感应必然','核裂变','摩擦起电'],0,'将电能转成内能。'),C(1,'热量单位为？',['J','A','V','Ω'],0,'焦耳。'),M(2,'探究电阻影响需控制？',['电流','通电时间','受热介质与装置','电阻相同'],[0,1,2],'电阻是自变量。'),M(2,'正确说法有？',['电动机电功不全是焦耳热','串联同I下大R发热功率大','任意电路都Q=U²t/R','过大电流会显著增加热损耗'],[0,1,3],'非纯电阻设备不能随意代换。'),T(2,'1 A通过10 Ω 20 s，发热多少J？',['200'],'1²×10×20=200。'),T(2,'2 A通过5 Ω，热功率多少W？',['20'],'I²R=20 W。'),C(2,'串联5 Ω与10 Ω，同时间发热比Q₅:Q₁₀？',['1:2','2:1','1:4','4:1'],0,'同I，热量与R成正比。'),C(2,'同电压并联5 Ω与10 Ω，同时间发热比？',['1:2','2:1','1:1','4:1'],1,'Q=U²t/R，与R反比。'),C(3,'电机6 V、1 A、线圈2 Ω，10 s输入电能与焦耳热为？',['60 J、20 J','180 J、60 J','20 J、60 J','60 J、60 J'],0,'W=UIt=60；Q=I²Rt=20。'),C(3,'标准大气压下，1000 W电热器持续100 s，84%的热量被2 kg、初温20 ℃的水吸收。c水=4200 J/(kg·℃)，忽略蒸发，水温升多少？',['10 ℃','20 ℃','40 ℃','5 ℃'],0,'Q=84000 J，Δt=84000/(8400)=10。'),C(3,'导线电阻不变，输电电流降为原1/5，同时间导线发热为原？',['1/5','1/25','5倍','25倍'],1,'焦耳热与电流平方成正比。'),T(3,'线圈R=2 Ω，电流3 A，运行60 s发热多少J？',['1080'],'9×2×60=1080。'),C(3,'两个相同电阻先串联后并联接同电源、同时间，并联总热量是串联的？',['2倍','4倍','1/4','相同'],1,'等效电阻由2R降至R/2，同U时热量增4倍。'),K('电机电压12 V、电流2 A、线圈电阻1 Ω，工作30 s，忽略线圈发热之外损耗。',[['输入电能多少J？',['720']],['线圈发热多少J？',['120']],['输出机械能多少J？',['600']]],'W=12×2×30=720；Q=2²×1×30=120；机械能600 J。')],V('同电阻、同时间：热量随电流平方增加',text(72,51,'R = 5 Ω，t = 10 s')+rect(80,92,230,120)+text(119,131,'I = 1 A',25)+text(119,180,'Q = 50 J',25)+rect(445,92,230,120,'#fae1cf')+text(484,131,'I = 2 A',25)+text(471,180,'Q = 200 J',25)+arrow(325,153,429,153)+text(210,284,'电流 ×2 → 发热量 ×4',25),'平方关系使过电流造成的发热显著增大；比较电阻影响时必须另行固定电流。'));
unit(19,'生活用电','理解家庭供电、触电防护与回路设计，以纸面和低压模型完成实践。');
add('p19-1','安全用电','识别触电、过载和短路风险，理解保护装置的作用边界。',['家庭照明供电常用220 V交流电，远高于通常安全接触范围。','触电危害来自电流通过人体，与电压、人体电阻、路径和时间有关。','避免接触低压带电体，不靠近高压带电体；湿手不触开关和插座。','过载和短路均可使电流过大，保护装置应匹配回路。','金属外壳保护接地与漏电保护各有作用，不能互相替代或私自旁路。'],'不能把“零线”理解为任何情况下都可触摸；不能用铜丝替代保险丝或绕开保护。',[
'安全用电的核心是避免不应有的电流通过人体，避免电路过热损坏。家庭常用供电电压为220 V交流电。人体接触带电部位后，若形成回路，就可能产生危险电流；危害不仅取决于电压，还与接触状况、人体电阻、电流路径和持续时间有关，不能以一次没事判断下一次安全。',
'皮肤潮湿时接触电阻可能降低，同样电压下通过人体的电流可能更大。因此湿手触开关、在潮湿地面接触破损导线都有额外风险。绝缘层、保护接地和漏电保护是不同防护环节，每一环节都可能因老化或故障失效，日常使用应保持器材完整，不自行拆除保护。',
'电流过大的主要原因包括同时接入过多高功率电器，以及火线和零线间出现低阻短路。判断过载可以按题目给定电压用总功率除以电压估算总电流，再与回路允许值比较。该计算仅用于学习和需求判断，真实线路的设计还涉及导线、安装条件和保护配合，应由专业人员完成。',
'在220 V模型回路中同时使用2200 W电热器和1100 W设备，电流分别10 A和5 A，总15 A。若插线板标明最大10 A，就超过其允许值。即使插孔还空着，也不能再接，因为孔数不代表总承载能力；“各设备单独都小于10 A”也不保证合用不超限。',
'保护接地使金属外壳在某些漏电故障下获得低阻保护通路，促使保护装置动作；漏电保护关注电流流入和流出的不平衡。二者作用不同，不能把接地线接成正常工作电流回路，也不能认为装了漏保就可以随意接触带电体。保险丝熔断后须查明原因，不以粗铜丝代替。',
'遇到有人触电，应先确保自身安全并切断电源，及时呼叫当地急救与专业救援，不直接徒手去拉带电人员。看到断落高压线应远离、警示周围并联系专业部门。学生实践限定在纸面分析与合适的低压模型，检验家庭隐患可记录外观和铭牌，不以身体或自制导线测试安全。'
],[C(1,'我国家庭常用供电电压约？',['220 V','3 V','12 V','1.5 V'],0,'常用单相家庭交流供电约220 V。'),C(1,'湿手不碰开关插座的原因之一是？',['人体接触电阻可能降低','电压单位改变','手会产生磁铁','电流必为零'],0,'可能增大通过人体的电流。'),C(1,'保险丝熔断后应？',['换铜丝','查明故障并用匹配保护','绕开保险丝','不断强行合闸'],1,'保护不能被旁路。'),C(1,'发现触电应先？',['徒手拉人','确保自身安全并切断电源','泼水','触摸测试'],1,'避免形成新的触电回路并呼救。'),M(2,'正确做法有？',['检查插线板总额定值','保持绝缘完整','金属外壳按规定接地','把地线作工作零线'],[0,1,2],'保护地线不能作正常载流回路。'),M(2,'可导致电流过大的原因有？',['用电总功率过大','火零低阻短路','多个大功率负载同时工作','正常断开一个支路必然'],[0,1,2],'正常断支路通常减少总电流。'),T(2,'220 V下2200 W电热器电流约多少A？',['10'],'P/U=10。'),T(2,'10 A插线板在220 V下总功率上限按模型多少W？',['2200'],'UI=2200。'),C(2,'装了漏电保护器后？',['可以触摸火线','仍须遵守正常用电规则','地线可拆除','不会发生任何故障'],1,'保护不是随意接触的许可。'),C(2,'插孔仍有空位，是否证明还能接大电器？',['是','不是，要核对总负载','空位决定功率','只看插头大小'],1,'总允许电流有限。'),C(3,'220 V、10 A回路已开1100 W与660 W，再接哪个会超限？',['220 W','330 W','550 W','110 W'],2,'已有1760 W，余440 W，550超限。'),C(3,'人体模型电阻从20 kΩ降至2 kΩ，接同220 V，电流变化？',['增10倍，至110 mA','减10倍','保持11 mA','增2倍'],0,'I=220/2000=0.11 A；仅为危险模型，不作实际测试。'),C(3,'设备外壳漏电，接地断开，能否只依靠其正常运行判断安全？',['能','不能，运行正常不证明保护完好','只看灯亮即可','电机响就安全'],1,'功能回路与保护回路是不同路径。'),T(3,'220 V、16 A回路同时用2200 W与1100 W，按功率模型还剩多少W余量？',['220'],'上限3520，已3300，余220；实际设计仍需完整规范。'),C(3,'某回路原功率2200 W，新增2200 W，导线电阻不变，工作同时间导线热量为原？',['2倍','4倍','1/2','相同'],1,'总I倍增，I²R发热增4倍。'),K('某学习模型回路220 V、最大10 A，电热器1100 W、电脑220 W、照明110 W同时工作。',[['总功率多少W？',['1430']],['总电流多少A？',['6.5']],['再接880 W电器是否超过最大电流？填是或否。',['是']]],'总1430 W，I=1430/220=6.5 A；新增后2310 W=10.5 A，超限。')],flowVisual('用电前的三项核对',['绝缘是否完整','总负载是否适合','保护是否完好','异常立即停用'],'纸面与低压模型学习，不拆改在用家庭线路'));
add('p19-2','家庭电路的基本组成','识别电能表、保护装置、火零地线和各支路的连接。',['家庭电路包含进户线、电能表、总开关和保护装置、支路、用电器及插座等。','用电器通常并联，独立开关与被控用电器串联且接在火线上。','三孔插座包含火线、零线和保护接地端，保护地线连接需接地的金属外壳。','火线与零线间有家庭供电电压，正常保护地线不承担工作电流。','电能表计量电能，断路器与漏电保护承担相应保护职责。'],'开关误接零线时灯虽能熄灭，但灯及部分线路仍可能对地带电。',[
'家庭电路从供电进户线开始，经过计量、总开关与相应保护装置，再分配到照明、插座和其他用电支路。各用电器通常并联在火线与零线之间，使它们得到相同的额定供电电压，并可以独立工作。电能表用于计量累计用电量，本身不能代替全部保护装置。',
'火线、零线和保护地线承担不同角色。火线与零线构成正常用电回路，保护地线用于安全防护，连接需要保护接地的金属外壳等位置，正常情况下不作为工作电流通道。它们不能因为颜色相近或都通向墙内就互换，更不能由学生凭肉眼猜测后改接。',
'单极开关应接在火线上并与被控制灯串联。这样断开时灯的供电端与火线断开。若开关接在零线上，灯可能也熄灭，但火线仍接到灯座相关部位，换灯或检修时存在危险。因此“能够控制亮灭”只是功能正确，不代表电路的安全连接正确。',
'两盏灯并联，每盏支路都有独立火线开关，一只开关断开只让对应灯熄灭，总开关断开则共同停止供电。若一盏灯丝断路，另一支路通常能继续工作；若某处短路，保护可能断开更大范围回路。这与理想并联正常通断的模型不同，不能将独立工作说成任何故障都互不影响。',
'三孔插座的保护接地端与用电器插头的保护端相连，进一步连接金属外壳。接地保护不能拿来弥补所有错误：接地线断了、火零接错、保护不匹配等都需要专业排查。课本示意图表达功能连接，真实安装还要遵守规范、使用认证器件，不能照着简图直接进行家庭布线。',
'读家庭电路图时，先沿火线找计量与保护，再看每条支路是否都有正常负载回到零线，最后核对开关和外壳保护端。重点检查有无把开关直接并在电源两线间、有无把保护地线串进负载、有无绕过保护。学习实验应把交流家庭图转换成低压灯模型，只模拟控制关系，明确其不具备真实家庭系统的全部功能。'
],[C(1,'家庭用电器通常？',['串联','并联','全部短接','不需回路'],1,'保证各自电压与独立工作。'),C(1,'单极灯开关应接？',['火线','保护地线','只接零线更安全','灯的两端并联'],0,'断开火线更合适。'),C(1,'电能表的主要作用？',['计量电能','代替保护地线','改变频率','给人体限流'],0,'电表不是全部保护装置。'),C(1,'三孔插座多出的保护端主要连？',['应接地的金属外壳','灯丝另一端','任意空线','零火短接点'],0,'用于保护接地。'),M(2,'正确连接原则有？',['负载并联','开关与对应负载串联','开关接火线','保护地线作日常工作回路'],[0,1,2],'保护地线不能任意代替零线。'),M(2,'判断家庭图需检查？',['保护装置位置','负载是否有正确回路','金属外壳保护接地','只看灯能否亮'],[0,1,2],'功能正确不保证防护正确。'),T(2,'控制单盏灯的开关与灯应串联还是并联？',['串联'],'串联控制这条支路通断。'),T(2,'两灯正常并联接220 V，单灯两端电压多少V？',['220'],'每支路都接电源两端。'),C(2,'开关接在零线，断开后灯不亮，是否说明灯座相关部位都不带电？',['是','否，仍可能与火线相连','电压自动归零所有处','保护已充分'],1,'火线未被开关切断。'),C(2,'保护地线正常情况下？',['承担全部工作电流','不应作为正常工作回路','必须和灯串联','可随意拆除'],1,'作用在保护连接。'),C(3,'两支路功率110 W、220 W接220 V，总电流？',['1.5 A','0.5 A','1 A','330 A'],0,'电流0.5+1=1.5 A。'),C(3,'灯并联但一开关跨火零两线，闭合会？',['正常控灯','形成短路风险','只切零线','自动降压'],1,'开关不能直接跨两供电线。'),C(3,'一灯开关断开灯灭，但其接电源的一端仍为火线，最可能设计问题？',['开关放在零线','电压不足','灯无电阻','两灯并联必错'],0,'控灯虽有效但没有切断火线。'),T(3,'三个并联支路各0.5、1、2 A，总回路电流多少A？',['3.5'],'支路电流相加。'),C(3,'外壳保护地线断开但电器工作正常，说明？',['安全已证明','功能回路完整但保护可能失效','地线本就没用','可一直不处理'],1,'工作零线与保护地线功能不同。'),K('纸面模型中火线L经过总开关S后分两支路：S₁串灯1、S₂串灯2，均回零线N。灯1功率110 W，灯2功率220 W，供电220 V。',[['两灯全亮时总电流多少A？',['1.5']],['仅断开S₁，灯2两端电压多少V？',['220']],['若要同时断开两支路供电，应断开哪个开关？',['S','总开关S','总开关']]],'支路电流0.5、1 A，总1.5 A；正常并联另一支路220 V不变；总开关切公共供电路径。')],V('家庭电路原理：支路并联、开关在火线',line(70,80,685,80,'#b86f53')+text(24,85,'L')+line(70,247,685,247,'#477c9b')+text(24,252,'N')+line(190,80,190,125)+line(190,125,205,148)+line(190,151,190,176)+`<circle cx="190" cy="198" r="22" fill="white" stroke="#396b64" stroke-width="3"/>`+line(177,184,203,212)+line(203,184,177,212)+line(190,220,190,247)+line(445,80,445,124)+line(445,124,460,147)+line(445,150,445,176)+`<circle cx="445" cy="198" r="22" fill="white" stroke="#396b64" stroke-width="3"/>`+line(432,184,458,212)+line(458,184,432,212)+line(445,220,445,247)+text(220,144,'S₁')+text(475,144,'S₂')+text(75,300,'仅为支路控制原理图；计量、保护和接地须另行完整设计',16),'图中两个开关均画为断开，且位于灯与火线之间。此图仅教学示意，不作为实际布线图。'));
add('p19-3','跨学科实践：为家庭电路做设计','用需求清单、负载计算与低压模型完成家庭回路方案。',['先调查房间用途、设备功率、使用时段和独立控制需求。','按并联支路与火线开关原则画功能图，标注保护与接地要求。','最大同时负载与一天总能耗不同，回路容量分析要使用同时功率。','按给定允许值核对总电流，纸面方案不能代替专业电气设计。','用低压灯模型测试所有开关组合和故障情形，再交流改进。'],'不依据小学式功率相加就自行选线布线；真实改造交给具备资格的专业人员。',[
'为家庭电路做设计，首先把居住需求转换成可检查的电路功能。例如书桌照明需要独立开关，厨房多台设备可能同时使用，公共区域可能需要总控。列清单时记录设备位置、额定功率、使用时间和是否同时运行，这些信息分别影响控制方案、回路承载与能耗估算。',
'最大同时功率是某一时刻可能一起开启的负载之和，决定相应回路电流；每天总电能则要逐台把功率乘运行时间再相加。一个功率很大的设备只运行短时，可能对瞬时负载影响大、对月能耗影响较小。两个指标不能互相替代，设计报告应分别列出。',
'功能图中把负载接成并联，独立开关与对应负载串联在火线一侧，并标注总开关、必要保护及金属外壳接地的要求。实际线径、敷设方式、保护配合与地区规范不由这张简图决定，学习设计只验证需求与基本原理。需要实际安装时，交给专业人员核定完整方案。',
'题设厨房回路220 V、允许16 A，同时使用电水壶1800 W和电饭锅1000 W，电流(1800+1000)/220≈12.73 A。若再开1200 W烤箱，总4000 W，对应18.18 A，超过给定上限。可调整使用安排或由专业人员评估回路，而不是简单把保护器换大。',
'低压模型可用两三盏小灯代替房间负载，验证总开关与支路开关。列开关组合表：总开关断开全部灭；总开关闭合时各灯由自身开关控制；断开一支路，其他正常支路仍可亮。模型验证的是控制连接，不验证真实220 V绝缘能力、接地或载流量，因此结论应说明边界。',
'展示材料包含需求表、功能电路图、负载核算、低压测试记录和改进理由。若比较两方案，把功能要求和允许值保持一致，解释为什么某方案避免过载、操作更方便或减少无效用电。保留无法确定的条件，例如已有线路规格未知，不编造精确施工结论；这正是把物理知识用于真实问题时的严谨。'
],[C(1,'设计第一步应？',['调查需求和设备功率','马上拆插座','只选漂亮外壳','把保护器换最大'],0,'先明确问题与条件。'),C(1,'各房间负载独立工作通常用？',['并联','全串联','全部短接','不接零线'],0,'并联各支路独立。'),C(1,'估算最大回路电流应关注？',['最大同时功率','只看月电费','插孔数量','灯罩颜色'],0,'I≈P同时/U。'),C(1,'学生验证功能图适合？',['低压模型','直接市电试接','人体接触试电','短接电源'],0,'只模拟基本控制关系。'),M(2,'设计报告应有？',['设备需求表','连接图','负载核算','只一句“应该安全”'],[0,1,2],'结论需要条件和证据。'),M(2,'正确原则有？',['开关接火线','负载独立并联','保护器可任意调大解决过载','真实安装由专业人员核定'],[0,1,3],'保护需与导线等匹配。'),T(2,'220 V下总功率2200 W，总电流多少A？',['10'],'P/U=10。'),T(2,'题设回路最大16 A、220 V，最大功率模型值多少W？',['3520'],'220×16=3520。'),C(2,'月耗电相同的两个家庭，最大同时电流？',['必相同','可能不同','必零','由电价决定'],1,'时间安排不同。'),C(2,'低压模型能验证的主要是？',['控制连接关系','真实家庭绝缘全部合格','墙内导线实际温度','市电接地阻值'],0,'模型有适用边界。'),C(3,'16 A、220 V回路同时1800 W、1000 W，再加1200 W，总电流约？',['18.18 A且超限','12.73 A且不超','5.45 A','16 A自动固定'],0,'4000/220≈18.18。'),C(3,'某回路上限2200 W，设备1200、1000、800 W；最多可同时开哪组而不超限？',['1200与1000','三台全开','1200与1000再加小灯','总功率不限'],0,'1200+1000恰2200；加入任何正功率负载会超。'),C(3,'设备甲2000 W每天0.5 h，乙100 W每天10 h，比较正确？',['能耗相等，甲对瞬时负载影响更大','能耗甲20倍','最大电流相同','乙电流更大'],0,'都1度，但甲功率20倍。'),T(3,'220 V、10 A上限，已接880 W和660 W，按模型剩余功率多少W？',['660'],'2200−880−660=660。'),C(3,'测试只验证全部开关闭合灯都亮，是否足以证明独立控制？',['足够','不够，还需逐一断开及组合测试','灯数量足够就行','只看总电流'],1,'多种错误连接也可能全开时全部亮。'),K('纸面设计：回路220 V允许10 A，照明220 W、设备甲1100 W、设备乙880 W，三者可能同时使用。',[['三者总功率多少W？',['2200']],['三者同时电流多少A？',['10']],['若再加220 W设备，总电流多少A？',['11']]],'220+1100+880=2200 W，正好10 A；新增后2420/220=11 A，超题设上限。')],flowVisual('从需求走到可验证方案',['列需求与功率','画并联功能图','核对同时负载','低压测试改进'],'模型验证控制功能；真实施工需专业设计与安装'));
function magnetVisual(mode='field'){
 if(mode==='force'||mode==='induction')return V(mode==='force'?'通电导线在磁场中受力':'切割磁感线产生感应电流',rect(44,81,140,177,'#edc3aa')+text(93,176,'N',38)+rect(575,81,140,177,'#bdd8d9')+text(623,176,'S',38)+[116,165,216].map(y=>arrow(207,y,550,y,'#719c91')).join('')+`<circle cx="380" cy="165" r="24" fill="white" stroke="#364e48" stroke-width="3"/>`+(mode==='force'?`<circle cx="380" cy="165" r="7" fill="#364e48"/>`:line(369,154,391,176)+line(391,154,369,176))+line(380,130,380,51,'#cc8055')+`<path d="M373 63 L380 49 L387 63" fill="none" stroke="#cc8055" stroke-width="3"/>`+text(412,70,mode==='force'?'受力方向 F':'运动方向 v')+text(170,300,mode==='force'?'⊙ 表示电流垂直纸面向外；磁场由N指向S':'闭合回路中：⊗ 表示感应电流垂直纸面向里',18),mode==='force'?'示意给定电流和磁场方向下的受力。反转电流或磁场之一，力反向；同时反转两者，力方向不变。':'图示导线是闭合回路的一部分，向上运动切割水平磁感线。方向关系为帮助区分，不要求用高中公式计算。');
 if(mode==='coil')return V('通电螺线管与磁极',rect(130,140,490,43,'#d6e1d6')+Array.from({length:12},(_,i)=>`<ellipse cx="${164+i*36}" cy="161" rx="15" ry="63" fill="none" stroke="#bf835b" stroke-width="4"/>`).join('')+text(119,66,'S端（示例）')+text(545,66,'N端（示例）')+text(77,264,'右手握住螺线管：四指沿电流绕向，拇指所指为N极',20)+text(156,308,'换电流方向 → 两端磁极互换',18),'图示铁芯与线圈结构；示例磁极不替代电流方向证据，判断具体题需按题给电流绕向使用右手螺旋定则。');
 return V('条形磁体外部磁场方向',`<path d="M185 150 C185 27 575 27 575 150 M185 175 C185 300 575 300 575 175" fill="none" stroke="#7eab9b" stroke-width="3"/>`+arrow(350,58,420,58)+arrow(350,269,420,269)+rect(185,133,195,63,'#e6bea7')+rect(380,133,195,63,'#bdd9d6')+text(258,175,'N',29)+text(456,175,'S',29)+text(199,316,'磁体外部磁感线由N极指向S极',19),'磁感线是描述磁场的模型线，并非真实细线；磁场真实存在，磁体内部方向与外部相接形成闭合线。');
}
unit(20,'电与磁','依次研究磁场、电生磁、磁场对电流作用及磁生电，连接实际电机和控制装置。');
add('p20-1','磁现象 磁场','利用磁极规律和小磁针认识磁场，理解磁感线模型。',['磁体有N、S两极，同名磁极相互排斥，异名磁极相互吸引。','磁体周围存在磁场，磁场能对放入其中的磁体产生力的作用。','磁场某点方向规定为小磁针静止时N极所指方向。','磁感线为描述磁场的假想曲线，磁体外部从N极指向S极。','地球周围存在磁场，指南针定位需考虑磁场干扰，地理极与地磁极不完全重合。'],'把磁体截成两段通常得到两块各有南北极的磁体，而非孤立一个磁极。',[
'能够吸引铁、钴、镍等物质的性质叫磁性，具有磁性的物体称磁体。磁体上磁性较强的两个区域叫磁极，分别称北极N和南极S。同名磁极相斥，异名磁极相吸。判断是否为磁体可利用排斥证据，因为吸引铁块并不需要铁块原先就是磁体。',
'磁体彼此不接触也能相互作用，说明周围存在传递磁作用的磁场。磁场不是空气中的一阵风，也不依赖手碰才存在。把小磁针放到不同位置，其方向会不同；人们规定磁针静止时N极指向就是该处磁场方向。磁针S极指向相反，题目标极性时必须看清。',
'在磁体周围撒铁屑可显示大致分布，但铁屑只能帮助展示形状，方向仍需小磁针判断。用磁感线把分布和方向画成可读模型，线的切线方向表示当地磁场方向，疏密可定性反映强弱。磁感线本身是假想的，不能说铁屑排列证明空间里真的有细线。',
'条形磁体外部磁感线由N极走向S极。若在某位置磁针N极指右，那里磁场方向为右；若只知道磁针整体指向东西而未标N、S，无法定出具体方向。两块磁体靠近时，一端与已知N极相斥，说明该端也是N极；相吸则还需确认对方确实是磁体。',
'磁体断成两块通常每块仍各有N、S两极，中间切口处出现新的两极，不能靠剪切获得单独N极或S极。某些材料接近磁体后表现磁性称磁化，移走外磁场后保留程度取决于材料。软铁常用于容易磁化和退磁的场合，钢可用于永久磁体，但具体性能还与材料处理有关。',
'指南针受地磁场影响，磁针北端大致指向地理北方，地理极和地磁极并不完全重合。靠近钢铁物体、通电导线或磁铁时会受到干扰，因此导航不能无条件依靠室内一次读数。实验把相同小磁针放在不同位置，应等待稳定后记录箭头，避免把摆动途中的方向当作平衡方向。'
],[C(1,'同名磁极之间？',['相斥','相吸','无作用','融合消失'],0,'同名相斥。'),C(1,'磁场方向规定为小磁针哪个极静止时所指？',['N','S','任意','几何中心'],0,'N极方向。'),C(1,'磁体外部磁感线从？',['N到S','S到N','两端都向外','没有方向'],0,'外部N出S入。'),C(1,'磁感线是？',['真实细线','描述磁场的模型','空气流线','电流本身'],1,'磁场存在，线为表示工具。'),M(2,'正确的有？',['磁体周围有磁场','小磁针可探测方向','断磁体必得孤立磁极','磁感线疏密定性表示强弱'],[0,1,3],'每段通常仍有两极。'),M(2,'指南针使用应考虑？',['附近磁铁干扰','通电导线影响','等磁针稳定','只看一次高速摆动方向'],[0,1,2],'稳定后才适合读数。'),T(2,'某处小磁针N极指东，该处磁场向什么方向？',['东','向东'],'按N极指向定义。'),T(2,'未知磁体A端排斥已知N极，A端是什么极？',['N','N极','北极'],'排斥表同名。'),C(2,'普通铁块被磁铁吸引，能断定它原来是永久磁体吗？',['能','不能','只看重量就能','必带正电'],1,'磁化也可产生吸引。'),C(2,'条形磁铁从中间断开，通常？',['每块都有N、S极','一块仅N另一块仅S','都无磁性必然','产生电荷'],0,'不能切出单独磁极。'),C(3,'两磁体A端与已知N极相斥，B端与A相吸且B确为磁体，则B为？',['N','S','无法判断','无磁性'],1,'A为N，B异名为S。'),C(3,'磁针S极指向右，且静止无其他干扰，该处磁场？',['向左','向右','向上','无法定义'],0,'N极相反指左。'),C(3,'磁铁两侧铁屑排列对称，能据此确定左右哪端N吗？',['能，左必N','不能，需有方向的磁针证据','右必N','铁屑无任何用途'],1,'形状对称并不显示方向。'),T(3,'三块磁体：A左端为N；A右端与B左端相斥；B右端与C左端相吸，C左端为何极？',['S','S极','南极'],'A右S，B左S则B右N，C左与N相吸为S。'),C(3,'指南针靠近通电线后方向变，离开恢复，最合适解释？',['地理北极移动','附近电流磁场与地磁场共同作用','针失去质量','磁场线为实体绳'],1,'观察支持局部磁场叠加影响。'),K('条形磁体左端N、右端S。外部上方某点磁感线水平向右。',[['小磁针N极平衡时朝左还是右？',['右','向右']],['若磁体整体掉头，该对应对称位置磁场方向是否反转？填是或否。',['是']],['将原磁体分成两块，通常共得到几个磁极？',['4']]],'N极沿场向右；磁体对调两极场向反转；每段仍各两极，共4极。')],magnetVisual());
add('p20-2','电生磁','理解奥斯特实验、通电螺线管与右手螺旋定则。',['电流周围存在磁场，电流方向改变，磁场方向相应改变。','奥斯特实验用通电导线附近小磁针偏转显示电流磁效应。','通电螺线管外部磁场类似条形磁体。','右手握螺线管，四指沿电流绕向，拇指所指的一端为N极。','判电流方向应使用约定电流，不能误用金属电子移动方向。'],'螺线管端点极性由电流绕向决定，线圈画法不清时不能凭“左端一定N”猜。',[
'通电导线周围存在磁场，电流的磁效应把电现象与磁现象联系起来。奥斯特实验中，原先沿地磁场方向静止的小磁针，在附近导线通电后发生偏转；断电后可能恢复原方向；改变电流方向，偏转方向改变。这一组对照支持磁场与电流及其方向有关。',
'直导线周围的磁场分布与条形磁体不同，把导线绕成螺线管后，各匝磁场共同形成类似条形磁体的外部磁场。线圈看起来只是导线弯了很多圈，却使磁作用的方向和分布更集中，因此是电磁铁、电动机等装置的基础。螺线管有无磁性可以由通断电控制。',
'判断N极用右手螺旋定则：右手四指沿线圈中约定电流的环绕方向弯曲，伸直拇指所指端为N极。一定先沿电源正极到负极追踪电流，并看清线圈哪段在前、哪段在后。如果图没有交代绕线前后或电流方向，左右磁极可能无法唯一确定，不应仅凭绕圈图形猜测。',
'从螺线管某一端正面看，若约定电流呈逆时针环绕，该端为N极；若顺时针则为S极。这是右手规则的一种方便用法。假设左端看去逆时针，左端N、右端S；把电池两极反接而绕线不变，电流反向，两端磁极交换。',
'小磁针偏转大小也受导线距离、电流大小与原地磁场共同影响。要研究电流大小的作用，应保持线圈匝数、位置、铁芯和探测距离相同；要研究绕向，则保持其他条件一致并改变电流方向。不能把线圈移近磁针造成的更大偏转全部归因电流增大。',
'实验只使用合适的低压电路，通电导线仍有电阻，长时间大电流会发热，不能为了追求明显偏转直接短接电池。每次短时间观察后断电，记录电源极性、线圈绕向和磁针N极箭头。用图画清这些要素，才能让别人按同样接法复现结论，也为分析电磁铁极性建立可靠基础。'
],[C(1,'奥斯特实验说明？',['电流周围存在磁场','磁场必生静电','电流无作用','电压等于磁极'],0,'建立电与磁的联系。'),C(1,'通电螺线管外场类似？',['条形磁体','只有电场','无方向气流','光线'],0,'具有N、S两端特征。'),C(1,'右手四指顺电流，拇指指？',['N极','S极','电源负极必然','地理南方'],0,'螺旋定则。'),C(1,'仅反转螺线管电流，磁极？',['互换','不变','消失永不恢复','变为单极'],0,'磁场方向反向。'),M(2,'奥斯特实验可作的对照有？',['通电与断电','正向与反向电流','保持导线位置相同','同时任意改变所有因素'],[0,1,2],'对照需清楚变量。'),M(2,'判断螺线管磁极需注意？',['约定电流方向','绕线前后关系','用右手','把电子方向直接当电流'],[0,1,2],'金属电子运动与电流相反。'),T(2,'从某端看电流逆时针，该端是什么极？',['N','N极','北极'],'右手四指逆时针，拇指向观察者。'),T(2,'从某端看电流顺时针，该端是什么极？',['S','S极','南极'],'拇指背离观察者。'),C(2,'断开线圈电源后，空气芯线圈由电流产生的磁场？',['仍保持原强度','消失','增倍','变成永久磁体必然'],1,'电流磁场与电流存在相关。'),C(2,'研究电流大小影响，应保持？',['匝数与探测位置相同','每次换距离','每次换铁芯','只看导线颜色'],0,'固定其他因素。'),C(3,'左端看电流顺时针，旁边磁针位于左端外侧，其N极一般指向？',['螺线管左端','远离左端','竖直必然','无法受磁'],0,'左端S，外场朝S进入，所以N极朝向左端。'),C(3,'绕线方向反转同时电池两极反接，两端磁极相对原来？',['不变','互换','只有一个极','必无磁'],0,'绕向和电流两个反转相互抵消。'),C(3,'同电流线圈靠近磁针，偏转增大，能推出电流增加吗？',['能','不能，距离已改变','只要偏转即电流增加','磁针指针坏'],1,'距离是另一个变量。'),T(3,'已知线圈右端为N，反接电源后右端吸引小磁针哪一极？',['N','N极','北极'],'右端变S，吸引磁针N。'),C(3,'螺线管图只画平面椭圆且未标电流，能唯一判左端N吗？',['能','不能，信息不足','左端永远N','右端永远N'],1,'需要明确电流绕向。'),K('从线圈左端看，初始约定电流逆时针。随后仅反接电源，线圈位置不变。',[['初始左端为何极？',['N','N极']],['反接后右端为何极？',['N','N极']],['反接后左端会吸引小磁针N极还是S极？',['N','N极']]],'初始左N右S；反接后左S右N；左S吸引N。')],magnetVisual('coil'));
add('p20-3','电磁铁 电磁继电器','分析电磁铁强弱和继电器的控制回路、工作回路。',['带铁芯的通电螺线管常构成电磁铁，通断电可控制其磁性。','在其他条件相同时，电流较大、匝数较多、合适铁芯等可增强磁作用。','比较吸钉数量要保持铁钉、接触方式等相同，吸钉法是间接比较。','电磁继电器利用电磁铁吸引衔铁带动触点，实现一个电路控制另一个电路。','控制回路与工作回路要区分，触点承担的负载电流并不等于线圈电流。'],'更多匝数若同时使线圈电阻变大、电流变小，不能只看匝数就直接比较强弱。',[
'电磁铁通常由线圈和铁芯构成，线圈通电产生磁场，铁芯被磁化后使磁作用增强。选择容易磁化也容易退磁的铁芯，有利于断电后较快失去强磁性。与永久磁体相比，电磁铁可以通过电流控制有无磁性、强弱和磁极方向，因此广泛用于吸持、控制和机电装置。',
'探究强弱时可比较吸起相同铁钉的数量，但吸钉数量还受铁钉规格、接触位置、剩磁和排列影响。研究匝数需让两线圈电流相同，研究电流需保持匝数和铁芯相同。若直接用同一电源接不同长度导线绕成的线圈，电阻也变了，电流可能不同，结论就不能只归因匝数。',
'继电器有两套角色：控制回路中较小电流使电磁铁吸引衔铁，衔铁带动工作回路中的触点接通或断开负载。控制开关不直接承担全部负载电流，这使控制更灵活。常开触点在线圈未通电时断开，常闭触点则相反，必须按图例或题给状态判断，不能只背“通电就开灯”。',
'某继电器线圈12 V、电阻120 Ω，控制电流0.10 A，控制功率1.2 W。它的触点可控制24 V、2 A的低压电机，负载功率48 W。线圈和电机属于不同回路，不能把0.10 A与2 A相加当作同一干路电流，也不能说继电器创造了48 W能量。',
'温控或水位报警可让传感器改变控制电路电流，达到吸合条件后切换触点。分析时先看传感器阻值随物理量的关系，再判断线圈电流增减，再判断是否达到给定吸合阈值，最后追踪工作回路状态。实际装置存在吸合和释放不同阈值，题目未给时只按给定理想模型讨论。',
'设计低压模型时保持两个回路清楚分开，注明电源与触点额定值。电磁铁不应长期超过允许电流，线圈会发热；触点也不能无条件接任意大负载。报告要把“控制信号来自哪里”与“负载能量来自哪里”分开画出，避免把小电流控制大功率误解为以小能量凭空产生大能量。'
],[C(1,'电磁铁常由什么构成？',['通电线圈与铁芯','纸板与玻璃','只有塑料','不接电的灯'],0,'铁芯增强线圈磁作用。'),C(1,'通断电可主要控制电磁铁？',['有无磁性','质量是否守恒','电荷种类','重力方向'],0,'电流产生磁场。'),C(1,'继电器吸引衔铁的部件是？',['电磁铁','电阻丝必然','灯罩','温度计'],0,'磁力驱动触点。'),C(1,'常开触点在线圈未通电时通常？',['断开','闭合','短接所有回路','无定义'],0,'按“常态”命名。'),M(2,'比较电磁铁强弱需注意？',['保持铁钉规格相同','研究匝数时固定电流','记录间接指标','一次同时改全部因素'],[0,1,2],'需控制变量。'),M(2,'继电器正确理解有？',['控制与工作回路可分开','负载能量来自工作电源','线圈电流必等于负载电流','触点也有额定限值'],[0,1,3],'两回路电流不同。'),T(2,'12 V加在120 Ω线圈两端，电流多少A？',['0.1'],'12/120=0.1。'),T(2,'6 V、0.2 A线圈功率多少W？',['1.2'],'UI=1.2。'),C(2,'同电流同铁芯下匝数增加，磁作用通常？',['增强','减弱','无关必然','变成电压'],0,'控制其他条件后比较。'),C(2,'线圈通电吸合使常闭触点断开，负载？',['可能停止','必启动','一定短路','必增大电流'],0,'需按触点位置判断。'),C(3,'线圈6 V电源串传感器，线圈20 Ω，吸合需≥0.1 A，传感器最大允许多少Ω仍能吸合？',['40 Ω','60 Ω','20 Ω','100 Ω'],0,'总阻≤6/0.1=60，传感器≤40。'),C(3,'两线圈匝数100与200，接同电源后电流0.4与0.1 A，能仅凭匝数断定后者强吗？',['能','不能，电流也改变','后者必强2倍','都无磁'],1,'控制变量未满足。'),C(3,'12 V 0.1 A控制线圈控制24 V 2 A负载，控制功率占负载功率？',['2.5%','5%','20%','40%'],0,'1.2/48=2.5%。'),T(3,'12 V电源，线圈100 Ω、传感器200 Ω串联，电流多少A？',['0.04'],'12/300=0.04。'),C(3,'温度升高热敏电阻减小，线圈与其串联、供电稳定，常开触点控制风扇，达到吸合阈值时？',['风扇启动','风扇必关','线圈电流减小','无变化必然'],0,'总阻减小、I增大、吸合常开闭合。'),K('控制回路6 V，线圈20 Ω，传感器串联，吸合电流至少0.10 A。工作回路独立12 V、1 A，常开触点控制。',[['传感器10 Ω时线圈电流多少A？',['0.2']],['传感器50 Ω时能否吸合？填能或不能。',['不能']],['负载运行功率多少W？',['12']]],'6/30=0.2 A满足；6/70≈0.086 A不足；负载功率12×1=12 W。')],flowVisual('继电器：控制与供能分开',['控制电源供线圈','磁力带动衔铁','触点切换负载','工作电源供负载'],'线圈电流与负载电流属于不同回路，不可混用'));
add('p20-4','电动机','解释通电导线受力与直流电动机持续转动，区分电动机和发电机。',['通电导线在磁场中可受到力，力的方向与电流方向和磁场方向有关。','只改变电流或磁场方向之一，受力方向反转；两者同时反转可保持不变。','通电线圈在磁场中可发生转动，电动机把电能转化为机械能。','直流电动机换向器使线圈转过平衡位置后电流适时反向，维持同方向转动。','实际电动机还发热，输入电功率不全部变成机械功率。'],'给线圈通电看它受力是电动机原理；机械运动产生电流是发电机原理，方向不可颠倒。',[
'磁场能对其中的通电导线产生力的作用，这就是电动机的基本依据。受力方向与电流方向、磁场方向及导线位置有关。在给定互相垂直的条件下，仅反转电流或磁场之一，力会反向；如果两者同时反转，力的方向可保持不变。初中重点是实验对比和方向变化规律。',
'一段导线受力可移动，线圈两边受力形成使线圈转动的效果，于是电能转为机械能。电动机需要电源输入，不能因为转子开始旋转就说在发电。实际电机内线圈、磁体、转轴、轴承和换向结构配合工作，部分输入电能也变成内能，因此会发热。',
'简单直流电动机线圈转到某位置时，转动力矩会减小甚至暂时为零，靠惯性越过。若电流方向一直不变，越过后受力可能使其回摆。换向器在适当位置改变线圈中电流方向，让两侧受力方向随之改变，从而持续保持原转向；电源外部供电方向并未因此反复改变。',
'某电机输入电压12 V、电流1 A，输入功率12 W。若线圈电阻2 Ω，则线圈发热功率2 W，忽略其他损耗，机械输出10 W，效率约83.3%。电机运转时不能直接用12²/2=72 W当作输入功率，因为电机不等效为仅有2 Ω的纯电阻。',
'转向控制要说明具体改变。如果电磁铁提供磁场，而整个电源反接同时使电枢电流和励磁电流都反向，磁场与导线电流可能同时反转，转向不一定改变；若只反接转子线圈而磁场不变，转向才反转。题目应明确两者是否同时受同一操作影响。',
'实验用低压小电机或通电导线装置，记录电源极性、磁极位置与运动方向。改变方向前先断电，避免短路和长时间堵转。堵转时机械输出为零，很多输入能量会变热，并且电流可能明显改变，不能把正常运转电流直接用于堵转状态。设备额定值和实际运行状态要分别核对。'
],[C(1,'电动机主要转化为？',['电能→机械能','机械能→电能','内能→核能','光能→化学能'],0,'电源使线圈受力转动。'),C(1,'电动机基本原理是？',['通电导线在磁场中受力','磁生电','摩擦起电','电阻热胀'],0,'与发电机区分。'),C(1,'仅反转电流，磁场不变，受力方向？',['反转','不变','一定为零','随机'],0,'方向因素之一反转。'),C(1,'简单直流机换向器作用是？',['适时改变线圈电流方向','创造电能','消除所有摩擦','改变地磁场'],0,'使线圈持续同向转动。'),M(2,'正确的有？',['电机需要输入能量','实际电机可能发热','两方向同时反转力可不变','输入电能全为机械能必然'],[0,1,2],'有损耗。'),M(2,'实验比较受力方向应？',['单独改变电流','单独改变磁场','记录导线位置','每次所有条件乱变'],[0,1,2],'一次改变一个方向因素。'),T(2,'12 V、0.5 A电机输入功率多少W？',['6'],'UI=6。'),T(2,'电机输入100 J，机械输出80 J，效率多少？',['80%'],'80/100。'),C(2,'线圈越过平衡位置可依靠？',['惯性','永动能源','只有重力','空气电荷'],0,'换向与惯性配合。'),C(2,'把永磁体两极交换但电流不变，转向一般？',['反转','不变','必失去电阻','电流自动归零'],0,'磁场反向使力反向。'),C(3,'12 V、1 A电机线圈2 Ω，忽略其他损耗，机械功率为？',['10 W','12 W','2 W','72 W'],0,'UI−I²R=12−2=10。'),C(3,'同一电源反接同时使励磁磁场与转子电流反向，则力方向？',['可能保持不变','必反向','必为零','与两者无关'],0,'两个反转抵消。'),C(3,'电机输出8 W提升重2 N的物体匀速上升，速度为？',['4 m/s','0.25 m/s','16 m/s','2 m/s'],0,'P=Fv，v=8/2=4。'),T(3,'电机输入20 W，线圈热损4 W，其他损耗1 W，机械效率多少？',['75%'],'有用15 W，15/20=75%。'),{...C(3,'读图：磁场由N指向S，导线电流垂直纸面向外时受力向上。若将电流改为向里，同时交换N、S，受力方向变为？',['仍向上','向下','向左','必为零'],0,'电流和磁场各反转一次，受力方向保持。'),diagram:magnetVisual('force').svg},K('电机6 V、2 A，线圈0.5 Ω，工作10 s，只有线圈发热这一项损耗。',[['输入电能多少J？',['120']],['产生焦耳热多少J？',['20']],['输出机械功多少J？',['100']]],'W=6×2×10=120；Q=2²×0.5×10=20；机械功100 J。')],magnetVisual('force'));
add('p20-5','跨学科实践：制作简易直流电动机','组装低压线圈电机，验证供电、磁场、换向和机械结构的作用。',['模型至少包含低压电源、线圈、磁体、支架与合适的换向或间歇供电结构。','线圈在磁场中受力，合适换向使转动持续，电能转为机械能。','半刮漆线轴属于简化间歇供电方案，其工作原理与完整换向器需区分。','调试关注接触、摩擦、重心、线圈位置与磁场方向，每次改变一个因素。','记录启动、转速、带载与温升，空转快不等于效率最高。'],'不以大电流或长时间堵转解决结构问题；断电后再调整线圈和触点。',[
'制作直流电动机模型要同时解决电与机械两个问题：线圈必须有合适电流并处在磁场中，转轴又要能灵活转动。先画能量与结构图，标明低压电源、线圈两端、支撑触点、磁体和转动轴。可选成熟的低压教学套件，明确每个零件的作用后再做结构改进。',
'当线圈边中的电流经过磁场，受到方向相反的力，可形成转动效果。线圈不是任何角度都同样容易启动，某些位置转动力矩很小。真正带换向器的直流机在合适时机反转线圈电流；简易半刮漆轴模型常在部分转角断电，靠惯性通过另一段角度，两者都可持续转动，但不能把间歇通电说成完全相同的换向方式。',
'绕制线圈应尽量对称并使重心接近轴，支架保持稳定，接触点既要导电又不能夹得过紧。检查是否有绝缘漆未去除、接线松动或线圈碰到磁体。调试时先用手轻转检查机械阻力，再短时通电，断电后才调整。若电源或导线明显发热，停止检查，不靠继续加大电流来掩盖卡滞。',
'模型30 s转150周，平均转速5周/s，即300 r/min。另一次轻载提升0.020 kg物体0.30 m，用时3 s，取g=10 N/kg，输出功0.060 J，功率0.020 W。若输入功率0.40 W，机械能利用率约5%。空转数据与带载数据不同，不能拿空转速度和带载功直接混算。',
'比较磁体位置对性能影响，要保持电源状态、线圈匝数、接触压力和负载相同；比较绕线方案，则需要关注电阻变化带来的电流变化。如果匝数变多同时线圈更重、阻值变大，转速变化就可能受多因素共同影响。研究报告应明确是单因素探究还是整机优化，后者可接受多项改进但不能作单一因果结论。',
'展示时提供接线图、结构照片、三次测试记录、能量解释及失败排查。可以说明为什么增加支架稳定性比继续提高电压更有效，为什么反接电源可能改变转向。模型只在合适低压下运行，不把裸露线圈接入家庭插座；最终评价既看可运行，也看可重复、耗电、带载能力与结构可靠性。'
],[C(1,'简易电机能量来源为？',['电源','磁体无限供能','支架','惯性凭空产生'],0,'磁场作用不意味着无限能源。'),C(1,'模型能转动的主要物理作用？',['通电线圈在磁场中受力','重力消失','空气导电必然','核能释放'],0,'电动机原理。'),C(1,'调整线圈触点前应？',['断电','提高电压','短接电池','用湿手操作'],0,'先断电再调整。'),C(1,'线圈轴夹得太紧，可能？',['摩擦阻碍转动','自动提高效率','产生无限功率','改变电荷种类'],0,'机械阻力也是关键因素。'),M(2,'合理调试项目有？',['触点导电情况','轴的摩擦','线圈是否碰磁体','直接无限加压'],[0,1,2],'先排查结构与接触。'),M(2,'测量比较应注意？',['相同负载','电源状态','重复记录','只选最快一次'],[0,1,2],'重复数据帮助评价稳定性。'),T(2,'20 s转80周，平均转速多少周/s？',['4'],'80/20=4。'),T(2,'转速5周/s等于多少r/min？',['300'],'5×60=300。'),C(2,'半刮漆简易线圈模型通常主要通过？',['部分角度断电并靠惯性转过','任何角度电流必自动反向','磁体永不耗电产生功','删除电源'],0,'需区分间歇供电与完整换向器。'),C(2,'线圈不转但电池发热，最合理处理？',['立刻断电检查卡滞或短接','继续通电等转','再加电池','用手捏裸线判断'],0,'避免过热。'),C(3,'模型提升0.05 kg物体0.4 m用4 s，g=10，输入0.5 W，机械效率？',['10%','20%','40%','5%'],0,'W=0.2 J，P=0.05 W，η=10%。'),C(3,'甲空转600 r/min、带载功率0.02 W；乙空转400 r/min、带载功率0.03 W，哪项可判断？',['乙在给定带载条件输出功率更大','甲效率必高','甲任何负载都更好','两者输入必相同'],0,'空转速度不能代替带载功率和效率。'),C(3,'增加匝数后转速下降，线圈同时更重且电流下降，结论应？',['匝数增加必使磁场弱','多个因素同时变化，需分开研究','电动机原理错误','电源无需测量'],1,'质量、电流与匝数均有影响。'),T(3,'输入3 V、0.2 A，机械输出0.12 W，效率多少？',['20%'],'输入0.6 W，0.12/0.6=20%。'),C(3,'两方案输出相同机械功0.6 J，甲用时3 s耗电3 J，乙用时2 s耗电4 J，正确的是？',['乙功率更大但效率更低','乙功率效率均高','甲功率更大','两者效率相同'],0,'甲0.2 W、20%；乙0.3 W、15%。'),K('模型低压电源3 V、电流0.20 A，运行5 s，提升0.10 kg物体0.30 m，g=10 N/kg。',[['输入电能多少J？',['3']],['有用机械功多少J？',['0.3']],['机械效率多少？',['10%']]],'输入3×0.2×5=3 J；mgh=0.1×10×0.3=0.3 J；效率10%。')],magnetVisual('force'));
add('p20-6','磁生电','判断电磁感应条件和方向变化，理解发电机的能量来源。',['闭合电路的一部分导体在磁场中做切割磁感线运动，可产生感应电流。','感应电流方向与导体运动方向、磁场方向有关。','只反转运动或磁场之一，感应电流反向；两者同时反转可保持方向。','发电机依据电磁感应，将机械能转为电能。','运动需要外界做功，不能从磁体中无止境取电；实际发电有损耗。'],'导体沿磁感线运动通常不满足该简单切割条件；断开的电路可能有感应电压但无持续感应电流。',[
'电磁感应说明磁可以产生电。在初中常用实验中，闭合电路的一部分导体处于磁场，导体运动切割磁感线时，灵敏电流计可显示感应电流。必须同时关注电路闭合、磁场以及合适的相对运动，不能把任何导线在任何方向的运动都叫发电。',
'所谓切割磁感线是一种模型描述，用来判断导体运动是否穿过磁场方向所代表的线。若导体在均匀磁场中恰沿磁感线运动，通常不发生这个简单实验中的切割效果；若导体与磁体相对静止，也不能靠静止磁场让这根导线持续发电。电路断开时可存在感应电压，但没有完整通路就没有持续电流。',
'探究实验把导线接入闭合的电流计回路，先静止观察，再左右运动比较，改变磁极方向再重复。记录每次运动方向、磁场方向和指针偏向，不能只写“指针动了”。保持其他条件相同，运动较快或磁场较强时感应效果常更明显，但精确大小还与导线长度、回路电阻等因素有关。',
'给定一次实验导线向右运动时电流计向左偏，保持磁场不变改向左运动，则指针向右偏。若同时把磁体N、S互换并把运动方向反转，两次反转作用可相互抵消，指针可保持原偏向。这类题只需相对初始情况判断，不必强行猜未给出的绝对方向。',
'发电机中转动的线圈或转动磁场使电磁感应持续发生，把外界机械功转换为电能。手摇发电机接上更重电负载时往往更难摇动，说明电能输出需要机械输入。风力、水力、热力机组等只是提供机械运动的来源不同；发电机并没有创造能量，也不是不断消耗磁极本身作为燃料。',
'电动机与发电机的结构可能相似，但实验线索不同：给线圈通电看它受力转动，是电动机效应；让导体运动并测到电流，是电磁感应。某些机器能在不同工况下互换角色，例如回收运动能量时可以发电，但必须说明能量流向。交流发电机线圈连续转动时电流方向可周期改变，家庭供电频率与机组设计有关。'
],[C(1,'发电机的主要能量转化？',['机械能→电能','电能→机械能','磁能无限创造','热量→质量'],0,'外界机械输入转为电输出。'),C(1,'发电机依据？',['电磁感应','静电吸引','光的折射','只有电阻发热'],0,'运动切割磁感线产生感应。'),C(1,'简单感应电流实验还需？',['闭合回路','只要有磁铁','电路永远断开','没有导体'],0,'电流需要完整回路。'),C(1,'导体静止在不变磁场中，该简单实验持续感应电流？',['一般没有','必很大','与重力相同','永久存在'],0,'缺少磁通变化或切割条件。'),M(2,'能影响感应电流方向的有？',['运动方向','磁场方向','两者同时考虑','导线绝缘皮颜色'],[0,1,2],'方向由运动与场共同决定。'),M(2,'正确说法有？',['发电需要能量输入','导体沿磁感线运动不一定有感应电流','断路也必有持续电流','电机与发电机能量方向不同'],[0,1,3],'断路无持续电流。'),T(2,'保持磁场，仅把运动方向反转，感应电流方向变不变？填反转或不变。',['反转'],'单个方向因素反转。'),T(2,'发电机机械输入100 J，电输出80 J，效率多少？',['80%'],'80/100。'),C(2,'手摇发电机接负载后更费力，说明？',['电输出需机械功','磁铁制造能量','能量不守恒','负载没有影响'],0,'输出电能来自输入机械能。'),C(2,'运动和磁场方向同时反转，感应电流方向通常？',['不变','反转','必为零','随机'],0,'两个方向变化相互抵消。'),C(3,'机械输入20 W，发电效率75%，给5 Ω电阻供电，电流为？',['√3 A','3 A','0.75 A','4 A'],0,'电功率15 W，I²R=15，I=√3 A。'),C(3,'发电机输出6 V、0.5 A，效率60%，机械输入功率？',['5 W','3 W','1.8 W','10 W'],0,'输出3 W，输入3/0.6=5 W。'),C(3,'原导线向上切割磁场，电流向里；改为向下并交换磁极，电流？',['仍向里','变向外','必零','不能再闭合'],0,'双反转保持方向。'),T(3,'手摇发电机输入机械功120 J，电能90 J，电能中60 J最终为光源有用输出，整个链效率多少？',['50%'],'最终有用60/输入120=50%。'),{...C(3,'读图：导线作为闭合回路一部分向上运动、电流向里。若只反向移动而回路不变，电流及能量来源判断是？',['电流向外，能量来自外界机械功','电流不变，来自磁体无限能量','电流向外，无需做功','电流消失必然'],0,'运动反向使电流反向，能量仍由机械输入。'),diagram:magnetVisual('induction').svg},K('发电机每秒接受机械能40 J，电输出12 V、2 A，稳定工作30 s。',[['电输出功率多少W？',['24']],['发电效率多少？',['60%']],['30 s损耗能量多少J？',['480']]],'输出24 W，效率24/40=60%；损耗16 W×30 s=480 J。')],magnetVisual('induction'));
function waveVisual(kind='wave'){
 if(kind==='fiber')return V('光纤用反射引导光信号',rect(65,101,630,113,'#d6ece6')+`<polyline points="65,158 145,107 305,207 465,107 625,207 695,162" fill="none" stroke="#d2834e" stroke-width="4"/>`+text(95,72,'合适入射条件下，光在纤芯边界连续全反射',20)+text(219,269,'玻璃纤芯 → 承载光脉冲信息',22),'光纤中的光速小于真空光速；图为路径原理示意，实际光纤还包含包层及保护结构。');
 let pts=Array.from({length:151},(_,i)=>`${65+i*4.2},${157-54*Math.sin(i*Math.PI*6/150)}`).join(' ');
 return V('波长、频率与传播速度',line(48,157,710,157,'#b7c6bc',1)+`<polyline points="${pts}" fill="none" stroke="#3b8a7d" stroke-width="4"/>`+line(117.5,72,327.5,72,'#c78650',3)+line(117.5,63,117.5,81)+line(327.5,63,327.5,81)+text(188,58,'一个波长 λ')+text(150,261,'同一介质中：v = λf；真空中 c ≈ 3×10⁸ m/s',21)+text(174,302,'波形是模型图，横轴表示空间位置',17),'波长是相邻同相位点之间的距离；频率是每秒振动次数。空间波形图与某点随时间变化图不要混淆。');
}
unit(21,'电磁波及其应用','用波速、频率和波长理解信息传输，认识移动、卫星与光纤通信。');
add('p21-1','电磁波的海洋','理解电磁波传播特性，计算波长频率与传播时延。',['变化的电流等可产生电磁波，电磁波能传递能量和信息。','电磁波可在真空传播，真空中速度约3×10⁸ m/s。','波速、波长与频率满足v=λf，Hz表示每秒振动次数。','同一传播速度下，频率越高波长越短。','无线电波、红外线、可见光、紫外线等都属于电磁波，声音是另一类机械波。'],'声音不能在真空传播，但电磁波可以；高频不代表在真空中传播得更快。',[
'电磁波是可以传播能量和信息的一种波，变化的电流等能产生电磁波。无线电波、红外线、可见光和紫外线都属于电磁波，区别主要在频率和波长范围。肉眼只能看到其中很小一段，并不能因为看不见无线电波就说它不存在。',
'声音需要空气、水或固体等介质来传播，电磁波则能够穿过真空。从太阳传来的光跨过大量近似真空空间仍能到达地球，就是熟悉例子。电磁波在真空中的速度约为3×10⁸ m/s，常用字母c表示。不同频率的电磁波在真空中的传播速度相同，不能把频率高误解为跑得快。',
'频率f表示每秒周期数，单位Hz；波长λ是空间中相邻同相位点的距离；波速满足v=λf。代数前统一频率单位，1 MHz=10⁶ Hz，1 GHz=10⁹ Hz，波长用m。已知两者求第三个时，要确定题目是在真空还是其他介质，光纤等介质中传播速度可能较低。',
'频率100 MHz的电磁波在真空中的波长为3×10⁸/(100×10⁶)=3 m。若频率改为150 MHz，波长为2 m，速度仍相同。信号从距离300 km处传播到接收器，理想单程时间为300000/(3×10⁸)=0.001 s，即1 ms；往返信号时间需再乘2。',
'读波形图先看横轴：若横轴是位置，两个相邻波峰距离给波长；若横轴是时间，相邻波峰间隔给周期。把波峰数与完整周期数区别开，三个连续波峰之间只有两个完整波长。频率与周期关系f=1/T，可由此把时间图和空间图联系起来，但不能把距离直接当成时间。',
'电磁波在环境中会遇到反射、吸收、遮挡和信号干扰。接收信号强弱不仅由频率决定，也取决于发射功率、传播距离、天线与环境。实验可观察收音机受金属屏蔽或电火花干扰的现象，但要控制位置和频道，并使用已有低压教学器材，不靠拆改无线设备或产生高压火花来验证。'
],[C(1,'可在真空传播的是？',['电磁波','空气中的声波','水波','绳波'],0,'电磁波无需物质介质。'),C(1,'真空中电磁波速度约？',['3×10⁸ m/s','340 m/s','3×10³ m/s','30 m/s'],0,'常量c近似值。'),C(1,'频率单位Hz表示？',['每秒周期数','每秒米数','能量','电压'],0,'频率是周期变化快慢。'),C(1,'波速关系是？',['v=λf','v=λ/f','v=f/λ','v=λ+f'],0,'单位m×1/s=m/s。'),M(2,'属于电磁波的有？',['红外线','可见光','无线电波','空气声波'],[0,1,2],'声是机械波。'),M(2,'真空中正确的有？',['不同频率电磁波速度相同','频率高波长短','频率高速度必大','可传递能量'],[0,1,3],'速度不是随频率任意增加。'),T(2,'100 MHz电磁波真空波长多少m？',['3'],'3×10⁸/10⁸=3。'),T(2,'波长0.5 m，真空频率多少MHz？',['600'],'3×10⁸/0.5=6×10⁸ Hz。'),C(2,'空间图相邻波峰距离表示？',['波长','周期','电流','速度本身'],0,'位置差是长度。'),C(2,'频率增加到2倍且波速不变，波长？',['2倍','1/2','不变','4倍'],1,'λ=v/f。'),C(3,'雷达发出电磁波后2 ms收到回波，c=3×10⁸，目标距离？',['300 km','600 km','150 km','3 km'],0,'往返距离ct，单程ct/2=300000 m。'),C(3,'空间波图相邻第1与第4波峰相距6 m，真空频率？',['150 MHz','50 MHz','600 MHz','300 MHz'],0,'三波长6 m，λ=2 m，f=150 MHz。'),C(3,'某点每2 ns完成1周期，真空波长？',['0.6 m','6 m','0.06 m','1.5 m'],0,'f=5×10⁸ Hz，λ=0.6 m。'),T(3,'电磁波单程传播900 km，真空传播时间多少ms？',['3'],'900000/3e8=0.003 s=3 ms。'),C(3,'两波真空频率比2:5，波长比和速度比分别？',['5:2、1:1','2:5、2:5','5:2、5:2','1:1、1:1'],0,'λ反比f，真空速度同值。'),K('无线信号频率150 MHz，在真空传播；雷达往返用时0.004 s。',[['波长多少m？',['2']],['雷达信号往返总路程多少km？',['1200']],['目标距雷达多少km？',['600']]],'λ=3e8/150e6=2 m；ct=1.2e6 m=1200 km；单程600 km。')],waveVisual());
add('p21-2','广播、电视和移动通信','理解信息编码、调制、传输、接收的过程，并计算通信数据量。',['话筒将声音信号转换为电信号，摄像器件将图像信息转换为电信号。','调制把信息加载到载波上，接收端选择信号并解调还原信息。','广播通常一个发射端面向多个接收者，移动通信可进行双向信息交换。','移动终端与基站等设备经电磁波通信，网络还连接有线和光纤部分。','信息内容、载波频率、传输速率、传播速度是不同概念，不能混淆。'],'载波频率高不等于声音音调高；设备标注的速率不是电磁波传播速度。',[
'广播和通信要把声音、图像或数据转换成可以传输的信号。话筒将声音变化转换为电信号，摄像器件记录图像形成电信号，数字系统可进一步编码为数字信息。发射装置把信息加载到适当载波，通过天线发射电磁波；接收装置选择目标信号、解调并还原成声音、图像或数据。',
'载波像运输信息的车辆，信息像车上装载的货物。广播频率不是节目里某个音符的频率；换频道改变所选择的载波，扬声器仍可播放同样高低的声音。这里的类比帮助分开“传什么”与“用什么信号传”，不能把数字信息直接看成一串真实小球沿天线飞出。',
'广播系统常由一个发射台向许多接收机发送内容，接收机选择不同载波来收听频道。移动通信终端则既能发送也能接收，与基站及核心网络等协同实现双向通信。通话的一端到另一端不一定全程无线，中间可能经过光纤或其他有线网络，不能把手机之间通信画成永远直接互传。',
'假设音频每秒采样8000次，每次用8 bit编码，单声道原始数据率为64000 bit/s。发送10 s音频的原始数据为640000 bit，即80000 byte，忽略压缩和协议开销。数据率与信号传播速度是不同量：前者表示每秒可传多少信息位，后者表示信号前沿经过空间的快慢。',
'通信延迟可能包括信号传播、设备处理、排队等待与数据发送时间。即使电磁波传播很快，一个很大的文件仍需要有限时间送完，因为通道每秒传输数据量有限。实际下载还受服务器、拥塞和编码等条件影响，题目给定理想传输速率时可按总数据量除以速率计算，并注明单位换算。',
'分析通信故障先区分信号问题与内容处理问题。遮挡、距离或干扰可能影响无线接收，网络负载会影响吞吐与延迟；音量变小不等于载波频率下降，画面卡顿也不等于光速变慢。学习时用完整链条解释现象，把发射、传播、接收和还原各环节的职责分开，就能避免用一个“信号不好”替代全部原因。'
],[C(1,'话筒主要把什么转换为电信号？',['声音信息','质量','磁极数','温度单位'],0,'声音引起的变化被转成电信号。'),C(1,'把信息加载到载波上的过程称？',['调制','汽化','称量','短路'],0,'传输前加载信息。'),C(1,'收音机调频道主要在选择？',['不同载波信号','不同光速','不同声音质量单位','不同重力'],0,'选择载波频率对应频道。'),C(1,'移动电话通常能够？',['双向通信','只接收不能发送','不用电磁波','永不需网络'],0,'终端可发可收。'),M(2,'通信链条可能包括？',['信息编码','电磁波传输','接收解调','能量凭空产生'],[0,1,2],'传输需要设备与供能。'),M(2,'应区分的概念有？',['载波频率与音调','数据率与传播速度','传播时延与总时延','把MHz当作m/s'],[0,1,2],'MHz是频率单位。'),T(2,'每秒传8000 bit，2 s共多少bit？',['16000'],'数据量=速率×时间。'),T(2,'8000 bit等于多少byte？1 byte=8 bit。',['1000'],'除以8。'),C(2,'手机通话全程一定直接无线传到另一手机吗？',['一定','不一定，中间可经基站与光纤网络','只靠声波','完全不需信号'],1,'通信链可混合不同媒介。'),C(2,'把广播载波频率变高，是否必使节目音调变高？',['是','否，载波与音频信息不同','节目无法恢复','音速一定改变'],1,'信息与载波区分。'),C(3,'8000次/s采样、每次8 bit、双声道，10 s未压缩数据量？',['160000 byte','80000 byte','16000 byte','1280000 byte'],0,'8000×8×2×10/8=160000 byte。'),C(3,'文件8 MB，1 MB=10⁶ byte，理想速率4 Mbit/s，发送时间？',['16 s','2 s','8 s','32 s'],0,'8×8=64 Mbit，64/4=16 s。'),C(3,'信号传播2 ms、设备处理3 ms、排队5 ms、数据发送10 ms，总延迟？',['20 ms','2 ms','10 ms','8 ms'],0,'四段相加20 ms。'),T(3,'64 kbit/s原音频压缩到原数据的1/4，持续60 s，压缩后多少kbit？',['960'],'64×60/4=960。'),C(3,'两个网络信号传播速度相同，甲下载比乙慢，可由什么解释？',['甲可用数据率更低或排队更久','甲电磁波必慢一半','甲无线电频率等于音调','乙违背守恒'],0,'吞吐和时延不只由传播速度决定。'),K('数字音频单声道，采样10000次/s，每次8 bit；发送时压缩为原始数据的一半，网络有效速率40 kbit/s。k=1000。',[['原始数据率多少kbit/s？',['80']],['10 s音频压缩后多少kbit？',['400']],['理想发送这些压缩数据需多少s？',['10']]],'10000×8=80 kbit/s；10 s原800，压缩400；400/40=10 s。')],flowVisual('声音信息的传输链',['话筒转换编码','调制并发射','传播与接收','解调还原声音'],'载波负责传送，节目内容与载波频率是不同层次'));
add('p21-3','卫星通信和光纤通信','比较两类通信路径，估算距离、时延与传输效率。',['通信卫星可作空间中继，接收、处理并转发地面信号。','卫星通信使用电磁波，路径长会造成可计算的传播时延。','光纤以光信号传输信息，合适条件下利用全反射将光限制在纤芯中。','光纤中信号速度小于真空光速，实际时延还含处理与排队。','比较通信方案要综合覆盖、容量、时延、建设与维护条件。'],'卫星不是把声音直接传过真空；光纤也不意味着信号瞬间到达。',[
'卫星通信把卫星作为空间中继站：地面站把信息调制为电磁信号发向卫星，卫星接收并转发到另一处地面站。它能覆盖较广地区，特别适合某些地面网络不易建设的环境，但信号必须走实际空间路径，距离会带来传播时间，不能认为从太空中转就没有延迟。',
'光纤通信先把信息变成光脉冲，再让光沿细长的纤维传播。光纤通常由纤芯和包层等组成，合适的入射条件下，光在边界发生全反射，能够被限制在纤芯中向前传送。图中曲折的光路只是原理示意，真实传播方式更复杂；学习重点是光信号和引导传播，不是把光纤当作空心水管。',
'计算传播时延用t=s/v，先明确是单程、往返还是经中继的多段路径。真空电磁波速度近似3×10⁸ m/s，光纤中可按题给数值如2×10⁸ m/s计算。不同系统的真实速度和路由需以具体数据为准，不能仅用地图直线距离就精确代表光缆长度或卫星链路距离。',
'假设地面A经卫星到地面B共行进72000 km，近似以真空光速传播，单程时延0.24 s；若还要返回确认且路径相同，传播部分合计0.48 s。另一条光纤实际长度3000 km、速度2×10⁸ m/s，单程时延0.015 s。比较结果只对应给定路径，不代表所有卫星都一样高或一样慢。',
'方案比较不能只盯一个数字。海底光缆适合大容量连接，但铺设维护条件不同；卫星可迅速覆盖偏远或移动场景，但要考虑轨道、信号可视条件、系统容量和终端能耗。现代网络常组合多种媒介，某条业务既经过无线接入又经过光纤骨干，再接入卫星链路也是可能的。',
'“带宽大”在通俗说明中常表示可传较多数据，不等同于传播速度无限快。发送一个大文件的总时间可能主要受数据率限制，实时对话则更敏感于时延。题目若给容量与时延，应分别计算发送时间和传播时间，再按发送完成后到达等具体定义组合，避免把两个不同过程混为一谈。'
],[C(1,'卫星通信中的卫星主要可充当？',['中继站','声波空气桥','无限能源','机械传送带'],0,'接收和转发信号。'),C(1,'光纤承载的主要信号是？',['光信号','空气声波','水流','铁屑'],0,'光脉冲载信息。'),C(1,'光在光纤内受引导传播与什么有关？',['全反射','汽化','电流热效应唯一','重力反弹'],0,'合适条件下边界全反射。'),C(1,'传播时间公式？',['t=s/v','t=sv','t=v/s','t=s+v'],0,'路程除以速度。'),M(2,'通信方案比较可考虑？',['覆盖','时延','建设维护条件','只看某一个最高数字'],[0,1,2],'多指标判断。'),M(2,'正确的有？',['卫星用电磁波通信','光纤传播也需时间','所有卫星高度都相同','实际路径可能长于直线距离'],[0,1,3],'轨道和路由可不同。'),T(2,'光纤长200 km，信号速度2×10⁸ m/s，单程多少ms？',['1'],'200000/2e8=0.001 s。'),T(2,'信号路径60000 km、速度3×10⁸ m/s，单程多少s？',['0.2'],'6e7/3e8=0.2。'),C(2,'声音经卫星通信可穿真空，是因为？',['声音直接穿真空','先转成电磁信号再还原','卫星制造空气','真空有声速'],1,'媒介变为电磁波。'),C(2,'光纤中速度与真空光速相比通常？',['更小','无限大','必相同','为零'],0,'介质中光速低于c。'),C(3,'地面—卫星—地面路径72000 km，返回确认同路，纯传播往返时间？',['0.48 s','0.24 s','0.12 s','4.8 s'],0,'总144000 km除以300000 km/s。'),C(3,'光纤3000 km、速度2×10⁸ m/s；8 Mbit文件以4 Mbit/s发送，末位到达时间约？',['2.015 s','0.015 s','2.15 s','0.5 s'],0,'发送2 s+传播0.015 s。'),C(3,'两个链路单程分别20 ms、200 ms，文件发送均1 s，第一比第二末位到达早？',['180 ms','10 ms','1 s','220 ms'],0,'发送时间同，时延差180 ms。'),T(3,'光纤往返时间0.02 s，v=2×10⁸ m/s，单程光纤长度多少km？',['2000'],'s=vt/2=2e6 m=2000 km。'),C(3,'偏远山区短期救援需尽快接网，已有可用卫星终端，选择依据较合理的是？',['综合部署时间与覆盖，并接受相应时延','所有情况卫星必优','光纤无任何优点','只比较外观'],0,'情境约束影响方案。'),K('A方案光纤总长1000 km，v=2×10⁸ m/s；B方案经卫星单程总路程60000 km，v=3×10⁸ m/s，忽略处理。',[['A单程传播时延多少ms？',['5']],['B单程传播时延多少ms？',['200']],['B比A的纯传播往返时延多多少ms？',['390']]],'A5 ms，B200 ms，单程差195 ms，往返差390 ms。')],waveVisual('fiber'));
unit(22,'能源与可持续发展','从能量账本转向能源选择，评价新能源并设计可验证的节能方案。');
add('p22-1','能源利用的现状和面临的挑战','区分一次二次、可再生不可再生能源，结合效率和环境分析利用问题。',['能提供能量的物质资源或自然过程可称能源，能源与能量概念需区分。','煤、石油、天然气等化石能源形成周期很长，属于不可再生能源。','太阳能、风能、水能等在一定尺度上可持续获得，常归入可再生能源。','电能通常是由其他能源转化获得的二次能源，清洁程度与来源有关。','能源利用需同时考虑供应、效率、环境影响和获取条件，能量守恒不意味着无需节约。'],'电器使用处没有燃烧不等于全链条零排放；可再生也不等于任何地方任何时刻无限可用。',[
'能源是能够向人类活动提供能量的资源或自然过程，能量则是物理学中描述做功和变化能力的量。煤、油、天然气提供化学能，阳光提供辐射能，流水与风可提供机械能。人们常先把一次能源转化为电能等便于输送使用的形式，这些经转换获得的能源称二次能源。',
'从人类社会时间尺度看，化石燃料形成极其缓慢，用掉后很难短期补充，因此属于不可再生能源。太阳、风、水循环等能持续提供输入，通常归为可再生能源。但某地无风或夜间无阳光仍影响实时供应，需要储能、联网或其他供能方式协调，可再生不表示随时随地都有相同输出。',
'评价能源利用先画完整链条：开采或获取、加工、运输、转换、最终服务。某一环节看似无排放，不代表全部环节没有环境影响。例如电动设备使用端不直接燃烧化石燃料，但发电结构、制造和回收仍会影响全生命周期结果。初中题用给定数据分析，避免没有边界条件的绝对比较。',
'某燃料输入能量100 MJ，发电环节效率40%，输配电保留95%，设备有效利用率80%，最终有用能量100×0.40×0.95×0.80=30.4 MJ。各环节效率不是直接相加，必须连乘。若提高最后一环节到90%，最终变34.2 MJ，可定量看出技术改进收益。',
'能源挑战包括资源可获取性、供需匹配、污染和气候影响、转换损耗、基础设施与经济成本等。不同方案有不同约束，不能只用一次效率就断言适合所有场景。改善效率、减少无效需求、发展适合当地条件的能源和完善储存传输设施，可以共同减少资源消耗和环境负担。',
'能量守恒说总量不消失，但很多使用后的能量分散到环境，难以重新集中成有用输出，因此仍需节约能源。调查家庭或学校能耗时，要区分能源种类和最后提供的服务，以相同照明、室温或运输任务作为比较基准。真实数据不足时给出范围和假设，比写一个貌似精确却无依据的排名更可靠。'
],[C(1,'属于化石能源的是？',['天然气','风','阳光','潮汐'],0,'煤油气为典型化石能源。'),C(1,'电能通常属于？',['二次能源','永远一次能源','物质质量单位','不可测量能源'],0,'常由其他能源转换获得。'),C(1,'通常属于可再生能源的是？',['风能','煤','石油','天然气'],0,'风可由自然过程持续形成。'),C(1,'能量守恒意味着？',['不用节约','总能量不消失但可用性会变化','所有资源无限','所有能量自动回收'],1,'数量守恒不等于便于再利用。'),M(2,'能源评价应考虑？',['供应条件','转换效率','环境影响','只看使用端是否冒烟'],[0,1,2],'需要合理系统边界。'),M(2,'正确的有？',['化石能源人类尺度难以快速补充','可再生供能也可波动','电的来源影响环境评价','电能一定全链条零排放'],[0,1,2],'不能一概而论。'),T(2,'输入100 MJ、有效输出40 MJ，效率多少？',['40%'],'40/100。'),T(2,'设备提供20 MJ有用能量，效率50%，输入多少MJ？',['40'],'20/0.5=40。'),C(2,'太阳能夜间直接输出下降，说明？',['可再生定义错误','供应具有时间条件','太阳能不可再生','能量不守恒'],1,'再生性与实时可用性不同。'),C(2,'比较运输方案应尽量固定？',['运输距离和载荷','只固定颜色','任意任务','所有品牌相同'],0,'以相同服务为基准。'),C(3,'100 MJ经40%发电、90%输送、80%利用，最终有用？',['28.8 MJ','210 MJ','32 MJ','36 MJ'],0,'100×0.4×0.9×0.8=28.8。'),C(3,'完成同任务甲效率25%、乙40%，同热值燃料，乙耗量为甲多少？',['62.5%','160%','15%','40%'],0,'耗量与效率反比，25/40=0.625。'),C(3,'方案本地无排放但上游需高耗能制造，评价应？',['纳入制造及能源来源边界','直接认定零影响','只看颜色','忽略上游一切'],0,'全链条条件影响比较。'),T(3,'有用需求60 MJ，转换效率30%、输送保留80%，初始能源需多少MJ？',['250'],'60/(0.3×0.8)=250。'),C(3,'设备效率由50%提升至60%，同任务输入能量减少比例约？',['16.7%','10%','20%','50%'],0,'原W/0.5，新W/0.6，减少1−0.5/0.6=16.7%。'),K('某系统输入化学能200 MJ，发电效率40%，输电损失发出电能的5%，终端有效利用80%。',[['发出电能多少MJ？',['80']],['到达终端电能多少MJ？',['76']],['最终有用能量多少MJ？',['60.8']]],'200×0.4=80；80×0.95=76；76×0.8=60.8。')],V('能源利用：每一环都影响最终结果',rect(40,72,670,42,'#d7a47b')+text(51,101,'一次能源输入 100 MJ')+rect(40,138,268,42,'#89bcae')+text(325,167,'发电后 40 MJ')+rect(40,204,255,42,'#68a592')+text(315,233,'输送后 38 MJ')+rect(40,270,204,37,'#337c68')+text(265,295,'终端有用 30.4 MJ',18),'示例依次采用40%、95%、80%的保留比例；有用能量=输入×各环节效率。'));
add('p22-2','新能源的发展','认识太阳能、风能、核能、氢能和储能，比较技术条件。',['太阳能可通过光伏发电，也可通过集热利用热能，两种方式应区分。','风电、水电等先获取机械能，再经发电机转为电能。','核裂变和核聚变都能释放核能；现有常规核电主要利用可控核裂变。','氢能常作为能量载体，制氢需要能量，其环境表现与制取路径有关。','新能源系统需要考虑储能、调度、资源条件、成本和全生命周期影响。'],'核能不属于燃烧的化学能；氢不是凭空出现的免费能源，光伏和太阳能热水器原理不同。',[
'新能源的发展为能源利用提供更多选择，但不同技术的原理与条件不同。太阳能光伏把光能直接转换为电能，太阳能集热利用吸收辐射使物体升温，风力和水力则先获得机械能再通过发电机转电。用同一个“太阳能设备”名称概括所有结构，会掩盖其输出形式和效率定义差异。',
'核能来自原子核的变化，核裂变是较重的核分裂成较轻的核并释放能量，核聚变是轻核结合成较重核并释放能量。现有常规核电主要使用可控裂变产生热，再经蒸汽系统和发电机发电。它与煤燃烧在微观能量来源上不同，也需要考虑安全控制、材料和废物管理等技术条件。',
'氢可以储存和转移能量，但制氢通常先消耗其他能源。评价氢能要追问氢从哪里来、如何储运、最后如何转化为有用能量。电池储能同样是把输入电能暂存为其他形式再释放，不会凭空增加能量。充放电、运输和转换各环节都有保留比例，综合效率应按链条相乘。',
'一块面积2 m²的光伏板，题设辐照功率密度800 W/m²、转换效率20%，电输出功率为2×800×0.20=320 W。若保持该条件5 h，电能1.6 kW·h。这里是假定稳定照射和效率的计算模型，实际天气、角度、温度和遮挡会使全天输出变化。',
'风光发电具有随资源条件波动的特点，储能与电网调度可把不同时间、地区的供需连接起来。核电等系统也有自身的运行和维护要求，没有一种能源在所有地点、任务和时间都绝对最佳。选择需同时衡量资源可用性、输出稳定性、转换效率、建设成本和环境影响。',
'科学阅读新能源宣传时，区分实验室单次最高效率、工程平均效率和整个系统效率。给出一个“90%”要问分子分母是什么、边界在哪里；若一段效率高但储运损耗大，全链条结果可能不同。用明确数据做条件化比较，比凭名称判断“新能源必无污染、必便宜”更有科学依据。'
],[C(1,'光伏板主要转化？',['光能→电能','电能→光能','核能→机械能','声能→化学能'],0,'光伏电输出。'),C(1,'太阳能热水器主要利用？',['辐射加热','核聚变在水箱发生','摩擦起电','磁生电唯一'],0,'吸收太阳辐射转为内能。'),C(1,'常规核电主要利用？',['可控核裂变','普通燃烧','永久磁体耗尽','目前所有都是聚变'],0,'区别裂变和聚变。'),C(1,'电池储能意味着？',['存储并释放能量','创造能量','无任何损耗','可无限供能'],0,'遵守能量守恒。'),M(2,'合理认识有？',['制氢需要能量来源','风电依赖风资源','光伏与集热不同','核能就是化学燃烧'],[0,1,2],'核能来自核变化。'),M(2,'比较新能源应考虑？',['当地资源','储运转换损耗','输出与需求匹配','只凭名称判断零影响'],[0,1,2],'系统边界很重要。'),T(2,'1 m²板接收1000 W/m²，效率20%，输出多少W？',['200'],'面积×辐照功率密度×效率。'),T(2,'输入电能10 kW·h，储放效率80%，放出多少kW·h？',['8'],'10×0.8=8。'),C(2,'风电主要能量链？',['风机械能→电能','电能→风','太阳光直接变电流不需机构','核能→光'],0,'风推动机组发电。'),C(2,'氢能使用端产物较少污染，能否据此断定全链零影响？',['能','不能，需考虑制取与储运','氢不需制取','效率永为100%'],1,'系统边界不能遗漏。'),C(3,'2 m²光伏、800 W/m²、效率20%、5 h稳定照射，电量？',['1.6度','8度','0.32度','16度'],0,'P320 W，5 h=1.6度。'),C(3,'电解制氢效率70%、储运90%、燃料电池50%，电到电综合效率？',['31.5%','210%','63%','35%'],0,'0.7×0.9×0.5=31.5%。'),C(3,'满足夜间8度电需求，储能充放总效率80%，白天需至少存入多少度？',['10','8','6.4','16'],0,'8/0.8=10度，忽略其他损耗。'),T(3,'光伏输出400 W，其中100 W即时使用，剩余连续4 h充电，充放效率75%，后续可放多少度？',['0.9'],'余0.3 kW×4=1.2度，×0.75=0.9。'),C(3,'两板相同面积、同效率，甲处日有效照射时间是乙2倍，其日发电量在其他条件相同时？',['2倍','相同','1/2','4倍'],0,'功率相同、时间倍增，能量倍增。'),K('一套光伏系统面积5 m²，辐照600 W/m²，转换效率20%，稳定4 h；全部电能进储能，充放总效率80%。',[['光伏电功率多少W？',['600']],['光伏这段发电多少度？',['2.4']],['储能后可提供多少度？',['1.92']]],'5×600×0.2=600 W；0.6×4=2.4度；2.4×0.8=1.92度。')],V('太阳能两种路径：光伏与集热',`<circle cx="101" cy="150" r="44" fill="#efcb75"/>`+text(64,157,'太阳',25)+arrow(160,138,268,89)+arrow(160,169,268,235)+rect(283,43,246,83)+text(324,80,'光伏电池')+text(334,107,'光能 → 电能',17)+rect(283,195,246,83)+text(324,232,'集热装置')+text(334,259,'光能 → 内能',17)+arrow(539,86,689,86)+arrow(539,235,689,235)+text(585,63,'供电')+text(585,212,'热水'),'新能源系统需说明输入、输出和效率边界；光伏电量与光照面积、强度、时间及效率有关。'));
add('p22-3','跨学科实践：为节约能源设计方案','为保温或家庭交通建立公平比较，用数据检验节能效果。',['实践包含提出问题、调查测量、设计方案、检验效果和交流改进。','建筑保温通过减缓热传递减少维持温差所需能量；比较时固定初温、面积和环境。','交通比较要保持行程、载荷等服务条件一致，把能量单位统一后比较。','节能率=(基准能耗−方案能耗)/基准能耗，回收期需依据净节省费用计算。','综合考虑实施成本、材料寿命、舒适性与环境，不把短时试验无限推广。'],'减少温降不代表产生热量；保温材料主要减缓能量转移，不能凭空使室温上升。',[
'为节约能源设计方案要求从一个具体需求出发，例如减少房间冬季散热，或为同样出行任务选择较低能耗方式。先记录当前做法和能耗作为基准，再提出可实施改进，说明为什么预期节能。方案不应只写“少用能源”口号，而要有可以测量的指标、明确条件以及检验安排。',
'保温模型可用相同容器装相同质量温水，在外部包不同材料，同时记录一段时间后的温度。初温、环境温度、容器尺寸、材料厚度和测量位置需要控制。保温材料减缓热传递，所以温降较小并不表示材料制造了热量，而是同一时间向外转移的能量较少。',
'交通比较可以使用给定油耗、电耗和行驶里程，先把每百公里输入能量统一为MJ或kW·h，再比较。若讨论费用，还要明确油价电价为题设假设；若讨论环境，需要额外考虑能源来源、制造与使用寿命，不能从单次用车电费较低直接推出所有环境指标都最优。',
'模型房间原来维持温差每小时需600 kJ，改进后450 kJ，节能率(600−450)/600=25%。每天相同条件维持8 h，节能1200 kJ，约0.333 kW·h。若改进成本、使用期和能源价格已给，还可估算回收时间；真实建筑会受天气和使用方式影响，模型数据不直接当作全年精确值。',
'比较数据时要区分相关与因果。改造后一周耗电变少，如果那一周本来更暖或人更少，不能把下降全部归因保温材料。可以选择相近天气时段、同时设置对照模型，或按单位温差、单位服务量进一步整理。多次测量保留波动，报告不仅给平均节省，也说明无法控制的因素。',
'最终方案列出目标、措施、预算、预期收益、验证数据和调整方向。材料选择要兼顾耐用、健康、可回收与实施条件，不单看保温一次实验中的排名。交通建议也要考虑可达性和时间需求。可在纸面、低温模型和正常使用调查中完成，不拆改燃气或电力设施，以科学证据支持可持续的日常选择。'
],[C(1,'制定节能方案先要？',['建立当前能耗基准','立即买最贵设备','不测直接宣传','忽略服务需求'],0,'先知道原来消耗多少。'),C(1,'保温材料主要作用？',['减缓热传递','创造热量','让能量消失','完全停止分子运动'],0,'降低传热速度。'),C(1,'节能率分母为？',['基准能耗','节省量','方案成本','使用时间必然'],0,'相对原基准求减少比例。'),C(1,'交通能耗比较需尽量相同？',['行程和载荷等任务','车型颜色','任何条件随意','只看价格标签'],0,'固定服务需求。'),M(2,'保温实验应控制？',['温水质量与初温','环境温度','容器与测量时长','同时任意改变材料厚度和容器'],[0,1,2],'单因素研究只改变目标因素。'),M(2,'方案评价可包括？',['净节能','成本与寿命','舒适性及可实施性','仅凭口号'],[0,1,2],'需多指标。'),T(2,'原耗1000 J、改后800 J，节能率多少？',['20%'],'减少200/1000=20%。'),T(2,'节省3600 kJ等于多少度电？',['1'],'3600 kJ=3.6×10⁶ J。'),C(2,'保温杯水温降小，说明？',['同时间散热较少','杯子发明能源','水不含内能','热量凭空增加'],0,'保温减慢散热。'),C(2,'改造后天气更暖，能耗下降，结论应？',['全部归功改造','考虑天气干扰','一定改造无效','数据无任何价值'],1,'需区分影响因素。'),C(3,'原每小时600 kJ、改450 kJ，每天8 h，节能率与每日节能为？',['25%、1200 kJ','75%、3600 kJ','25%、150 kJ','20%、1200 kJ'],0,'差150/600=25%，×8=1200。'),C(3,'燃油车每100 km耗2.0×10⁸ J，电车耗15度，同任务电车输入能量为燃油车约？',['27%','75%','54%','15%'],0,'15×3.6e6=5.4e7，除2e8=27%；不含上游。'),C(3,'改造成本300元，每月毛省30元、维护增5元，简单回收期？',['12个月','10个月','15个月','6个月'],0,'净省25元，300/25=12。'),T(3,'原年能耗1200度，措施先省20%，在剩余基础再省10%，最终年能耗多少度？',['864'],'1200×0.8×0.9=864，不能直接减30%。'),C(3,'两种保温材料A温降2℃、B温降4℃，但A水量是B两倍，能断A更好？',['能，温降直接比','不能，质量不同影响温降','B一定好','能量不守恒'],1,'同Q时质量大温降小，实验未控制质量。'),K('同样服务需求，基准每日耗能5度，方案每日3.5度。每年使用200天，题设能源价格0.6元/度，改造成本360元，无新增维护。',[['每日节能率多少？',['30%']],['每年节省费用多少元？',['180']],['简单回收期多少年？',['2']]],'节1.5/5=30%；年节300度，省180元；360/180=2年。')],V('节能测试：同条件、有对照',rect(67,95,265,145,'#e1ebdf')+text(96,130,'对照模型')+text(91,167,'同质量水、同初温')+text(93,208,'记录温降 Δt₁')+rect(427,95,265,145,'#c9e1d6')+text(456,130,'改进模型')+text(451,167,'只改变保温方案')+text(452,208,'记录温降 Δt₂')+text(128,291,'相同环境、相同时长，重复测量后再解释差异',19),'如果质量、初温或环境改变，温降差异不能唯一归因保温材料。数据与控制条件应一起报告。'));
// 教学图补充：比较两种连接，显示伏安法的完整接线关系。
function compareCircuits(title,caption){const left=circuitVisual('series').svg,right=circuitVisual('parallel').svg;return {title,svg:`<svg class="lesson-diagram" viewBox="0 0 760 430" role="img" aria-label="${esc(title)}"><rect width="760" height="430" rx="18" fill="#f6faf7"/>${text(28,36,'串联：同一条路径',22)}${text(405,36,'并联：两条独立支路',22)}<svg x="0" y="52" width="375" height="275" viewBox="0 0 760 330">${left.slice(left.indexOf('>')+1,left.lastIndexOf('</svg>'))}</svg><svg x="385" y="52" width="375" height="275" viewBox="0 0 760 330">${right.slice(right.indexOf('>')+1,right.lastIndexOf('</svg>'))}</svg>${text(52,354,'I = I₁ = I₂',23)}${text(426,354,'I = I₁ + I₂',23)}${text(52,397,'U = U₁ + U₂',21)}${text(426,397,'U = U₁ = U₂',21)}</svg>`,caption};}
function measurementCircuit(lamp=false){
 const name=lamp?'小灯泡L':'被测电阻R';
 let a=line(75,100,124,100)+line(124,100,159,100)+`<circle cx="124" cy="100" r="4" fill="#396b64"/><circle cx="159" cy="100" r="4" fill="#396b64"/>`+text(108,68,'S',18)+line(159,100,202,100)+line(258,100,290,100)+`<circle cx="230" cy="100" r="28" fill="white" stroke="#396b64" stroke-width="3"/>`+text(220,108,'A',24)+text(193,74,'+',16)+text(263,74,'−',16);
 a+=lamp?line(290,100,326,100)+`<circle cx="354" cy="100" r="28" fill="white" stroke="#396b64" stroke-width="3"/>`+line(335,81,373,119)+line(373,81,335,119)+line(382,100,420,100)+text(329,52,'灯L',18):resistor(320,100,'R');
 a+=line(420,100,470,100)+resistor(500,100,'R滑')+line(600,100,685,100)+arrow(561,56,527,122,'#bd8158')+line(75,100,75,283)+line(685,100,685,283)+line(75,283,344,283)+battery(379,283)+line(419,283,685,283);
 a+=line(290,100,290,193)+line(290,193,326,193)+line(382,193,420,193)+line(420,193,420,100)+`<circle cx="354" cy="193" r="28" fill="white" stroke="#396b64" stroke-width="3"/>`+text(344,201,'V',24)+text(305,226,'+',16)+text(394,226,'−',16)+`<circle cx="290" cy="100" r="5" fill="#396b64"/><circle cx="420" cy="100" r="5" fill="#396b64"/>`;
 a+=text(46,250,'A串联测通过元件的电流；V仅跨被测元件两端',17);
 return V(lamp?'测小灯泡电功率的完整电路':'伏安法测电阻的完整电路',a,`图中开关为测量时的闭合状态，接线与改接前须断开。滑动变阻器用标准可变电阻符号串联接入；电流表串联，电压表只跨${name}。${lamp?'调至额定电压后读I，P=UI。':'同一工作点用R=U/I计算。'}`);
}
