improve('p15-3',13,{...C(3,'图中两电阻并联在稳定电源上。若先把R₁支路断开，之后恢复R₁再用理想导线跨接R₁，两种操作对R₂的影响分别是？',['第一次通常不影响；第二次可能短接整个电源','两次都只影响R₁','两次都使R₂正常更亮','第一次电源必短路；第二次安全'],0,'正常断开一支路不破坏另一支路供电；把并联支路直接短接则把共同两节点短接，会影响整个电源。独立工作不包括任意短路故障。'),diagram:circuitVisual('parallel').svg});
