improve('p15-3',15,C(3,'报警器只在总使能S闭合，且门开关A或窗开关B至少一个闭合时响。满足逻辑且不短接电源的连接是？',['A、B并联后，与S和报警器串联','A、B、S全部串联再接报警器','S、A、B全部并联后跨接电源','报警器与S并联且其余任意'],0,'A或B触发对应并联，必须S使能对应再串联。全部串联会要求门窗同时触发，不满足“至少一个”。'));
// 题目按ID确定固定排列，刷新与错题重练位置保持一致，同时同步映射正确索引。
for(const lesson of physicsUnits9.flatMap(u=>u.lessons)){
 for(const q of lesson.questions){
  if(!q.options)continue;
  let seed=2166136261;
  for(const char of q.id)seed=Math.imul(seed^char.charCodeAt(0),16777619)>>>0;
  const order=q.options.map((_,i)=>i);
  for(let i=order.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[order[i],order[j]]=[order[j],order[i]];}
  const previous=q.options;q.options=order.map(i=>previous[i]);
  if(q.type==='choice')q.answer=order.indexOf(q.answer);
  if(q.type==='multi')q.answers=q.answers.map(i=>order.indexOf(i)).sort((a,b)=>a-b);
 }
}
